import { useState, useEffect, useRef, useCallback } from 'react';
import { Search, X, ChevronRight, AlertCircle, Activity, Users, CreditCard, Globe, Building2, MapPin, Calendar, Hash } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import api from '../api/axios';

const ENTITY_CONFIG = [
  {
    key: 'infractions',
    endpoint: '/infractions',
    label: 'Infractions',
    icon: AlertCircle,
    color: 'text-[#D97706]',
    route: '/infractions',
    getLabel: (item) => item.type_infraction?.nom || `Infraction #${item.id}`,
    getSub: (item) => [item.commune?.nom, item.lieu].filter(Boolean).join(' — ') || '',
    getPreview: (item) => ({
      title: item.type_infraction?.nom || `Infraction #${item.id}`,
      status: item.statut,
      location: [item.commune?.nom, item.region?.nom].filter(Boolean).join(', ') || item.lieu || '—',
      date: item.date_infraction || item.created_at,
    }),
  },
  {
    key: 'accidents',
    endpoint: '/accidents',
    label: 'Accidents',
    icon: Activity,
    color: 'text-[#DC2626]',
    route: '/accidents',
    getLabel: (item) => `Accident ${item.type || ''} #${item.id}`,
    getSub: (item) => [item.commune?.nom, item.lieu].filter(Boolean).join(' — ') || '',
    getPreview: (item) => ({
      title: `Accident #${item.id}`,
      status: item.gravite,
      location: [item.commune?.nom, item.region?.nom].filter(Boolean).join(', ') || item.lieu || '—',
      date: item.date_accident || item.created_at,
    }),
  },
  {
    key: 'personnels',
    endpoint: '/personnels',
    label: 'Personnel',
    icon: Users,
    color: 'text-[#2563EB]',
    route: '/personnel',
    getLabel: (item) => `${item.prenom || ''} ${item.nom || ''}`.trim() || `Agent #${item.id}`,
    getSub: (item) => [item.grade, item.service?.nom].filter(Boolean).join(' · ') || '',
    getPreview: (item) => ({
      title: `${item.prenom || ''} ${item.nom || ''}`.trim() || `Agent #${item.id}`,
      status: item.statut,
      location: item.service?.nom || '—',
      date: item.date_integration || item.created_at,
      extra: item.grade ? `Grade : ${item.grade}` : null,
    }),
  },
  {
    key: 'victimes',
    endpoint: '/victimes',
    label: 'Victimes',
    icon: Users,
    color: 'text-[#64748B]',
    route: '/victimes',
    getLabel: (item) => `${item.prenom || ''} ${item.nom || ''}`.trim() || `Victime #${item.id}`,
    getSub: (item) => [item.nationalite, item.no_cin_passeport].filter(Boolean).join(' · ') || '',
    getPreview: (item) => ({
      title: `${item.prenom || ''} ${item.nom || ''}`.trim() || `Victime #${item.id}`,
      status: item.type_victime,
      location: item.commune?.nom || '—',
      date: item.created_at,
      extra: item.no_cin_passeport ? `CIN/Passeport : ${item.no_cin_passeport}` : null,
    }),
  },
  {
    key: 'amendes',
    endpoint: '/amendes-pieces-saisies',
    label: 'Amendes',
    icon: CreditCard,
    color: 'text-[#16A34A]',
    route: '/amendes',
    getLabel: (item) => `${item.type || 'Amende'} #${item.id}`,
    getSub: (item) => item.montant ? `${Number(item.montant).toLocaleString('fr-FR')} FCFA` : '',
    getPreview: (item) => ({
      title: `${item.type || 'Amende'} #${item.id}`,
      status: item.statut,
      location: item.commune?.nom || item.region?.nom || '—',
      date: item.date_emission || item.created_at,
      extra: item.montant ? `Montant : ${Number(item.montant).toLocaleString('fr-FR')} FCFA` : null,
    }),
  },
  {
    key: 'immigrations',
    endpoint: '/immigrations-clandestines',
    label: 'Immigration',
    icon: Globe,
    color: 'text-[#7C3AED]',
    route: '/immigration',
    getLabel: (item) => `Dossier #${item.id}`,
    getSub: (item) => [item.zone_depart, item.zone_arrivee].filter(Boolean).join(' → ') || '',
    getPreview: (item) => ({
      title: `Dossier immigration #${item.id}`,
      status: item.statut,
      location: [item.zone_depart, item.zone_arrivee].filter(Boolean).join(' → ') || '—',
      date: item.date_interception || item.created_at,
      extra: item.nationalite ? `Nationalité : ${item.nationalite}` : null,
    }),
  },
  {
    key: 'services',
    endpoint: '/services',
    label: 'Commissariats',
    icon: Building2,
    color: 'text-[#0891B2]',
    route: '/personnel',
    getLabel: (item) => item.nom || `Service #${item.id}`,
    getSub: (item) => [item.code, item.region?.nom].filter(Boolean).join(' · ') || '',
    getPreview: (item) => ({
      title: item.nom || `Service #${item.id}`,
      status: item.type,
      location: [item.commune?.nom, item.region?.nom].filter(Boolean).join(', ') || '—',
      date: item.created_at,
      extra: item.code ? `Code : ${item.code}` : null,
    }),
  },
  {
    key: 'users',
    endpoint: '/users',
    label: 'Utilisateurs',
    icon: Users,
    color: 'text-[#E11D48]',
    route: '/utilisateurs',
    getLabel: (item) => item.name || `Utilisateur #${item.id}`,
    getSub: (item) => [item.email, item.role].filter(Boolean).join(' · ') || '',
    getPreview: (item) => ({
      title: item.name || `Utilisateur #${item.id}`,
      status: item.role,
      location: item.service?.nom || '—',
      date: item.created_at,
      extra: item.email || null,
    }),
  },
];

function QuickPreview({ preview }) {
  if (!preview) return null;
  const fmt = (d) => d ? new Date(d).toLocaleDateString('fr-FR') : '—';
  return (
    <div className="absolute left-full top-0 ml-2 w-52 bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/10 rounded-xl shadow-xl p-3 z-10 pointer-events-none">
      <p className="text-xs font-bold text-[#0F172A] dark:text-white truncate mb-2">{preview.title}</p>
      <div className="space-y-1">
        {preview.status && (
          <div className="flex items-center gap-1.5 text-[10px] text-[#64748B] dark:text-white/40">
            <Hash className="w-3 h-3 shrink-0" />
            <span className="truncate capitalize">{preview.status}</span>
          </div>
        )}
        <div className="flex items-center gap-1.5 text-[10px] text-[#64748B] dark:text-white/40">
          <MapPin className="w-3 h-3 shrink-0" />
          <span className="truncate">{preview.location}</span>
        </div>
        <div className="flex items-center gap-1.5 text-[10px] text-[#64748B] dark:text-white/40">
          <Calendar className="w-3 h-3 shrink-0" />
          <span>{fmt(preview.date)}</span>
        </div>
        {preview.extra && (
          <div className="flex items-center gap-1.5 text-[10px] text-[#94A3B8] dark:text-white/30">
            <ChevronRight className="w-3 h-3 shrink-0" />
            <span className="truncate">{preview.extra}</span>
          </div>
        )}
      </div>
    </div>
  );
}

export default function GlobalSearchBar() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState({});
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [hoveredItem, setHoveredItem] = useState(null); // { cfg, item }
  const inputRef = useRef(null);
  const containerRef = useRef(null);
  const navigate = useNavigate();
  const debounceRef = useRef(null);

  useEffect(() => {
    const handler = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        inputRef.current?.focus();
        setIsOpen(true);
      }
      if (e.key === 'Escape') {
        setIsOpen(false);
        inputRef.current?.blur();
      }
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, []);

  useEffect(() => {
    const handler = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) setIsOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const doSearch = useCallback(async (q) => {
    if (!q || q.length < 2) { setResults({}); setLoading(false); return; }
    setLoading(true);
    try {
      const responses = await Promise.allSettled(
        ENTITY_CONFIG.map(cfg => api.get(cfg.endpoint, { params: { search: q, per_page: 4 } }))
      );
      const newResults = {};
      responses.forEach((res, i) => {
        if (res.status === 'fulfilled') {
          const raw = res.value.data;
          const items = Array.isArray(raw) ? raw : (Array.isArray(raw?.data) ? raw.data : []);
          if (items.length > 0) newResults[ENTITY_CONFIG[i].key] = items.slice(0, 4);
        }
      });
      setResults(newResults);
    } catch {
      setResults({});
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!query.trim() || query.trim().length < 2) { setResults({}); setLoading(false); return; }
    setLoading(true);
    debounceRef.current = setTimeout(() => doSearch(query.trim()), 350);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [query, doSearch]);

  const handleNavigate = (route) => {
    navigate(route);
    setQuery('');
    setResults({});
    setIsOpen(false);
    setHoveredItem(null);
  };

  const hasResults = Object.keys(results).length > 0;
  const totalResults = Object.values(results).reduce((sum, arr) => sum + arr.length, 0);

  return (
    <div className="relative flex-1 max-w-md" ref={containerRef}>
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={e => { setQuery(e.target.value); setIsOpen(true); }}
          onFocus={() => setIsOpen(true)}
          placeholder="Recherche intelligente…"
          className="w-full h-8 pl-9 pr-10 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-md text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all"
        />
        {query ? (
          <button
            onClick={() => { setQuery(''); setResults({}); setHoveredItem(null); }}
            className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[#94A3B8] hover:text-[#475569] dark:hover:text-white/60 transition-colors"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        ) : (
          <kbd className="absolute right-2.5 top-1/2 -translate-y-1/2 hidden sm:inline-flex items-center h-5 px-1.5 text-[10px] font-medium text-[#94A3B8] dark:text-white/30 bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded">
            ⌘K
          </kbd>
        )}
      </div>

      {isOpen && query.length >= 2 && (
        <div className="absolute top-full mt-1.5 left-0 right-0 bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/10 rounded-xl shadow-xl shadow-black/10 z-50 overflow-hidden">
          {loading && (
            <div className="px-4 py-3 flex items-center gap-2 text-xs text-[#94A3B8] dark:text-white/40">
              <div className="w-3 h-3 border border-[#2563EB] border-t-transparent rounded-full animate-spin shrink-0" />
              Recherche en cours…
            </div>
          )}
          {!loading && !hasResults && (
            <div className="px-4 py-6 text-center">
              <p className="text-sm text-[#94A3B8] dark:text-white/30">Aucun résultat pour « {query} »</p>
              <p className="text-xs text-[#CBD5E1] dark:text-white/20 mt-1">Essayez un autre terme ou vérifiez l'orthographe</p>
            </div>
          )}
          {!loading && hasResults && (
            <div className="max-h-96 overflow-y-auto">
              {ENTITY_CONFIG.map(cfg => {
                const items = results[cfg.key];
                if (!items?.length) return null;
                const Icon = cfg.icon;
                return (
                  <div key={cfg.key}>
                    <div className="px-3 py-1.5 bg-[#F8FAFC] dark:bg-white/3 border-b border-[#F1F5F9] dark:border-white/5 flex items-center gap-1.5">
                      <Icon className={`w-3 h-3 ${cfg.color}`} />
                      <p className="text-[10px] font-bold text-[#94A3B8] dark:text-white/30 uppercase tracking-wider">
                        {cfg.label}
                      </p>
                    </div>
                    {items.map(item => {
                      const isHovered = hoveredItem?.cfg.key === cfg.key && hoveredItem?.item.id === item.id;
                      return (
                        <div
                          key={item.id}
                          className="relative"
                          onMouseEnter={() => setHoveredItem({ cfg, item })}
                          onMouseLeave={() => setHoveredItem(null)}
                        >
                          <button
                            onClick={() => handleNavigate(cfg.route)}
                            className="w-full flex items-center justify-between px-4 py-2.5 hover:bg-[#F8FAFC] dark:hover:bg-white/5 transition-colors text-left group"
                          >
                            <div className="min-w-0 flex-1">
                              <p className="text-xs font-semibold text-[#0F172A] dark:text-white truncate">{cfg.getLabel(item)}</p>
                              {cfg.getSub(item) && (
                                <p className="text-[10px] text-[#94A3B8] dark:text-white/40 truncate mt-0.5">{cfg.getSub(item)}</p>
                              )}
                            </div>
                            <ChevronRight className="w-3.5 h-3.5 text-[#CBD5E1] dark:text-white/20 shrink-0 ml-2 group-hover:text-[#94A3B8] dark:group-hover:text-white/40 transition-colors" />
                          </button>
                          {isHovered && cfg.getPreview && (
                            <QuickPreview preview={cfg.getPreview(item)} />
                          )}
                        </div>
                      );
                    })}
                  </div>
                );
              })}
              <div className="px-4 py-2 border-t border-[#F1F5F9] dark:border-white/5 text-[10px] text-[#94A3B8] dark:text-white/30 text-right">
                {totalResults} résultat{totalResults > 1 ? 's' : ''} trouvé{totalResults > 1 ? 's' : ''}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet.heat';

/**
 * Couche heatmap pour React Leaflet.
 * Props:
 *   points  — array de [lat, lng, intensity?]
 *   options — options leaflet.heat (radius, blur, maxZoom, gradient)
 */
export default function HeatmapLayer({ points = [], options = {} }) {
  const map = useMap();
  const heatRef = useRef(null);

  useEffect(() => {
    if (!points.length) return;

    const defaultOptions = {
      radius: 25,
      blur: 15,
      maxZoom: 17,
      gradient: { 0.2: '#3B82F6', 0.4: '#10B981', 0.6: '#F59E0B', 0.8: '#EF4444', 1.0: '#7C3AED' },
      ...options,
    };

    heatRef.current = L.heatLayer(points, defaultOptions).addTo(map);

    return () => {
      if (heatRef.current) {
        map.removeLayer(heatRef.current);
        heatRef.current = null;
      }
    };
  }, [points, map]);

  return null;
}

