import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Upload, X, Download, Trash2, FileText, Image,
  AlertCircle, Paperclip, Eye
} from 'lucide-react';
import mediaService from '../services/mediaService';

const ACCEPT = 'image/jpeg,image/png,image/gif,image/webp,application/pdf,.doc,.docx';

function FileIcon({ mimeType }) {
  if (mimeType?.startsWith('image/')) return <Image className="w-4 h-4 text-[#2563EB]" />;
  return <FileText className="w-4 h-4 text-[#D97706]" />;
}

/**
 * Composant réutilisable de gestion des médias.
 *
 * Props:
 *   entityType  — 'infractions' | 'accidents' | 'personnels' | 'victimes'
 *   entityId    — id de l'entité
 *   readOnly    — désactiver upload/suppression (optionnel)
 */
export default function MediaUpload({ entityType, entityId, readOnly = false }) {
  const [files, setFiles]         = useState([]);
  const [loading, setLoading]     = useState(false);
  const [uploading, setUploading] = useState(false);
  const [dragOver, setDragOver]   = useState(false);
  const [preview, setPreview]     = useState(null);
  const [toast, setToast]         = useState(null);
  const inputRef = useRef(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const loadFiles = async () => {
    if (!entityId) return;
    setLoading(true);
    try {
      const res = await mediaService.getAll(entityType, entityId);
      setFiles(res.data?.data || []);
    } catch {
      // silencieux si 0 media
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadFiles(); }, [entityType, entityId]);

  const handleUpload = async (fileList) => {
    if (!fileList?.length || readOnly) return;
    setUploading(true);
    try {
      await mediaService.upload(entityType, entityId, fileList);
      showToast(`${fileList.length} fichier(s) uploadé(s) avec succès`);
      await loadFiles();
    } catch (err) {
      showToast(err.response?.data?.message || 'Erreur lors de l\'upload', 'error');
    } finally {
      setUploading(false);
    }
  };

  const handleDelete = async (mediaId, filename) => {
    if (!window.confirm(`Supprimer "${filename}" ?`)) return;
    try {
      await mediaService.delete(mediaId);
      showToast('Fichier supprimé');
      setFiles(f => f.filter(x => x.id !== mediaId));
    } catch {
      showToast('Erreur lors de la suppression', 'error');
    }
  };

  const handleDownload = (file) => {
    mediaService.download(file.id, file.filename)
      .catch(() => showToast('Erreur lors du téléchargement', 'error'));
  };

  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    handleUpload(e.dataTransfer.files);
  };

  if (!entityId) return null;

  return (
    <div className="space-y-3">
      {/* Toast */}
      <AnimatePresence>
        {toast && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}
            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-medium text-white ${toast.type === 'error' ? 'bg-[#DC2626]' : 'bg-[#16A34A]'}`}>
            <AlertCircle className="w-3.5 h-3.5" />
            {toast.message}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Zone de dépôt */}
      {!readOnly && (
        <div
          onDragOver={e => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onDrop={onDrop}
          onClick={() => inputRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-4 text-center cursor-pointer transition-all ${
            dragOver
              ? 'border-[#2563EB] bg-[#EFF6FF] dark:bg-[#2563EB]/10'
              : 'border-[#E2E8F0] dark:border-white/15 hover:border-[#2563EB]/50 hover:bg-[#F8FAFC] dark:hover:bg-white/3'
          }`}
        >
          <input ref={inputRef} type="file" multiple accept={ACCEPT} className="hidden"
            onChange={e => handleUpload(e.target.files)} />
          {uploading ? (
            <div className="flex items-center justify-center gap-2 text-xs text-[#2563EB]">
              <div className="w-4 h-4 border-2 border-[#2563EB] border-t-transparent rounded-full animate-spin" />
              Upload en cours…
            </div>
          ) : (
            <div className="flex flex-col items-center gap-1.5">
              <Upload className="w-5 h-5 text-[#94A3B8]" />
              <p className="text-xs text-[#64748B] dark:text-white/50">
                Glisser-déposer ou <span className="text-[#2563EB] font-medium">parcourir</span>
              </p>
              <p className="text-[10px] text-[#94A3B8]">Images, PDF, Word — max 10 Mo par fichier</p>
            </div>
          )}
        </div>
      )}

      {/* Liste des fichiers */}
      {loading ? (
        <div className="space-y-2">
          {[...Array(2)].map((_, i) => (
            <div key={i} className="h-10 bg-[#F1F5F9] dark:bg-white/5 rounded-lg animate-pulse" />
          ))}
        </div>
      ) : files.length === 0 ? (
        <p className="text-xs text-[#94A3B8] dark:text-white/30 text-center py-2 flex items-center justify-center gap-1.5">
          <Paperclip className="w-3.5 h-3.5" /> Aucun fichier attaché
        </p>
      ) : (
        <div className="space-y-1.5">
          {files.map(file => (
            <div key={file.id}
              className="flex items-center gap-2.5 px-3 py-2 bg-[#F8FAFC] dark:bg-white/3 border border-[#E2E8F0] dark:border-white/8 rounded-lg group">
              <FileIcon mimeType={file.mime_type} />
              <div className="flex-1 min-w-0">
                <p className="text-xs font-medium text-[#0F172A] dark:text-white truncate">{file.filename}</p>
                <p className="text-[10px] text-[#94A3B8]">{file.size_human}</p>
              </div>
              <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                {file.is_image && (
                  <button onClick={() => setPreview(file)}
                    className="p-1 rounded hover:bg-[#EFF6FF] text-[#2563EB] transition-colors" title="Aperçu">
                    <Eye className="w-3.5 h-3.5" />
                  </button>
                )}
                <button onClick={() => handleDownload(file)}
                  className="p-1 rounded hover:bg-[#EFF6FF] text-[#2563EB] transition-colors" title="Télécharger">
                  <Download className="w-3.5 h-3.5" />
                </button>
                {!readOnly && (
                  <button onClick={() => handleDelete(file.id, file.filename)}
                    className="p-1 rounded hover:bg-[#FEF2F2] text-[#DC2626] transition-colors" title="Supprimer">
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal prévisualisation image */}
      <AnimatePresence>
        {preview && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-[9999] bg-black/80 flex items-center justify-center p-4"
            onClick={() => setPreview(null)}>
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} exit={{ scale: 0.9 }}
              onClick={e => e.stopPropagation()}
              className="relative max-w-3xl max-h-[90vh] bg-[#0F172A] rounded-xl overflow-hidden">
              <button onClick={() => setPreview(null)}
                className="absolute top-2 right-2 z-10 p-1.5 rounded-lg bg-black/50 hover:bg-black/70 text-white transition-colors">
                <X className="w-4 h-4" />
              </button>
              <img src={preview.url} alt={preview.filename}
                className="max-w-full max-h-[85vh] object-contain" />
              <p className="text-xs text-white/60 text-center py-2">{preview.filename} — {preview.size_human}</p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

const WORKFLOW_CONFIG = {
  'Brouillon':  { bg: 'bg-[#F1F5F9]', text: 'text-[#475569]', dot: 'bg-[#94A3B8]' },
  'En cours':   { bg: 'bg-[#EFF6FF]', text: 'text-[#2563EB]', dot: 'bg-[#2563EB]' },
  'Validé':     { bg: 'bg-[#F0FDF4]', text: 'text-[#16A34A]', dot: 'bg-[#16A34A]' },
  'Clôturé':    { bg: 'bg-[#FFF7ED]', text: 'text-[#D97706]', dot: 'bg-[#D97706]' },
  'Archivé':    { bg: 'bg-[#F9FAFB]', text: 'text-[#6B7280]', dot: 'bg-[#9CA3AF]' },
};

export const WORKFLOW_STATUTS = Object.keys(WORKFLOW_CONFIG);

/**
 * Badge affichant le statut workflow d'un dossier.
 * Props: status (string), size ('sm'|'md')
 */
export default function WorkflowBadge({ status, size = 'sm' }) {
  const cfg = WORKFLOW_CONFIG[status] || WORKFLOW_CONFIG['En cours'];
  const pad = size === 'md' ? 'px-3 py-1' : 'px-2 py-0.5';
  const txt = size === 'md' ? 'text-xs' : 'text-[10px]';

  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full font-semibold ${pad} ${txt} ${cfg.bg} ${cfg.text}`}>
      <span className={`w-1.5 h-1.5 rounded-full ${cfg.dot}`} />
      {status || 'En cours'}
    </span>
  );
}

/**
 * Sélecteur de statut workflow.
 * Props: value, onChange, className
 */
export function WorkflowSelect({ value, onChange, className = '' }) {
  return (
    <select
      value={value || 'En cours'}
      onChange={e => onChange(e.target.value)}
      className={`px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] ${className}`}
    >
      {WORKFLOW_STATUTS.map(s => (
        <option key={s} value={s}>{s}</option>
      ))}
    </select>
  );
}

import { useState, useRef, useEffect } from 'react';
import { Bell, LogOut, Menu, ChevronDown, PanelLeftClose, PanelLeftOpen, Sun, Moon, CheckCheck } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import notificationService from '../../services/notificationService';
import { mockNotifications } from '../../services/mockData';
import GlobalSearchBar from '../GlobalSearchBar';

export default function Topbar({ onToggleSidebar, collapsed, onToggleCollapse }) {
  const { user, logout } = useAuth();
  const { dark, toggle: toggleTheme } = useTheme();
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [notifOpen, setNotifOpen] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const dropdownRef = useRef(null);
  const notifRef = useRef(null);

  useEffect(() => {
    notificationService.getUnreadCount()
      .then(r => {
        const count = r.data?.count ?? r.data?.data?.count ?? 0;
        setUnreadCount(count > 0 ? count : 3);
      })
      .catch(() => setUnreadCount(3));
  }, []);

  useEffect(() => {
    if (!notifOpen) return;
    notificationService.getAll()
      .then(r => {
        const data = r.data?.data || r.data || [];
        setNotifications(Array.isArray(data) && data.length > 0 ? data : mockNotifications(6));
      })
      .catch(() => setNotifications(mockNotifications(6)));
  }, [notifOpen]);

  useEffect(() => {
    function handleClickOutside(event) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) setDropdownOpen(false);
      if (notifRef.current && !notifRef.current.contains(event.target)) setNotifOpen(false);
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleMarkAllRead = async () => {
    try {
      await notificationService.markAllAsRead();
      setUnreadCount(0);
      setNotifications(prev => prev.map(n => ({ ...n, read_at: new Date().toISOString() })));
    } catch {}
  };

  const handleMarkRead = async (id) => {
    try {
      await notificationService.markAsRead(id);
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n));
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch {}
  };

  const initials = user?.name
    ? user.name.split(' ').map(n => n[0]).slice(0, 2).join('').toUpperCase()
    : 'AG';

  return (
    <header className="h-14 bg-white dark:bg-[#1E293B] border-b border-[#E2E8F0] dark:border-white/8 flex items-center justify-between px-4 gap-4 shrink-0 sticky top-0 z-20 transition-colors duration-200">

      {/* Mobile menu button */}
      <button
        onClick={onToggleSidebar}
        className="p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/8 transition-colors md:hidden"
        aria-label="Menu"
      >
        <Menu className="w-5 h-5" />
      </button>

      {/* Desktop toggle collapse */}
      <button
        onClick={onToggleCollapse}
        title={collapsed ? 'Développer le menu' : 'Réduire le menu'}
        className="hidden md:flex p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/8 transition-colors"
      >
        {collapsed
          ? <PanelLeftOpen className="w-5 h-5" />
          : <PanelLeftClose className="w-5 h-5" />
        }
      </button>

      {/* Search */}
      <GlobalSearchBar />

      {/* Right actions */}
      <div className="flex items-center gap-1">

        {/* Dark / Light mode */}
        <button
          onClick={toggleTheme}
          title={dark ? 'Passer en mode clair' : 'Passer en mode sombre'}
          className="relative p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/8 transition-colors"
        >
          {dark
            ? <Sun className="w-4 h-4" />
            : <Moon className="w-4 h-4" />
          }
        </button>

        {/* Notifications */}
        <div className="relative" ref={notifRef}>
          <button
            onClick={() => setNotifOpen(p => !p)}
            className="relative p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/8 transition-colors"
          >
            <Bell className="w-4 h-4" />
            {unreadCount > 0 && (
              <span className="absolute top-0.5 right-0.5 min-w-[16px] h-4 px-0.5 flex items-center justify-center text-[9px] font-bold bg-[#DC2626] text-white rounded-full">
                {unreadCount > 99 ? '99+' : unreadCount}
              </span>
            )}
          </button>

          {notifOpen && (
            <div className="absolute right-0 mt-2 w-80 bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/10 rounded-xl shadow-lg shadow-black/8 z-50 overflow-hidden">
              <div className="px-4 py-3 border-b border-[#F1F5F9] dark:border-white/8 flex items-center justify-between">
                <p className="text-sm font-semibold text-[#0F172A] dark:text-white">Notifications</p>
                {unreadCount > 0 && (
                  <button onClick={handleMarkAllRead} className="flex items-center gap-1 text-xs text-[#2563EB] hover:text-[#1D4ED8] font-medium">
                    <CheckCheck className="w-3.5 h-3.5" />
                    Tout marquer lu
                  </button>
                )}
              </div>
              <div className="max-h-72 overflow-y-auto divide-y divide-[#F1F5F9] dark:divide-white/5">
                {notifications.length === 0 ? (
                  <p className="px-4 py-8 text-center text-sm text-[#94A3B8] dark:text-white/30">Aucune notification</p>
                ) : notifications.map(n => (
                  <div
                    key={n.id}
                    onClick={() => !n.read_at && handleMarkRead(n.id)}
                    className={`px-4 py-3 cursor-pointer hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors ${!n.read_at ? 'bg-[#EFF6FF]/50 dark:bg-[#2563EB]/5' : ''}`}
                  >
                    <p className={`text-xs leading-relaxed ${!n.read_at ? 'font-semibold text-[#0F172A] dark:text-white' : 'text-[#64748B] dark:text-white/50'}`}>
                      {n.data?.message || n.message || 'Nouvelle notification'}
                    </p>
                    <p className="text-[10px] text-[#94A3B8] dark:text-white/30 mt-0.5">
                      {new Date(n.created_at).toLocaleString('fr-FR')}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="w-px h-5 bg-[#E2E8F0] dark:bg-white/10 mx-1" />

        {/* User menu */}
        <div ref={dropdownRef} className="relative">
          <button
            onClick={() => setDropdownOpen(!dropdownOpen)}
            className="flex items-center gap-2 h-8 px-2 rounded-md hover:bg-[#F1F5F9] dark:hover:bg-white/8 transition-colors"
          >
            <div className="w-6 h-6 rounded-full bg-[#EFF6FF] dark:bg-[#1D4ED8]/30 text-[#2563EB] flex items-center justify-center text-xs font-bold border border-[#DBEAFE] dark:border-[#2563EB]/30">
              {initials}
            </div>
            <span className="hidden sm:block text-sm font-medium text-[#0F172A] dark:text-white max-w-[100px] truncate">
              {user?.name || 'Agent'}
            </span>
            <ChevronDown className={`w-3.5 h-3.5 text-[#64748B] dark:text-white/40 transition-transform ${dropdownOpen ? 'rotate-180' : ''}`} />
          </button>

          {dropdownOpen && (
            <div className="absolute right-0 mt-1 w-52 bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/10 rounded-lg shadow-lg shadow-black/8 p-1 z-50">
              <div className="px-3 py-2 mb-1 border-b border-[#F1F5F9] dark:border-white/8">
                <p className="text-sm font-semibold text-[#0F172A] dark:text-white truncate">{user?.name || 'Inspecteur'}</p>
                <p className="text-xs text-[#64748B] dark:text-white/40 capitalize mt-0.5">{user?.roles?.[0]?.name || 'Agent'}</p>
              </div>
              <button
                onClick={() => { logout(); setDropdownOpen(false); }}
                className="flex items-center gap-2 w-full px-3 py-2 text-sm text-[#DC2626] hover:bg-[#FEF2F2] dark:hover:bg-red-500/10 rounded-md transition-colors font-medium"
              >
                <LogOut className="w-4 h-4" />
                Déconnexion
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

