import { useState, useEffect, useCallback } from 'react';

/**
 * Hook CRUD générique.
 * Utilisation : const { data, loading, error, refresh, remove } = useCrud(service.getAll, params)
 */
export default function useCrud(fetchFn, params = null) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetch = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetchFn(params);
      const result = response.data?.data ?? response.data ?? [];
      setData(Array.isArray(result) ? result : [result]);
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur de chargement');
    } finally {
      setLoading(false);
    }
  }, [fetchFn, JSON.stringify(params)]);

  useEffect(() => {
    fetch();
  }, [fetch]);

  return { data, loading, error, refresh: fetch, setData };
}

