import { useState, useEffect, useCallback } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Search, Plus, Download, Edit, Trash2, Eye, X,
  AlertCircle, CheckCircle2, ChevronLeft, ChevronRight
} from 'lucide-react';
import GeoFilterComponent from '../components/GeoFilterComponent';
import WorkflowBadge, { WorkflowSelect } from '../components/WorkflowBadge';
import MediaUpload from '../components/MediaUpload';
import api from '../api/axios';
import accidentService from '../services/accidentService';
import geoService from '../services/geoService';
import { useAuth } from '../contexts/AuthContext';


const sanitizePayload = (data) => {
  const s = { ...data };
  Object.keys(s).forEach(k => { if (s[k] === '') s[k] = null; });
  return s;
};

const TYPE_BADGE = {
  mortel: 'bg-[#FEF2F2] text-[#DC2626] border-[#FECACA]',
  corporel: 'bg-[#FFF7ED] text-[#C2410C] border-[#FED7AA]',
  'matériel': 'bg-[#EFF6FF] text-[#2563EB] border-[#BFDBFE]',
};

const EMPTY_FORM = {
  type: 'matériel', date: new Date().toISOString().split('T')[0],
  lieu: '', commune_id: '', service_id: '', moyen: '',
  cause_probable: '', latitude: '', longitude: '', description: '',
  workflow_status: 'En cours',
};

const inputCls = "w-full h-9 px-3 text-sm bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all";

function Toast({ toast }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <motion.div
      initial={{ opacity: 0, y: -16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -16 }}
      className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-lg shadow-lg text-sm font-medium border ${
        isError ? 'bg-[#FEF2F2] border-[#FECACA] text-[#DC2626]' : 'bg-[#F0FDF4] border-[#BBF7D0] text-[#16A34A]'
      }`}
    >
      {isError ? <AlertCircle className="w-4 h-4 shrink-0" /> : <CheckCircle2 className="w-4 h-4 shrink-0" />}
      {toast.message}
    </motion.div>
  );
}

function FormField({ label, error, required, children }) {
  return (
    <div>
      <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">
        {label}{required && <span className="text-[#DC2626] ml-0.5">*</span>}
      </label>
      {children}
      {error && <p className="text-[#DC2626] text-xs mt-1">{error[0]}</p>}
    </div>
  );
}

const SENEGAL_BOUNDS = { latMin: 12, latMax: 17, lngMin: -18, lngMax: -11 };

const isValidSenegalCoord = (lat, lng) =>
  lat >= SENEGAL_BOUNDS.latMin && lat <= SENEGAL_BOUNDS.latMax &&
  lng >= SENEGAL_BOUNDS.lngMin && lng <= SENEGAL_BOUNDS.lngMax;

export default function Accidents() {
  const { user } = useAuth();
  const [accidents, setAccidents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({ page: 1, per_page: 10 });
  const [meta, setMeta] = useState(null);
  const [selectedAccident, setSelectedAccident] = useState(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [formMode, setFormMode] = useState('create');
  const [communes, setCommunes] = useState([]);
  const [services, setServices] = useState([]);
  const [formData, setFormData] = useState(EMPTY_FORM);
  const [formErrors, setFormErrors] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const fetchAccidents = useCallback(async () => {
    setLoading(true);
    try {
      const res = await accidentService.getAll({ ...filters, search: search || undefined });
      setAccidents(res.data.data || []);
      setMeta(res.data.meta || null);
    } catch { showToast('Erreur lors de la récupération des accidents', 'error'); }
    finally { setLoading(false); }
  }, [filters, search]);

  useEffect(() => { fetchAccidents(); }, [fetchAccidents]);
  useEffect(() => {
    const fetchAux = async () => {
      try {
        const [r1, r2] = await Promise.all([geoService.getAllCommunes(), geoService.getAllServices()]);
        setCommunes(r1.data.data || r1.data || []);
        setServices(r2.data.data || r2.data || []);
      } catch (e) { console.error(e); }
    };
    fetchAux();
  }, []);

  const handlePageChange = (p) => {
    if (p >= 1 && p <= (meta?.last_page || 1)) setFilters(prev => ({ ...prev, page: p }));
  };

  const handleOpenCreate = () => {
    setFormMode('create');
    setFormData({ ...EMPTY_FORM, service_id: user?.service_id || '' });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenEdit = (accident) => {
    const minsElapsed = (new Date() - new Date(accident.created_at)) / 60000;
    const isAdmin = user?.roles?.some(r => r.name === 'admin' || r.name === 'super_admin');
    if (minsElapsed > 1 && !isAdmin) {
      showToast('Modification impossible : le délai réglementaire de 1 minute est dépassé.', 'error');
      return;
    }
    setFormMode('edit');
    setSelectedAccident(accident);
    setFormData({
      type: accident.type || 'matériel',
      date: accident.date ? accident.date.split('T')[0] : '',
      lieu: accident.lieu || '',
      commune_id: accident.commune_id || '',
      service_id: accident.service_id || '',
      moyen: accident.moyen || '',
      cause_probable: accident.cause_probable || '',
      latitude: accident.latitude || '',
      longitude: accident.longitude || '',
      description: accident.description || '',
      workflow_status: accident.workflow_status || 'En cours',
    });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenDetail = async (accident) => {
    try {
      const res = await accidentService.getOne(accident.id);
      setSelectedAccident(res.data.data || accident);
      setIsDetailOpen(true);
    } catch { showToast('Erreur lors de la récupération des détails', 'error'); }
  };

  const handleDelete = async (id) => {
    if (!confirm("Voulez-vous vraiment supprimer ce dossier d'accident ?")) return;
    try {
      await accidentService.delete(id);
      showToast('Accident supprimé avec succès.');
      fetchAccidents();
    } catch (err) { showToast(err.response?.data?.message || 'Erreur de suppression.', 'error'); }
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    setActionLoading(true);
    setFormErrors(null);
    const lat = parseFloat(formData.latitude);
    const lng = parseFloat(formData.longitude);
    const validCoords = isValidSenegalCoord(lat, lng)
      ? { latitude: lat, longitude: lng }
      : { latitude: null, longitude: null };
    const payload = sanitizePayload({ ...formData, ...validCoords });
    try {
      if (formMode === 'create') { await accidentService.create(payload); showToast('Accident enregistré avec succès.'); }
      else { await accidentService.update(selectedAccident.id, payload); showToast('Accident mis à jour avec succès.'); }
      setIsFormOpen(false);
      fetchAccidents();
    } catch (err) {
      if (err.response?.status === 422) setFormErrors(err.response.data.errors);
      else showToast(err.response?.data?.message || 'Une erreur est survenue.', 'error');
    } finally { setActionLoading(false); }
  };

  const handleExportCSV = async () => {
    try {
      const res = await api.get('/export/accidents/csv', { params: filters, responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a');
      a.href = url;
      a.setAttribute('download', `accidents_${Date.now()}.csv`);
      document.body.appendChild(a);
      a.click();
      a.remove();
      showToast('Export CSV réussi.');
    } catch { showToast("Erreur lors de l'exportation.", 'error'); }
  };

  const displayedServices = formData.commune_id
    ? (services.filter(s => String(s.commune_id) === String(formData.commune_id)).length > 0
      ? services.filter(s => String(s.commune_id) === String(formData.commune_id))
      : services)
    : services;

  return (
    <div className="space-y-6 max-w-[1400px]">
      <AnimatePresence>{toast && <Toast toast={toast} />}</AnimatePresence>

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white">Accidents de la Circulation</h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">Gestion et suivi des accidents sur le territoire national</p>
        </div>
        <div className="flex items-center gap-2 w-full sm:w-auto">
          <button onClick={handleExportCSV} className="flex items-center gap-1.5 h-9 px-4 text-sm font-medium text-[#0F172A] dark:text-white bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
            <Download className="w-4 h-4" /> Export CSV
          </button>
          <button onClick={handleOpenCreate} className="flex items-center gap-1.5 h-9 px-4 text-sm font-medium text-white bg-[#2563EB] rounded-lg hover:bg-[#1D4ED8] transition-colors">
            <Plus className="w-4 h-4" /> Nouvel Accident
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-xl p-3 flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] dark:text-white/30" />
          <input
            type="text" value={search}
            onChange={(e) => { setSearch(e.target.value); setFilters(p => ({ ...p, page: 1 })); }}
            placeholder="Rechercher par lieu, cause, véhicules..."
            className="w-full h-9 pl-9 pr-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all"
          />
        </div>
        <div className="flex items-center gap-2">
          <GeoFilterComponent onChange={(geo) => setFilters(p => ({ ...p, ...geo, page: 1 }))} />
          <select
            value={filters.type || ''}
            onChange={(e) => setFilters(p => ({ ...p, type: e.target.value || undefined, page: 1 }))}
            className="h-9 px-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all"
          >
            <option value="">Tous les types</option>
            <option value="matériel">Matériel</option>
            <option value="corporel">Corporel</option>
            <option value="mortel">Mortel</option>
          </select>
        </div>
      </div>

      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[#F1F5F9] dark:border-white/5 bg-[#F8FAFC] dark:bg-white/5">
                {['Réf.', 'Date', 'Type', 'Lieu', 'Moyen / Cause', 'Statut', 'Actions'].map((h, i) => (
                  <th key={h} className={`px-4 py-3 text-xs font-semibold text-[#64748B] dark:text-white/50 uppercase tracking-wide ${i === 6 ? 'text-right' : 'text-left'}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-[#F1F5F9] dark:divide-white/5">
              {loading ? (
                [...Array(5)].map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    {[...Array(7)].map((_, j) => <td key={j} className="px-4 py-4"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded" /></td>)}
                  </tr>
                ))
              ) : accidents.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-16 text-center">
                    <AlertCircle className="w-8 h-8 text-[#CBD5E1] mx-auto mb-2" />
                    <p className="text-sm text-[#94A3B8] dark:text-white/30">Aucun accident trouvé.</p>
                  </td>
                </tr>
              ) : (
                accidents.map((accident) => {
                  const minsElapsed = (new Date() - new Date(accident.created_at)) / 60000;
                  const canEdit = minsElapsed <= 1 || user?.roles?.some(r => r.name === 'admin' || r.name === 'super_admin');
                  const badgeCls = TYPE_BADGE[accident.type] || 'bg-[#F1F5F9] text-[#64748B] border-[#E2E8F0]';
                  return (
                    <tr key={accident.id} className="hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors group">
                      <td className="px-4 py-3 font-mono text-xs font-semibold text-[#2563EB]">#{accident.id}</td>
                      <td className="px-4 py-3 text-xs text-[#0F172A] dark:text-white font-medium">
                        {new Date(accident.date).toLocaleDateString('fr-FR')}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border capitalize ${badgeCls}`}>
                          {accident.type}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <p className="text-[#0F172A] dark:text-white font-medium text-xs">{accident.commune?.nom || '-'}</p>
                        <p className="text-[#94A3B8] dark:text-white/30 text-xs truncate max-w-[140px]">{accident.lieu}</p>
                      </td>
                      <td className="px-4 py-3">
                        <p className="text-[#0F172A] dark:text-white text-xs font-medium">{accident.moyen || '-'}</p>
                        <p className="text-[#94A3B8] dark:text-white/30 text-xs truncate max-w-[140px]">{accident.cause_probable || '-'}</p>
                      </td>
                      <td className="px-4 py-3">
                        <WorkflowBadge status={accident.workflow_status} />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button onClick={() => handleOpenDetail(accident)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#2563EB] hover:bg-[#EFF6FF] transition-colors">
                            <Eye className="w-4 h-4" />
                          </button>
                          <button onClick={() => handleOpenEdit(accident)} disabled={!canEdit}
                            className={`p-1.5 rounded-md transition-colors ${canEdit ? 'text-[#94A3B8] hover:text-[#D97706] hover:bg-[#FFFBEB]' : 'text-[#E2E8F0] cursor-not-allowed'}`}>
                            <Edit className="w-4 h-4" />
                          </button>
                          <button onClick={() => handleDelete(accident.id)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#DC2626] hover:bg-[#FEF2F2] transition-colors">
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
        {meta && (
          <div className="px-4 py-3 border-t border-[#F1F5F9] dark:border-white/5 flex flex-col sm:flex-row justify-between items-center gap-2 text-xs text-[#64748B] dark:text-white/50">
            <span>{meta.from || 0}–{meta.to || 0} sur {meta.total || 0} accidents</span>
            <div className="flex items-center gap-1">
              <button onClick={() => handlePageChange(meta.current_page - 1)} disabled={meta.current_page === 1}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/8 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="px-3 py-1 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-md font-medium">
                {meta.current_page} / {meta.last_page}
              </span>
              <button onClick={() => handlePageChange(meta.current_page + 1)} disabled={meta.current_page === meta.last_page}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/8 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* MODAL FORM */}
      <AnimatePresence>
        {isFormOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40">
            <motion.div initial={{ scale: 0.96, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.96, opacity: 0 }} transition={{ duration: 0.15 }}
              className="bg-white dark:bg-[#1E293B] rounded-xl w-full max-w-2xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden border border-[#E2E8F0] dark:border-white/8">
              <div className="px-6 py-4 border-b border-[#F1F5F9] dark:border-white/5 flex items-center justify-between shrink-0">
                <h3 className="text-base font-semibold text-[#0F172A] dark:text-white">
                  {formMode === 'create' ? 'Nouvel Accident' : `Modifier l'Accident #${selectedAccident?.id}`}
                </h3>
                <button onClick={() => setIsFormOpen(false)} className="p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/5 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              </div>
              <form onSubmit={handleFormSubmit} className="flex-1 overflow-y-auto p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <FormField label="Type d'Accident" error={formErrors?.type} required>
                    <select value={formData.type} onChange={(e) => setFormData(p => ({ ...p, type: e.target.value }))} className={inputCls} required>
                      <option value="matériel">Matériel</option>
                      <option value="corporel">Corporel</option>
                      <option value="mortel">Mortel</option>
                    </select>
                  </FormField>
                  <FormField label="Date" error={formErrors?.date} required>
                    <input type="date" value={formData.date} onChange={(e) => setFormData(p => ({ ...p, date: e.target.value }))} className={inputCls} required />
                  </FormField>
                  <FormField label="Commune" error={formErrors?.commune_id} required>
                    <select value={formData.commune_id}
                      onChange={(e) => {
                        const id = e.target.value;
                        setFormData(p => {
                          const filtered = id ? services.filter(s => String(s.commune_id) === id) : services;
                          const hasS = filtered.some(s => String(s.id) === String(p.service_id));
                          return { ...p, commune_id: id, service_id: hasS ? p.service_id : '' };
                        });
                      }}
                      className={inputCls} required>
                      <option value="">Sélectionnez la commune</option>
                      {communes.map(c => <option key={c.id} value={c.id}>{c.nom}</option>)}
                    </select>
                  </FormField>
                  <FormField label="Service Enregistreur" error={formErrors?.service_id} required>
                    <select value={formData.service_id} onChange={(e) => setFormData(p => ({ ...p, service_id: e.target.value }))} className={inputCls} required>
                      <option value="">Sélectionnez le service</option>
                      {displayedServices.map(s => <option key={s.id} value={s.id}>{s.nom}</option>)}
                    </select>
                  </FormField>
                  <div className="md:col-span-2">
                    <FormField label="Lieu Exact" error={formErrors?.lieu} required>
                      <input type="text" value={formData.lieu} onChange={(e) => setFormData(p => ({ ...p, lieu: e.target.value }))}
                        placeholder="Ex: Route nationale 1, VDN Dakar" className={inputCls} required />
                    </FormField>
                  </div>
                  <FormField label="Moyen de transport impliqué" error={formErrors?.moyen} required>
                    <select value={formData.moyen} onChange={(e) => setFormData(p => ({ ...p, moyen: e.target.value }))} className={inputCls} required>
                      <option value="">Sélectionnez le moyen</option>
                      {['Voiture', 'Moto', 'Moto trois roues', 'Camion', 'Autre'].map(v => <option key={v} value={v}>{v}</option>)}
                    </select>
                  </FormField>
                  <FormField label="Cause probable" error={formErrors?.cause_probable}>
                    <input type="text" value={formData.cause_probable} onChange={(e) => setFormData(p => ({ ...p, cause_probable: e.target.value }))}
                      placeholder="Ex: Excès de vitesse, sommeil" className={inputCls} />
                  </FormField>
                  <FormField label="Statut de traitement" error={formErrors?.workflow_status}>
                    <WorkflowSelect
                      value={formData.workflow_status}
                      onChange={(v) => setFormData(p => ({ ...p, workflow_status: v }))}
                      className={inputCls}
                    />
                  </FormField>
                  <div className="md:col-span-2">
                    <FormField label="Description détaillée" error={formErrors?.description}>
                      <textarea value={formData.description} onChange={(e) => setFormData(p => ({ ...p, description: e.target.value }))} rows={3}
                        className="w-full px-3 py-2 text-sm bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all resize-none" />
                    </FormField>
                  </div>
                </div>
                <div className="flex justify-end gap-2 mt-6 pt-4 border-t border-[#F1F5F9] dark:border-white/5">
                  <button type="button" onClick={() => setIsFormOpen(false)} className="h-9 px-4 text-sm font-medium text-[#64748B] dark:text-white/60 bg-[#F1F5F9] dark:bg-white/5 hover:bg-[#E2E8F0] dark:hover:bg-white/5 rounded-lg transition-colors">Annuler</button>
                  <button type="submit" disabled={actionLoading} className="h-9 px-5 text-sm font-medium text-white bg-[#2563EB] hover:bg-[#1D4ED8] rounded-lg transition-colors disabled:opacity-60">
                    {actionLoading ? 'Enregistrement...' : 'Enregistrer'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* MODAL DETAIL */}
      <AnimatePresence>
        {isDetailOpen && selectedAccident && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40">
            <motion.div initial={{ scale: 0.96, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.96, opacity: 0 }} transition={{ duration: 0.15 }}
              className="bg-white dark:bg-[#1E293B] rounded-xl w-full max-w-xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden border border-[#E2E8F0] dark:border-white/8">
              <div className="px-6 py-4 border-b border-[#F1F5F9] dark:border-white/5 flex items-center justify-between shrink-0">
                <h3 className="text-base font-semibold text-[#0F172A] dark:text-white">Accident #{selectedAccident.id}</h3>
                <button onClick={() => setIsDetailOpen(false)} className="p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/5 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              </div>
              <div className="flex-1 overflow-y-auto p-6 space-y-5 text-sm">
                <div className="grid grid-cols-2 gap-4">
                  {[
                    { label: 'Type de gravité', value: selectedAccident.type, badge: true },
                    { label: 'Date', value: new Date(selectedAccident.date).toLocaleDateString('fr-FR') },
                    { label: 'Lieu exact', value: selectedAccident.lieu },
                    { label: 'Commune', value: selectedAccident.commune?.nom || '-' },
                    { label: 'Véhicules impliqués', value: selectedAccident.moyen || '-' },
                    { label: 'Cause probable', value: selectedAccident.cause_probable || 'Non déterminée' },
                    { label: 'Saisi par', value: selectedAccident.user?.name || '-' },
                    { label: 'Service instructeur', value: selectedAccident.service?.nom || '-' },
                  ].map(({ label, value, badge }) => (
                    <div key={label}>
                      <p className="text-xs font-medium text-[#94A3B8] dark:text-white/30 uppercase tracking-wide mb-1">{label}</p>
                      {badge ? (
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border capitalize ${TYPE_BADGE[value] || 'bg-[#F1F5F9] text-[#64748B] border-[#E2E8F0]'}`}>{value}</span>
                      ) : (
                        <p className="font-medium text-[#0F172A] dark:text-white">{value}</p>
                      )}
                    </div>
                  ))}
                  {selectedAccident.latitude && (
                    <div className="col-span-2">
                      <p className="text-xs font-medium text-[#94A3B8] dark:text-white/30 uppercase tracking-wide mb-1">Coordonnées GPS</p>
                      <p className="font-mono text-xs text-[#64748B] dark:text-white/50 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 px-3 py-2 rounded-lg inline-block">
                        {selectedAccident.latitude}, {selectedAccident.longitude}
                      </p>
                    </div>
                  )}
                  <div className="col-span-2">
                    <p className="text-xs font-medium text-[#94A3B8] dark:text-white/30 uppercase tracking-wide mb-1">Description</p>
                    <p className="text-[#64748B] dark:text-white/50 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 p-3 rounded-lg text-xs leading-relaxed whitespace-pre-wrap">
                      {selectedAccident.description || 'Aucune description disponible.'}
                    </p>
                  </div>
                </div>
                {selectedAccident.victimes?.length > 0 && (
                  <div className="border-t border-[#F1F5F9] dark:border-white/5 pt-4">
                    <p className="text-xs font-semibold text-[#0F172A] dark:text-white uppercase mb-3">Victimes ({selectedAccident.victimes.length})</p>
                    <div className="space-y-2">
                      {selectedAccident.victimes.map(v => (
                        <div key={v.id} className="flex items-center justify-between p-3 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg text-xs">
                          <div>
                            <p className="font-semibold text-[#0F172A] dark:text-white">{v.prenom} {v.nom}</p>
                            <p className="text-[#94A3B8] dark:text-white/30 mt-0.5">Sexe: {v.sexe || '-'} · Âge: {v.age ? `${v.age} ans` : '-'}</p>
                          </div>
                          <span className="px-2 py-0.5 bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded font-medium text-[#64748B] dark:text-white/50">CIN: {v.no_cin_passeport || 'N/C'}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <div className="border-t border-[#F1F5F9] dark:border-white/5 pt-4">
                  <div className="mb-3">
                    <p className="text-xs font-medium text-[#94A3B8] dark:text-white/30 uppercase tracking-wide mb-1">Statut de traitement</p>
                    <WorkflowBadge status={selectedAccident.workflow_status} />
                  </div>
                  <MediaUpload entityType="accidents" entityId={selectedAccident.id} />
                </div>
              </div>
              <div className="px-6 py-3 border-t border-[#F1F5F9] dark:border-white/5 flex justify-end shrink-0">
                <button onClick={() => setIsDetailOpen(false)} className="h-9 px-4 text-sm font-medium text-[#64748B] dark:text-white/60 bg-[#F1F5F9] dark:bg-white/5 hover:bg-[#E2E8F0] dark:hover:bg-white/5 rounded-lg transition-colors">Fermer</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

