import { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Terminal, Search, Eye, X, Globe, Cpu, Info, RefreshCw, ChevronLeft, ChevronRight, BarChart3, Users, TrendingUp } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import auditService from '../services/auditService';

const ACTION_BADGE = {
  created:              'bg-[#F0FDF4] text-[#16A34A] border-[#BBF7D0]',
  updated:              'bg-[#EFF6FF] text-[#2563EB] border-[#BFDBFE]',
  deleted:              'bg-[#FEF2F2] text-[#DC2626] border-[#FECACA]',
  login:                'bg-[#EEF2FF] text-[#4338CA] border-[#C7D2FE]',
  logout:               'bg-[#FFFBEB] text-[#D97706] border-[#FDE68A]',
  login_failed:         'bg-[#FFF1F2] text-[#E11D48] border-[#FECDD3]',
  sync_violation:       'bg-[#FFF7ED] text-[#C2410C] border-[#FED7AA]',
  territorial_violation:'bg-[#FAF5FF] text-[#7C3AED] border-[#DDD6FE]',
};

const actionBadgeCls = (a) => ACTION_BADGE[a] || 'bg-[#F8FAFC] text-[#475569] border-[#E2E8F0]';

const getDiffKeys = (oldVal, newVal) =>
  Array.from(new Set([...Object.keys(oldVal || {}), ...Object.keys(newVal || {})]));

const ACTION_COLORS = {
  created: '#16A34A', updated: '#2563EB', deleted: '#DC2626',
  login: '#4338CA', logout: '#D97706', login_failed: '#E11D48',
  sync_violation: '#C2410C', territorial_violation: '#7C3AED',
};

export default function AuditLogs() {
  const [logs,        setLogs]        = useState([]);
  const [allLogs,     setAllLogs]     = useState([]); // pour les stats
  const [loading,     setLoading]     = useState(true);
  const [searchTerm,  setSearchTerm]  = useState('');
  const [actionFilter,setActionFilter]= useState('');
  const [page,        setPage]        = useState(1);
  const [meta,        setMeta]        = useState(null);
  const [selectedLog, setSelectedLog] = useState(null);
  const PER_PAGE = 20;

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const r = await auditService.getAll({ page, per_page: PER_PAGE, action: actionFilter || undefined, search: searchTerm || undefined });
      setLogs(r.data.data || r.data || []);
      setMeta(r.data.meta || null);
    } catch (e) {
      console.error("Erreur lors de la récupération des logs d'audit", e);
    } finally {
      setLoading(false);
    }
  }, [page, actionFilter, searchTerm]);

  // Charger un échantillon large pour les stats (sans filtre)
  useEffect(() => {
    auditService.getAll({ per_page: 200 })
      .then(r => setAllLogs(r.data.data || r.data || []))
      .catch(() => {});
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleSearch = (val) => { setSearchTerm(val); setPage(1); };
  const handleAction = (val) => { setActionFilter(val); setPage(1); };

  /* ── Statistiques calculées depuis allLogs ── */
  const statsActions = useMemo(() => {
    const counts = {};
    allLogs.forEach(l => { counts[l.action] = (counts[l.action] || 0) + 1; });
    return Object.entries(counts)
      .map(([action, total]) => ({ action, total }))
      .sort((a, b) => b.total - a.total);
  }, [allLogs]);

  const topUsers = useMemo(() => {
    const counts = {};
    allLogs.forEach(l => {
      const name = l.user?.name || 'Système';
      counts[name] = (counts[name] || 0) + 1;
    });
    return Object.entries(counts)
      .map(([name, total]) => ({ name, total }))
      .sort((a, b) => b.total - a.total)
      .slice(0, 6);
  }, [allLogs]);

  const activityByDay = useMemo(() => {
    const counts = {};
    allLogs.forEach(l => {
      const day = new Date(l.created_at).toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit' });
      counts[day] = (counts[day] || 0) + 1;
    });
    return Object.entries(counts)
      .map(([day, total]) => ({ day, total }))
      .slice(-14);
  }, [allLogs]);

  return (
    <div className="space-y-6 max-w-[1400px]">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white flex items-center gap-2">
            <Terminal className="w-6 h-6 text-[#2563EB]" />
            Audit Logs & Traçabilité
          </h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">
            Historique immuable de toutes les actions sur le système
          </p>
        </div>
      </div>

      {/* KPI cards */}
      {allLogs.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {[
            {
              label: 'Entrées analysées',
              value: allLogs.length,
              icon: <BarChart3 className="w-5 h-5 text-[#2563EB]" />,
              bg: 'bg-[#DBEAFE]',
              accent: '',
            },
            {
              label: 'Utilisateurs actifs',
              value: new Set(allLogs.map(l => l.user?.id).filter(Boolean)).size,
              icon: <Users className="w-5 h-5 text-[#16A34A]" />,
              bg: 'bg-[#DCFCE7]',
              accent: '',
            },
            {
              label: 'Action dominante',
              value: statsActions[0]?.action || '—',
              icon: <TrendingUp className="w-5 h-5 text-[#D97706]" />,
              bg: 'bg-[#FEF3C7]',
              accent: '',
              isText: true,
            },
            {
              label: 'Utilisateur le + actif',
              value: topUsers[0]?.name || '—',
              icon: <Terminal className="w-5 h-5 text-[#2563EB]" />,
              bg: 'bg-[#DBEAFE]',
              accent: '',
              isText: true,
            },
          ].map(({ label, value, icon, bg, isText }) => (
            <div key={label} className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-4 flex items-start gap-3 shadow-[0_2px_6px_rgba(15,23,42,0.04)] hover:shadow-[0_8px_20px_rgba(15,23,42,0.08)] hover:-translate-y-0.5 transition-all duration-200">
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${bg}`}>{icon}</div>
              <div className="min-w-0">
                <p className="text-xs text-[#64748B] dark:text-white/40 mb-1">{label}</p>
                <p className={`font-bold text-[#0F172A] dark:text-white truncate ${isText ? 'text-sm' : 'text-xl'}`}>{value}</p>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Charts row */}
      {allLogs.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          {/* Actions par type */}
          <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 shadow-[0_2px_6px_rgba(15,23,42,0.04)]">
            <h3 className="text-sm font-semibold text-[#0F172A] dark:text-white mb-4 flex items-center gap-2">
              <BarChart3 className="w-4 h-4 text-[#2563EB]" />
              Actions par type
            </h3>
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={statsActions} layout="vertical" barSize={10} margin={{ left: 40, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 10, fill: '#94A3B8' }} axisLine={false} tickLine={false} />
                <YAxis type="category" dataKey="action" tick={{ fontSize: 10, fill: '#64748B' }} axisLine={false} tickLine={false} width={80} />
                <Tooltip
                  contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0', background: '#fff' }}
                  formatter={(v) => [v, 'Occurrences']}
                />
                <Bar dataKey="total" radius={[0, 4, 4, 0]}>
                  {statsActions.map((entry) => (
                    <Cell key={entry.action} fill={ACTION_COLORS[entry.action] || '#94A3B8'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>

          {/* Top utilisateurs */}
          <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 shadow-[0_2px_6px_rgba(15,23,42,0.04)]">
            <h3 className="text-sm font-semibold text-[#0F172A] dark:text-white mb-4 flex items-center gap-2">
              <Users className="w-4 h-4 text-[#16A34A]" />
              Utilisateurs les + actifs
            </h3>
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={topUsers} layout="vertical" barSize={10} margin={{ left: 40, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 10, fill: '#94A3B8' }} axisLine={false} tickLine={false} />
                <YAxis type="category" dataKey="name" tick={{ fontSize: 10, fill: '#64748B' }} axisLine={false} tickLine={false} width={80} />
                <Tooltip
                  contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0', background: '#fff' }}
                  formatter={(v) => [v, 'Actions']}
                />
                <Bar dataKey="total" fill="#16A34A" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>

          {/* Activité 14 derniers jours */}
          <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 shadow-[0_2px_6px_rgba(15,23,42,0.04)]">
            <h3 className="text-sm font-semibold text-[#0F172A] dark:text-white mb-4 flex items-center gap-2">
              <TrendingUp className="w-4 h-4 text-[#D97706]" />
              Activité (14 derniers jours)
            </h3>
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={activityByDay} barSize={14} margin={{ left: 0, right: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" vertical={false} />
                <XAxis dataKey="day" tick={{ fontSize: 9, fill: '#94A3B8' }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fontSize: 10, fill: '#94A3B8' }} axisLine={false} tickLine={false} width={28} />
                <Tooltip
                  contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0', background: '#fff' }}
                  formatter={(v) => [v, 'Actions']}
                />
                <Bar dataKey="total" fill="#D97706" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* Toolbar */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-4 flex flex-col sm:flex-row gap-3 items-center">
        <div className="relative flex-1 w-full sm:max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder="Rechercher par utilisateur, modèle, action, IP…"
            className="w-full pl-9 pr-4 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-colors"
          />
        </div>
        <select
          value={actionFilter}
          onChange={(e) => handleAction(e.target.value)}
          className="h-9 px-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 transition-colors"
        >
          <option value="">Toutes les actions</option>
          {Object.keys(ACTION_BADGE).map(a => <option key={a} value={a}>{a}</option>)}
        </select>
        <button
          onClick={() => { setPage(1); fetchData(); }}
          className="inline-flex items-center gap-2 px-4 py-2 bg-[#F8FAFC] dark:bg-white/5 hover:bg-[#F1F5F9] dark:hover:bg-white/10 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-xs font-semibold text-[#475569] dark:text-white/60 transition-colors shrink-0"
        >
          <RefreshCw className="w-3.5 h-3.5" />
          Rafraîchir
        </button>
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead>
              <tr className="border-b border-[#E2E8F0] dark:border-white/8 bg-[#F8FAFC] dark:bg-white/3">
                <th className="px-5 py-3 text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Date & Heure</th>
                <th className="px-5 py-3 text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Action</th>
                <th className="px-5 py-3 text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Utilisateur</th>
                <th className="px-5 py-3 text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Modèle Ciblé</th>
                <th className="px-5 py-3 text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Adresse IP</th>
                <th className="px-5 py-3 text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide text-right">Détails</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#F1F5F9] dark:divide-white/5">
              {loading ? (
                [...Array(6)].map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td className="px-5 py-4"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-28" /></td>
                    <td className="px-5 py-4"><div className="h-5 bg-[#F1F5F9] dark:bg-white/5 rounded-full w-16" /></td>
                    <td className="px-5 py-4">
                      <div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-24 mb-1" />
                      <div className="h-3 bg-[#F1F5F9] dark:bg-white/5 rounded w-32" />
                    </td>
                    <td className="px-5 py-4"><div className="h-5 bg-[#F1F5F9] dark:bg-white/5 rounded w-24" /></td>
                    <td className="px-5 py-4"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-20" /></td>
                    <td className="px-5 py-4 text-right"><div className="h-7 bg-[#F1F5F9] dark:bg-white/5 rounded-lg w-20 ml-auto" /></td>
                  </tr>
                ))
              ) : logs.length === 0 ? (
                <tr>
                  <td colSpan="6" className="px-5 py-16 text-center text-sm text-[#94A3B8] dark:text-white/30">
                    Aucun journal d'audit ne correspond à vos critères.
                  </td>
                </tr>
              ) : logs.map(log => (
                <tr key={log.id} className="hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                  <td className="px-5 py-3.5">
                    <span className="font-medium text-[#0F172A] dark:text-white text-xs">
                      {new Date(log.created_at || log.date).toLocaleDateString('fr-FR')}
                    </span>
                    <span className="text-[#94A3B8] dark:text-white/30 text-xs font-mono ml-1.5">
                      {new Date(log.created_at || log.date).toLocaleTimeString('fr-FR')}
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    <span className={`inline-flex px-2 py-0.5 rounded-full text-xs font-semibold uppercase border ${actionBadgeCls(log.action)}`}>
                      {log.action}
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    <p className="font-semibold text-[#0F172A] dark:text-white text-xs">{log.user?.name || 'Système'}</p>
                    <p className="text-[#94A3B8] dark:text-white/30 text-xs">{log.user?.email || 'Automate'}</p>
                  </td>
                  <td className="px-5 py-3.5">
                    {log.model_type ? (
                      <span className="font-mono text-xs bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 px-2 py-1 rounded-lg text-[#475569] dark:text-white/60">
                        {log.model_type.split('\\').pop()} #{log.model_id}
                      </span>
                    ) : (
                      <span className="text-xs text-[#94A3B8] dark:text-white/30 italic">Aucune entité</span>
                    )}
                  </td>
                  <td className="px-5 py-3.5">
                    <span className="flex items-center gap-1.5 text-xs font-mono text-[#64748B] dark:text-white/50">
                      <Globe className="w-3.5 h-3.5 text-[#94A3B8]" />
                      {log.ip_address || '—'}
                    </span>
                  </td>
                  <td className="px-5 py-3.5 text-right">
                    <button
                      onClick={() => setSelectedLog(log)}
                      className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-[#EFF6FF] dark:bg-[#2563EB]/20 hover:bg-[#2563EB] hover:text-white text-[#2563EB] dark:text-[#60A5FA] text-xs font-semibold rounded-lg transition-colors"
                    >
                      <Eye className="w-3.5 h-3.5" />
                      Inspecter
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {meta && meta.last_page > 1 && (
          <div className="px-5 py-3 border-t border-[#E2E8F0] dark:border-white/8 flex items-center justify-between text-xs text-[#64748B] dark:text-white/40">
            <span>{meta.from}–{meta.to} sur {meta.total} entrées</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/10 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[#F8FAFC] dark:hover:bg-white/5 transition-colors">
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="px-3 py-1 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-md font-medium">
                {page} / {meta.last_page}
              </span>
              <button onClick={() => setPage(p => Math.min(meta.last_page, p + 1))} disabled={page === meta.last_page}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/10 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[#F8FAFC] dark:hover:bg-white/5 transition-colors">
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Inspection modal */}
      <AnimatePresence>
        {selectedLog && (
          <div className="fixed inset-0 bg-black/40 flex items-center justify-center p-4 z-50 overflow-y-auto">
            <motion.div
              initial={{ opacity: 0, scale: 0.96, y: 12 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.96, y: 12 }}
              transition={{ duration: 0.18 }}
              className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/10 rounded-xl w-full max-w-4xl shadow-lg overflow-hidden flex flex-col my-8 max-h-[85vh]"
            >
              <div className="px-6 py-4 border-b border-[#E2E8F0] dark:border-white/8 flex items-center justify-between bg-[#F8FAFC] dark:bg-white/3">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 bg-[#2563EB] rounded-xl flex items-center justify-center shadow-sm">
                    <Terminal className="w-4 h-4 text-white" />
                  </div>
                  <div>
                    <p className="font-semibold text-[#0F172A] dark:text-white text-sm">Inspection Log #{selectedLog.id}</p>
                    <p className="text-xs text-[#64748B] dark:text-white/40">Audit de sécurité GESCRIM</p>
                  </div>
                </div>
                <button onClick={() => setSelectedLog(null)} className="w-8 h-8 flex items-center justify-center rounded-lg text-[#64748B] dark:text-white/50 hover:bg-[#E2E8F0] dark:hover:bg-white/10 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="p-6 overflow-y-auto flex-1 space-y-5">
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3">
                  {[
                    { label: 'Date & Heure', value: new Date(selectedLog.created_at || selectedLog.date).toLocaleString('fr-FR') },
                    { label: 'Opérateur', value: selectedLog.user?.name || 'Système' },
                    { label: 'Action', custom: <span className={`inline-flex px-2 py-0.5 rounded-full text-[10px] font-bold uppercase border mt-1 ${actionBadgeCls(selectedLog.action)}`}>{selectedLog.action}</span> },
                    { label: 'Adresse IP', value: selectedLog.ip_address || 'Non spécifiée', mono: true },
                  ].map(({ label, value, custom, mono }) => (
                    <div key={label} className="p-3 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg">
                      <p className="text-[10px] uppercase font-semibold text-[#94A3B8] dark:text-white/30 mb-1">{label}</p>
                      {custom || <p className={`text-sm font-semibold text-[#0F172A] dark:text-white truncate ${mono ? 'font-mono' : ''}`}>{value}</p>}
                    </div>
                  ))}
                </div>

                {selectedLog.user_agent && (
                  <div className="p-3.5 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg flex items-start gap-2.5">
                    <Cpu className="w-4 h-4 text-[#94A3B8] mt-0.5 shrink-0" />
                    <div>
                      <p className="text-[10px] uppercase font-semibold text-[#94A3B8] dark:text-white/30 mb-1">Signature Navigateur</p>
                      <p className="text-xs font-mono text-[#475569] dark:text-white/60 leading-relaxed break-all">{selectedLog.user_agent}</p>
                    </div>
                  </div>
                )}

                <div className="space-y-2">
                  <h4 className="text-sm font-semibold text-[#0F172A] dark:text-white flex items-center gap-2">
                    <Info className="w-4 h-4 text-[#2563EB]" />
                    Comparatif des modifications
                  </h4>
                  {(!selectedLog.old_values || Object.keys(selectedLog.old_values).length === 0) &&
                   (!selectedLog.new_values || Object.keys(selectedLog.new_values).length === 0) ? (
                    <div className="py-10 text-center border border-dashed border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#94A3B8] dark:text-white/30">
                      Aucune modification de valeur associée à cet événement.
                    </div>
                  ) : (
                    <div className="border border-[#E2E8F0] dark:border-white/10 rounded-xl overflow-hidden">
                      <div className="grid grid-cols-3 bg-[#F8FAFC] dark:bg-white/3 border-b border-[#E2E8F0] dark:border-white/8 divide-x divide-[#E2E8F0] dark:divide-white/8">
                        <div className="px-4 py-2.5 text-xs font-semibold text-[#64748B] dark:text-white/40">Champ</div>
                        <div className="px-4 py-2.5 text-xs font-semibold text-[#DC2626]">Valeur Précédente</div>
                        <div className="px-4 py-2.5 text-xs font-semibold text-[#16A34A]">Nouvelle Valeur</div>
                      </div>
                      <div className="divide-y divide-[#F1F5F9] dark:divide-white/5 text-xs font-mono bg-white dark:bg-[#1E293B]">
                        {getDiffKeys(selectedLog.old_values, selectedLog.new_values).map((key) => {
                          const oldVal = selectedLog.old_values?.[key];
                          const newVal = selectedLog.new_values?.[key];
                          const isChanged = JSON.stringify(oldVal) !== JSON.stringify(newVal);
                          return (
                            <div key={key} className={`grid grid-cols-3 divide-x divide-[#F1F5F9] dark:divide-white/5 ${isChanged ? 'bg-[#FFFBEB]/40 dark:bg-yellow-900/10' : ''}`}>
                              <div className="px-4 py-3 font-semibold text-[#475569] dark:text-white/60 break-all self-center">{key}</div>
                              <div className="px-4 py-3 text-[#DC2626] break-all leading-relaxed whitespace-pre-wrap">
                                {oldVal !== undefined && oldVal !== null
                                  ? (typeof oldVal === 'object' ? JSON.stringify(oldVal, null, 2) : String(oldVal))
                                  : <span className="text-[#CBD5E1] dark:text-white/20 italic">N/A</span>}
                              </div>
                              <div className="px-4 py-3 text-[#16A34A] break-all leading-relaxed whitespace-pre-wrap font-semibold">
                                {newVal !== undefined && newVal !== null
                                  ? (typeof newVal === 'object' ? JSON.stringify(newVal, null, 2) : String(newVal))
                                  : <span className="text-[#CBD5E1] dark:text-white/20 italic font-normal">Supprimé / Nul</span>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              </div>

              <div className="px-6 py-4 border-t border-[#E2E8F0] dark:border-white/8 bg-[#F8FAFC] dark:bg-white/3 flex justify-end">
                <button onClick={() => setSelectedLog(null)} className="px-5 py-2 bg-[#0F172A] dark:bg-white dark:text-[#0F172A] hover:bg-[#1E293B] text-white rounded-lg text-xs font-semibold transition-colors">
                  Fermer
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

