const SENEGAL_CENTER = [14.4974, -14.4524];

const isValidSenegalCoord = (lat, lng) =>
  lat >= 12 && lat <= 17 && lng >= -18 && lng <= -11;

const REGION_COORDS = {
  '1':  { center: [14.7167, -17.4677], zoom: 11, name: 'Dakar'         },
