function StatCard({ title, value, label, icon: Icon, iconColor, trend, sub, delta }) {
  const trendClass = !trend || trend === 'neutral'
    ? 'text-[#64748B] bg-[#F1F5F9] dark:bg-white/5 dark:text-white/40'
    : trend.includes('up_bad') || trend.includes('down_bad')
      ? 'text-[#DC2626] bg-[#FEF2F2] dark:bg-red-900/20'
      : 'text-[#16A34A] bg-[#F0FDF4] dark:bg-green-900/20';
  const TrendIcon = trend?.includes('up') ? TrendingUp : trend?.includes('down') ? TrendingDown : Minus;

  return (
    <div className="bg-white dark:bg-[#1E293B] rounded-xl p-5 border border-[#E2E8F0] dark:border-white/8 shadow-[0_2px_6px_rgba(15,23,42,0.04)] hover:shadow-[0_8px_20px_rgba(15,23,42,0.08)] hover:-translate-y-0.5 transition-all duration-200">
      <div className="flex items-start justify-between">
        <div className="min-w-0">
          <p className="text-sm text-[#64748B] dark:text-white/50 font-medium truncate">{title}</p>
          <p className="text-2xl font-bold text-[#0F172A] dark:text-white mt-1 tabular-nums">{value}</p>
          {sub && <p className="text-xs text-[#94A3B8] dark:text-white/30 mt-0.5">{sub}</p>}
        </div>
        <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${iconColor}`}>
          <Icon className="w-5 h-5" />
        </div>
      </div>
      <div className="mt-3 flex items-center gap-2 flex-wrap">
        {label && (
          <div className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${trendClass}`}>
            <TrendIcon className="w-3 h-3" />
            {label}
          </div>
        )}
        {delta !== undefined && delta !== null && (
          <span className={`text-xs font-medium ${delta > 0 ? 'text-[#DC2626]' : delta < 0 ? 'text-[#16A34A]' : 'text-[#94A3B8]'}`}>
            {delta > 0 ? `+${delta}` : delta} vs période préc.
          </span>
        )}
      </div>
    </div>
  );
}

