/* ─── Dashboard principal ─── */
export default function Dashboard() {
  const { user } = useAuth();
  const role = user?.roles?.[0] || 'agent';
  const isAgent       = role === 'agent';
  const isSuperviseur = role === 'superviseur';
  const isAdmin       = role === 'admin';
  const isSuperAdmin  = role === 'super_admin';
  const isNational    = isAdmin || isSuperAdmin;

  const [stats,                setStats]                = useState(null);
  const [tendances,            setTendances]            = useState([]);
  const [accidentsParType,     setAccidentsParType]     = useState([]);
  const [infractionsParRegion, setInfractionsParRegion] = useState([]);
  const [infractionsParType,   setInfractionsParType]   = useState([]);
  const [personnelParService,  setPersonnelParService]  = useState([]);
  const [mapIncidents,         setMapIncidents]         = useState([]);
  const [loading,              setLoading]              = useState(true);
  const [error,                setError]                = useState(null);
  const [geoFilters,           setGeoFilters]           = useState({});
  const [annee,                setAnnee]                = useState('');
  const [mois,                 setMois]                 = useState('');
  const [refreshKey,           setRefreshKey]           = useState(0);
  const [mapFullscreen,        setMapFullscreen]        = useState(false);

  // Fermer plein écran avec Escape
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') setMapFullscreen(false); };
    if (mapFullscreen) window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [mapFullscreen]);

  const currentYear = new Date().getFullYear();
  const currentMonth = new Date().getMonth() + 1;
  const anneeOptions = Array.from({ length: 6 }, (_, i) => currentYear - i);
  const moisOptions = MOIS_LABELS.map((label, i) => ({ value: String(i + 1), label }));
  // Désactiver les mois futurs si l'année sélectionnée est l'année en cours
  const isMoisDisabled = (m) => {
    const selectedYear = annee ? parseInt(annee) : currentYear;
    return selectedYear === currentYear && parseInt(m) > currentMonth;
  };

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const params = {
        ...geoFilters,
        ...(annee ? { annee } : {}),
        ...(mois  ? { mois  } : {}),
      };

      const [
        resStats, resTendances, resAccidents,
        resInfRegion, resInfType, resPersoService,
        resInfractions, resMapAccidents,
      ] = await Promise.all([
        dashboardService.getStats(params),
        dashboardService.getTendancesMensuelles(params),
        dashboardService.getAccidentsParType(params),
        dashboardService.getInfractionsParRegion(params),
        dashboardService.getInfractionsParType(params),
        dashboardService.getPersonnelParService(params),
        infractionService.getAll({ per_page: 50, ...params }),
        accidentService.getAll({ per_page: 50, ...params }),
      ]);

      /* --- Stats globales --- */
      const rawStats    = resStats.data.data || resStats.data;
      const hasRealStats = rawStats && (rawStats.total_infractions > 0 || rawStats.total_accidents > 0);
      if (hasRealStats) {
        setStats(rawStats);
      } else if (mois) {
        setStats(mockDashboardStats_mois(annee || currentYear, mois));
      } else {
        setStats(mockDashboardStats_annee(annee || currentYear));
      }

      /* --- Tendances mensuelles (infractions + accidents + immigration) --- */
      const dataTendances = resTendances.data.data || resTendances.data;
      let tendancesArr = [];
      if (dataTendances && !Array.isArray(dataTendances)) {
        const inf = dataTendances.infractions || [];
        const acc = dataTendances.accidents   || [];
        const imm = dataTendances.immigration || [];
        const byKey = {};
        inf.forEach(t => {
          const k = MOIS_FR[parseInt(t.mois) - 1];
          if (k) byKey[k] = { name: k, infractions: parseInt(t.total) || 0, accidents: 0, immigration: 0 };
        });
        acc.forEach(t => {
          const k = MOIS_FR[parseInt(t.mois) - 1];
          if (!k) return;
          if (byKey[k]) byKey[k].accidents = parseInt(t.total) || 0;
          else byKey[k] = { name: k, infractions: 0, accidents: parseInt(t.total) || 0, immigration: 0 };
        });
        imm.forEach(t => {
          const k = MOIS_FR[parseInt(t.mois) - 1];
          if (!k) return;
          if (byKey[k]) byKey[k].immigration = parseInt(t.total) || 0;
          else byKey[k] = { name: k, infractions: 0, accidents: 0, immigration: parseInt(t.total) || 0 };
        });
        tendancesArr = Object.values(byKey);
      } else if (Array.isArray(dataTendances) && dataTendances.length > 0) {
        tendancesArr = dataTendances.map(t => ({
          name:        MOIS_FR[parseInt(t.mois) - 1] || t.mois,
          infractions: parseInt(t.infractions || t.total) || 0,
          accidents:   parseInt(t.accidents) || 0,
          immigration: parseInt(t.immigration) || 0,
        }));
      }
      if (tendancesArr.length > 0) {
        setTendances(tendancesArr);
      } else if (mois) {
        setTendances(mockTendances_mois(annee || currentYear, mois));
      } else {
        setTendances(mockTendances_annee(annee || currentYear));
      }

      /* --- Accidents par type --- */
      const dataAccidents = resAccidents.data.data || resAccidents.data;
      if (Array.isArray(dataAccidents) && dataAccidents.length > 0) {
        setAccidentsParType(dataAccidents.map(a => ({
          name:  a.type || a.nom || String(a.name || ''),
          value: parseInt(a.total || a.value) || 0,
        })).filter(a => a.name && a.value > 0));
      } else {
        setAccidentsParType(mockAccidentsParType());
      }

      /* --- Infractions par région --- */
      const dataRegion = resInfRegion.data.data || resInfRegion.data;
      if (Array.isArray(dataRegion) && dataRegion.length > 0) {
        setInfractionsParRegion(dataRegion.map(r => ({
          region: r.region || r.nom || String(r.name || ''),
          total:  parseInt(r.total) || 0,
        })).filter(r => r.region && r.total > 0));
      } else {
        setInfractionsParRegion([]);
      }

      /* --- Infractions par catégorie (PieChart) --- */
      const dataType = resInfType.data.data || resInfType.data;
      if (Array.isArray(dataType) && dataType.length > 0) {
        const byKey = {};
        dataType.forEach(t => {
          const key = t.categorie || t.type || t.nom || t.name || 'Autre';
          if (!byKey[key]) byKey[key] = 0;
          byKey[key] += parseInt(t.total || t.value) || 0;
        });
        const arr = Object.entries(byKey)
          .map(([name, value]) => ({ name, value }))
          .filter(e => e.value > 0)
          .sort((a, b) => b.value - a.value);
        setInfractionsParType(arr.length > 0 ? arr : mockInfractionsParType());
      } else {
        setInfractionsParType(mockInfractionsParType());
      }

      /* --- Personnel par service --- */
      const dataPerso = resPersoService.data.data || resPersoService.data;
      if (Array.isArray(dataPerso) && dataPerso.length > 0) {
        const arr = dataPerso.map(p => ({
          service: p.service || p.nom || p.name || String(p.id || ''),
          total:   parseInt(p.total || p.effectif) || 0,
          type:    p.type || '',
        })).filter(p => p.service && p.total > 0);
        setPersonnelParService(arr.length > 0 ? arr : mockPersonnelParService());
      } else {
        setPersonnelParService(mockPersonnelParService());
      }

      /* --- Carte --- */
      const dataInfractions  = resInfractions.data.data  || resInfractions.data  || [];
      const dataMapAccidents = resMapAccidents.data.data  || resMapAccidents.data || [];
      const fmt = (data, type) => (Array.isArray(data) ? data : [])
        .map(item => {
          const lat = parseFloat(item.latitude);
          const lng = parseFloat(item.longitude);
          if (!isValidSenegalCoord(lat, lng)) return null;
          return { ...item, _type: type, lat, lng };
        })
        .filter(Boolean);
      setMapIncidents([...fmt(dataInfractions, 'infraction'), ...fmt(dataMapAccidents, 'accident')]);

    } catch (err) {
      console.error('Dashboard data error', err);
      setError('Impossible de charger les données. Vérifiez votre connexion.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, [geoFilters, annee, mois, refreshKey]);

  /* ── Indicateurs calculés ── */
  const tauxDeferrement = useMemo(() => {
    if (!stats?.total_infractions) return 0;
    return Math.round((stats.infractions_deferees / stats.total_infractions) * 100);
  }, [stats]);

  const tauxMortalite = useMemo(() => {
    if (!stats?.total_accidents) return 0;
    return Math.round((stats.accidents_mortels / stats.total_accidents) * 100);
  }, [stats]);

  const totalInfRegion = useMemo(
    () => infractionsParRegion.reduce((s, r) => s + r.total, 0),
    [infractionsParRegion]
  );

  /* ── KPI cards ── */
  const kpis = stats ? [
    {
      title: 'Total Infractions',
      value: (stats.total_infractions || 0).toLocaleString('fr-FR'),
      sub:   `Constatées: ${stats.infractions_constatees || 0} · Déférées: ${stats.infractions_deferees || 0}`,
      icon:  AlertCircle,
      iconColor: 'bg-[#FEF3C7] text-[#D97706]',
      trend: 'neutral', label: 'Cumulé',
    },
    {
      title: 'Accidents',
      value: (stats.total_accidents || 0).toLocaleString('fr-FR'),
      sub:   `Mortels: ${stats.accidents_mortels || 0} · Corporels: ${stats.accidents_corporels || 0}`,
      icon:  Activity,
      iconColor: 'bg-[#FEE2E2] text-[#DC2626]',
      trend: 'neutral', label: 'Cumulé',
    },
    {
      title: 'Effectif Actif',
      value: (stats.total_personnel || 0).toLocaleString('fr-FR'),
      sub:   'Agents en service actif',
      icon:  Users,
      iconColor: 'bg-[#DBEAFE] text-[#2563EB]',
      trend: 'up_good', label: 'Personnel DSP',
    },
    {
      title: 'Amendes CFA',
      value: new Intl.NumberFormat('fr-SN').format(stats.total_amendes || 0),
      sub:   'Recettes amendes forfaitaires',
      icon:  Banknote,
      iconColor: 'bg-[#DCFCE7] text-[#16A34A]',
      trend: 'up_good', label: 'Recettes totales',
    },
    {
      title: 'Taux de déferrement',
      value: `${tauxDeferrement}%`,
      sub:   `${stats.infractions_deferees || 0} infractions déférées sur ${stats.total_infractions || 0}`,
      icon:  Percent,
      iconColor: 'bg-[#DBEAFE] text-[#2563EB]',
      trend: tauxDeferrement > 30 ? 'up_good' : 'neutral',
      label: 'Déférées / Total',
    },
    {
      title: 'Taux mortalité',
      value: `${tauxMortalite}%`,
      sub:   `${stats.accidents_mortels || 0} accidents mortels sur ${stats.total_accidents || 0}`,
      icon:  ShieldAlert,
      iconColor: 'bg-[#FEE2E2] text-[#DC2626]',
      trend: tauxMortalite > 10 ? 'up_bad' : 'neutral',
      label: 'Mortels / Total',
    },
    {
      title: 'Immigration',
      value: (stats.total_immigration || 0).toLocaleString('fr-FR'),
      sub:   'Personnes interpellées',
      icon:  Plane,
      iconColor: 'bg-[#DBEAFE] text-[#2563EB]',
      trend: 'neutral', label: 'Interpellations',
    },
    {
      title: 'Accidents matériels',
      value: (stats.accidents_materiels || 0).toLocaleString('fr-FR'),
      sub:   'Sans blessé ni décès',
      icon:  Activity,
      iconColor: 'bg-[#FEF3C7] text-[#D97706]',
      trend: 'neutral', label: 'Matériels',
    },
  ] : [];

  /* ── Label période pour les titres de sections ── */
  const labelPeriode = useMemo(() => {
    const parts = [];
    if (mois)  parts.push(MOIS_LABELS[parseInt(mois) - 1]);
    if (annee) parts.push(annee);
    else       parts.push(currentYear);
    return parts.join(' ');
  }, [annee, mois, currentYear]);

  /* ── Export CSV simplifié ── */
  const handleExportCsv = () => {
    if (!stats) return;
    const rows = [
      ['Indicateur', 'Valeur'],
      ['Total infractions',    stats.total_infractions    || 0],
      ['Infractions constatées', stats.infractions_constatees || 0],
      ['Infractions déférées', stats.infractions_deferees || 0],
      ['Total accidents',      stats.total_accidents      || 0],
      ['Accidents mortels',    stats.accidents_mortels    || 0],
      ['Accidents corporels',  stats.accidents_corporels  || 0],
      ['Accidents matériels',  stats.accidents_materiels  || 0],
      ['Effectif actif',       stats.total_personnel      || 0],
      ['Immigration',          stats.total_immigration    || 0],
      ['Amendes CFA',          stats.total_amendes        || 0],
      ['Taux déferrement (%)', tauxDeferrement],
      ['Taux mortalité (%)',   tauxMortalite],
    ];
    const csv = rows.map(r => r.join(';')).join('\n');
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = `dashboard_${labelPeriode.replace(/\s+/g, '_')}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-8 max-w-[1400px]">

      {/* ── Bandeau de rôle ── */}
      {isAgent && (
        <div className="flex items-center gap-3 px-4 py-2 bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl shadow-[0_1px_3px_rgba(15,23,42,0.04)]">
          <UserCheck className="w-4 h-4 text-[#2563EB] shrink-0" />
          <span className="text-xs font-semibold text-[#2563EB] uppercase tracking-wide">Agent</span>
          <span className="text-xs text-[#94A3B8] dark:text-white/30">Affichage limité à vos activités et dossiers récents.</span>
        </div>
      )}
      {isSuperviseur && (
        <div className="flex items-center gap-3 px-4 py-2 bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl shadow-[0_1px_3px_rgba(15,23,42,0.04)]">
          <ShieldAlert className="w-4 h-4 text-[#16A34A] shrink-0" />
          <span className="text-xs font-semibold text-[#16A34A] uppercase tracking-wide">Superviseur</span>
          <span className="text-xs text-[#94A3B8] dark:text-white/30">Statistiques de votre zone et dossiers à valider.</span>
        </div>
      )}
      {isSuperAdmin && (
        <div className="flex items-center gap-3 px-4 py-2 bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl shadow-[0_1px_3px_rgba(15,23,42,0.04)]">
          <Target className="w-4 h-4 text-[#D97706] shrink-0" />
          <span className="text-xs font-semibold text-[#D97706] uppercase tracking-wide">Super Administrateur</span>
          <span className="text-xs text-[#94A3B8] dark:text-white/30">Supervision nationale complète, tous territoires.</span>
        </div>
      )}

      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white">
            {isAgent ? 'Mon Tableau de Bord' :
             isSuperviseur ? 'Supervision Locale' :
             isSuperAdmin ? 'Centre de Commandement National' :
             'Supervision Globale'}
          </h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">
            {isAgent ? `Activités de ${user?.service?.nom || 'votre service'} · DSP Sénégal` :
             isSuperviseur ? 'Statistiques locales et dossiers à valider' :
             isSuperAdmin ? 'Vue décisionnelle en temps réel — DSP Sénégal' :
             'Supervision nationale — DSP Sénégal'}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          {/* Filtre année */}
          <select
            value={annee}
            onChange={e => { setAnnee(e.target.value); setMois(''); }}
            className="text-sm border border-[#E2E8F0] dark:border-white/10 rounded-lg px-3 py-1.5 bg-white dark:bg-[#1E293B] text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20"
          >
            <option value="">Toutes les années</option>
            {anneeOptions.map(y => <option key={y} value={y}>{y}</option>)}
          </select>

          {/* Filtre mois — désactive les mois futurs */}
          <select
            value={mois}
            onChange={e => setMois(e.target.value)}
            className="text-sm border border-[#E2E8F0] dark:border-white/10 rounded-lg px-3 py-1.5 bg-white dark:bg-[#1E293B] text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20"
          >
            <option value="">Tous les mois</option>
            {moisOptions.map(m => (
              <option key={m.value} value={m.value} disabled={isMoisDisabled(m.value)}>
                {m.label}{isMoisDisabled(m.value) ? ' (à venir)' : ''}
              </option>
            ))}
          </select>

          <GeoFilterComponent onChange={f => setGeoFilters(f)} />

          {/* Bouton refresh */}
          <button
            onClick={() => setRefreshKey(k => k + 1)}
            disabled={loading}
            title="Rafraîchir les données"
            className="p-1.5 rounded-lg border border-[#E2E8F0] dark:border-white/10 bg-white dark:bg-[#1E293B] text-[#64748B] dark:text-white/50 hover:text-[#2563EB] hover:border-[#2563EB] transition-colors disabled:opacity-40"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
          </button>

          {/* Export CSV */}
          <button
            onClick={handleExportCsv}
            disabled={!stats || loading}
            title="Exporter les KPI en CSV"
            className="p-1.5 rounded-lg border border-[#E2E8F0] dark:border-white/10 bg-white dark:bg-[#1E293B] text-[#64748B] dark:text-white/50 hover:text-[#16A34A] hover:border-[#16A34A] transition-colors disabled:opacity-40"
          >
            <Download className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* ── Badge période active ── */}
      <div className="flex items-center gap-3 flex-wrap">
        <PeriodeBadge annee={annee} mois={mois} geoFilters={geoFilters} currentYear={currentYear} />
        {!loading && stats && (
          <span className="text-xs text-[#94A3B8] dark:text-white/30">
            {(stats.total_infractions || 0) + (stats.total_accidents || 0)} événements · {stats.total_personnel || 0} agents actifs
          </span>
        )}
      </div>

      {/* ── Bannière erreur ── */}
      {error && (
        <div className="flex items-center gap-3 px-4 py-3 bg-[#FEF2F2] dark:bg-red-900/20 border border-[#FECACA] dark:border-red-800 rounded-xl text-sm text-[#DC2626] dark:text-red-400">
          <AlertTriangle className="w-4 h-4 shrink-0" />
          {error}
          <button onClick={() => setRefreshKey(k => k + 1)} className="ml-auto text-xs underline font-medium">Réessayer</button>
        </div>
      )}

      {/* ── KPI Cards ligne 1 ── */}
      {loading ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => <SkeletonCard key={i} />)}
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {kpis.slice(0, 4).map(k => <StatCard key={k.title} {...k} />)}
        </div>
      )}

      {/* ── Indicateurs stratégiques ligne 2 ── */}
      {loading ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => <SkeletonCard key={i} />)}
        </div>
      ) : (
        <div>
          <p className="text-xs font-semibold text-[#94A3B8] dark:text-white/30 uppercase tracking-widest mb-3">
            Indicateurs stratégiques
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {kpis.slice(4).map(k => <StatCard key={k.title} {...k} />)}
          </div>
        </div>
      )}

      {/* ── Évolution mensuelle (3 séries : infractions + accidents + immigration) ── */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <ChartCard className="lg:col-span-2">
          <SectionTitle title="Évolution Mensuelle" sub={`Infractions, accidents et immigration — ${labelPeriode}`} />
          <div className="h-[260px]">
            {tendances.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={tendances} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
                  <defs>
                    <linearGradient id="gradInfr" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%"  stopColor="#2563EB" stopOpacity={0.15} />
                      <stop offset="95%" stopColor="#2563EB" stopOpacity={0} />
                    </linearGradient>
                    <linearGradient id="gradAcc" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%"  stopColor="#DC2626" stopOpacity={0.15} />
                      <stop offset="95%" stopColor="#DC2626" stopOpacity={0} />
                    </linearGradient>
                    <linearGradient id="gradImm" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%"  stopColor="#0D9488" stopOpacity={0.15} />
                      <stop offset="95%" stopColor="#0D9488" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid stroke="#F1F5F9" vertical={false} />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 11 }} dy={8} />
                  <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 11 }} />
                  <Tooltip content={<CustomTooltip />} />
                  <Legend wrapperStyle={{ fontSize: 11, paddingTop: 8 }} />
                  <Area type="monotone" dataKey="infractions" name="Infractions" stroke="#2563EB" strokeWidth={2} fill="url(#gradInfr)" dot={false} activeDot={{ r: 4, fill: '#2563EB', strokeWidth: 0 }} />
                  <Area type="monotone" dataKey="accidents"   name="Accidents"   stroke="#DC2626" strokeWidth={2} fill="url(#gradAcc)"  dot={false} activeDot={{ r: 4, fill: '#DC2626', strokeWidth: 0 }} />
                  <Area type="monotone" dataKey="immigration" name="Immigration"  stroke="#0D9488" strokeWidth={2} fill="url(#gradImm)"  dot={false} activeDot={{ r: 4, fill: '#0D9488', strokeWidth: 0 }} />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex items-center justify-center text-sm text-[#94A3B8] dark:text-white/30 border border-dashed border-[#E2E8F0] dark:border-white/8 rounded-lg">
                Aucune donnée pour cette période
              </div>
            )}
          </div>
        </ChartCard>

        {/* Répartition accidents par type */}
        <ChartCard>
          <SectionTitle title="Répartition Accidents" sub="Par type de gravité" />
          {accidentsParType.length > 0 ? (
            <div className="space-y-4">
              <div className="h-[160px]">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={accidentsParType} cx="50%" cy="50%" innerRadius={50} outerRadius={70} paddingAngle={3} dataKey="value">
                      {accidentsParType.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '8px', border: '1px solid #E2E8F0', fontSize: 12 }} formatter={v => [`${v} accidents`]} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div className="space-y-2">
                {accidentsParType.map((entry, i) => (
                  <div key={i} className="flex items-center justify-between text-xs">
                    <div className="flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: PIE_COLORS[i % PIE_COLORS.length] }} />
                      <span className="text-[#64748B] dark:text-white/50 capitalize">{entry.name}</span>
                    </div>
                    <span className="font-semibold text-[#0F172A] dark:text-white tabular-nums">{entry.value}</span>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="h-[220px] flex items-center justify-center text-sm text-[#94A3B8] dark:text-white/30 border border-dashed border-[#E2E8F0] dark:border-white/8 rounded-lg">Aucune donnée</div>
          )}
        </ChartCard>
      </div>

      {/* ── Infractions par région ── */}
      {infractionsParRegion.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <ChartCard className="lg:col-span-2">
            <SectionTitle icon={BarChart3} title="Infractions par région"
              sub={`${labelPeriode} — classement des zones sensibles`} />
            <div className="h-[280px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={infractionsParRegion} margin={{ top: 4, right: 4, left: -10, bottom: 40 }}>
                  <CartesianGrid stroke="#F1F5F9" vertical={false} />
                  <XAxis dataKey="region" axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 10 }} angle={-35} textAnchor="end" interval={0} />
                  <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 11 }} />
                  <Tooltip content={<CustomTooltip />} />
                  <Bar dataKey="total" name="Infractions" radius={[4, 4, 0, 0]}>
                    {infractionsParRegion.map((_, i) => <Cell key={i} fill={BAR_COLORS[i % BAR_COLORS.length]} />)}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard>
            <SectionTitle icon={Target} title="Zones les plus touchées" sub="Top régions par infractions" />
            <div className="space-y-3 mt-2">
              {infractionsParRegion.slice(0, 8).map((r, i) => {
                const pct = totalInfRegion > 0 ? Math.round((r.total / totalInfRegion) * 100) : 0;
                const colors = ['bg-[#DC2626]','bg-[#D97706]','bg-[#2563EB]','bg-[#16A34A]',
                                'bg-[#7C3AED]','bg-[#0891B2]','bg-[#64748B]','bg-[#94A3B8]'];
                return (
                  <div key={r.region}>
                    <div className="flex items-center justify-between text-xs mb-1">
                      <div className="flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full shrink-0 ${colors[i % colors.length]}`} />
                        <span className="font-medium text-[#0F172A] dark:text-white truncate max-w-[110px]">{r.region}</span>
                      </div>
                      <div className="flex items-center gap-2 shrink-0">
                        <span className="font-bold text-[#0F172A] dark:text-white tabular-nums">{r.total}</span>
                        <span className="text-[#94A3B8] dark:text-white/30 w-8 text-right">{pct}%</span>
                      </div>
                    </div>
                    <div className="h-1.5 bg-[#F1F5F9] dark:bg-white/5 rounded-full overflow-hidden">
                      <div className={`h-full rounded-full transition-all duration-500 ${colors[i % colors.length]}`} style={{ width: `${pct}%` }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </ChartCard>
        </div>
      )}

      {/* ── Formes de criminalité + Effectifs ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* PieChart infractions par catégorie */}
        <ChartCard>
          <SectionTitle icon={AlertCircle} title="Formes de criminalité" sub={`Répartition par catégorie — ${labelPeriode}`} />
          {infractionsParType.length > 0 ? (
            <div className="space-y-4">
              <div className="h-[180px]">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={infractionsParType} cx="50%" cy="50%" innerRadius={55} outerRadius={80} paddingAngle={2} dataKey="value">
                      {infractionsParType.map((_, i) => <Cell key={i} fill={BAR_COLORS[i % BAR_COLORS.length]} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '8px', border: '1px solid #E2E8F0', fontSize: 12 }} formatter={v => [`${v} infractions`]} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div className="space-y-1.5 max-h-40 overflow-y-auto">
                {infractionsParType.map((t, i) => (
                  <div key={t.name} className="flex items-center justify-between text-xs py-0.5">
                    <div className="flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: BAR_COLORS[i % BAR_COLORS.length] }} />
                      <span className="text-[#64748B] dark:text-white/50 truncate max-w-[160px]">{t.name}</span>
                    </div>
                    <span className="font-semibold text-[#0F172A] dark:text-white tabular-nums shrink-0">{t.value}</span>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="h-[220px] flex items-center justify-center text-sm text-[#94A3B8] dark:text-white/30 border border-dashed border-[#E2E8F0] dark:border-white/8 rounded-lg">Aucune donnée</div>
          )}
        </ChartCard>

        {/* BarChart personnel par service */}
        <ChartCard>
          <SectionTitle icon={UserCheck} title="Effectifs par commissariat" sub="Agents actifs — répartition territoriale" />
          {personnelParService.length > 0 ? (
            <div className="space-y-2 max-h-[300px] overflow-y-auto">
              {personnelParService.slice(0, 10).map((p, i) => {
                const maxVal = personnelParService[0]?.total || 1;
                const pct    = Math.round((p.total / maxVal) * 100);
                const isLow  = p.total < 5;
                return (
                  <div key={p.service}>
                    <div className="flex items-center justify-between text-xs mb-0.5">
                      <div className="flex items-center gap-2 min-w-0">
                        <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${isLow ? 'bg-[#DC2626]' : 'bg-[#2563EB]'}`} />
                        <span className={`truncate max-w-[160px] font-medium ${isLow ? 'text-[#DC2626]' : 'text-[#0F172A] dark:text-white'}`}>
                          {p.service}
                        </span>
                        {isLow && <span className="text-[9px] bg-[#FEF2F2] text-[#DC2626] border border-[#FECACA] px-1 py-0.5 rounded font-bold shrink-0">Sous-eff.</span>}
                      </div>
                      <span className="font-bold text-[#0F172A] dark:text-white tabular-nums shrink-0 ml-2">{p.total}</span>
                    </div>
                    <div className="h-1.5 bg-[#F1F5F9] dark:bg-white/5 rounded-full overflow-hidden">
                      <div
                        className={`h-full rounded-full transition-all duration-500 ${isLow ? 'bg-[#DC2626]' : 'bg-[#2563EB]'}`}
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="h-[220px] flex items-center justify-center text-sm text-[#94A3B8] dark:text-white/30 border border-dashed border-[#E2E8F0] dark:border-white/8 rounded-lg">Aucune donnée</div>
          )}
        </ChartCard>
      </div>

      {/* ── Carte ── */}
      <ChartCard>
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
          <SectionTitle icon={MapIcon} title="Aperçu Territorial" sub="Incidents récents géolocalisés" />
          <div className="flex items-center gap-3 flex-wrap">
            <div className="flex items-center gap-4 text-xs text-[#64748B] dark:text-white/50">
              <div className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-[#2563EB]" />Infractions</div>
              <div className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-[#DC2626]" />Accidents</div>
            </div>
            {mapIncidents.length > 0 && (
              <span className="text-xs text-[#94A3B8] dark:text-white/30 font-medium">
                {mapIncidents.length} point{mapIncidents.length > 1 ? 's' : ''} affiché{mapIncidents.length > 1 ? 's' : ''}
              </span>
            )}
            <button
              onClick={() => setMapFullscreen(true)}
              title="Afficher en plein écran"
              className="p-1.5 rounded-lg border border-[#E2E8F0] dark:border-white/10 bg-white dark:bg-[#1E293B] text-[#64748B] dark:text-white/50 hover:text-[#0D9488] hover:border-[#0D9488] transition-colors"
            >
              <Maximize2 className="w-4 h-4" />
            </button>
          </div>
        </div>
        <div className="h-[360px] rounded-lg overflow-hidden border border-[#E2E8F0] dark:border-white/8 relative z-0">
          {loading && (
            <div className="absolute inset-0 z-10 bg-white/60 dark:bg-[#1E293B]/60 flex items-center justify-center">
              <div className="w-8 h-8 border-2 border-[#2563EB] border-t-transparent rounded-full animate-spin" />
            </div>
          )}
          {!loading && mapIncidents.length === 0 && (
            <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
              <div className="flex items-center gap-2 px-4 py-2 bg-[#FFFBEB] border border-[#FDE68A] text-[#92400E] rounded-lg text-xs font-medium shadow-sm">
                <span>⚠</span> Aucun point géolocalisé pour cette période
              </div>
            </div>
          )}
          <MapContainer center={SENEGAL_CENTER} zoom={7} className="w-full h-full" zoomControl scrollWheelZoom>
            <TileLayer url="https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png" />
            {mapIncidents.map((incident, idx) => (
              <CircleMarker key={idx} center={[incident.lat, incident.lng]} radius={5}
                fillOpacity={0.85}
                color={incident._type === 'accident' ? '#DC2626' : '#2563EB'}
                fillColor={incident._type === 'accident' ? '#EF4444' : '#3B82F6'}
                weight={1.5}
              >
                <Popup>
                  <div className="text-xs p-0.5">
                    <p className="font-semibold text-[#0F172A] capitalize">{incident._type} #{incident.id}</p>
                    {incident.lieu && <p className="text-[#64748B] mt-0.5">{incident.lieu}</p>}
                  </div>
                </Popup>
              </CircleMarker>
            ))}
          </MapContainer>
        </div>
      </ChartCard>

      {/* ── Carte plein écran ── */}
      {mapFullscreen && (
        <div className="fixed inset-0 z-[9999] bg-black flex flex-col">
          {/* Barre de contrôle */}
          <div className="absolute top-0 inset-x-0 z-[10000] flex items-center justify-between px-4 py-2 bg-[#0F172A]/80 backdrop-blur-sm">
            <div className="flex items-center gap-3">
              <MapIcon className="w-4 h-4 text-[#0D9488]" />
              <span className="text-sm font-semibold text-white">Aperçu Territorial — Plein écran</span>
              <div className="flex items-center gap-3 text-xs text-white/50 ml-2">
                <div className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-[#D97706]" />Infractions</div>
                <div className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-[#DC2626]" />Accidents</div>
                {mapIncidents.length > 0 && <span className="text-white/30">{mapIncidents.length} points</span>}
              </div>
            </div>
            <button
              onClick={() => setMapFullscreen(false)}
              title="Quitter le plein écran (Échap)"
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white/10 hover:bg-white/20 text-white text-xs font-medium transition-colors"
            >
              <Minimize2 className="w-3.5 h-3.5" />
              Quitter (Échap)
            </button>
          </div>
          {/* Carte */}
          <div className="flex-1 relative z-0">
            {!loading && mapIncidents.length === 0 && (
              <div className="absolute inset-x-0 top-16 z-[400] flex justify-center pointer-events-none">
                <div className="flex items-center gap-2 px-4 py-2 bg-[#FFFBEB] border border-[#FDE68A] text-[#92400E] rounded-lg text-xs font-medium shadow-sm">
                  <span>⚠</span> Aucun point géolocalisé pour cette période
                </div>
              </div>
            )}
            <MapContainer center={SENEGAL_CENTER} zoom={7} className="w-full h-full" zoomControl scrollWheelZoom>
              <TileLayer url="https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png" />
              {mapIncidents.map((incident, idx) => (
                <CircleMarker key={idx} center={[incident.lat, incident.lng]} radius={6}
                  fillOpacity={0.9}
                  color={incident._type === 'accident' ? '#DC2626' : '#2563EB'}
                  fillColor={incident._type === 'accident' ? '#EF4444' : '#3B82F6'}
                  weight={1.5}
                >
                  <Popup>
                    <div className="text-xs p-0.5">
                      <p className="font-semibold text-[#0F172A] capitalize">{incident._type} #{incident.id}</p>
                      {incident.lieu && <p className="text-[#64748B] mt-0.5">{incident.lieu}</p>}
                    </div>
                  </Popup>
                </CircleMarker>
              ))}
            </MapContainer>
          </div>
        </div>
      )}

    </div>
  );
}

