import { useState, useEffect, useCallback } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Search, Plus, Download, Edit, Trash2, Eye, X,
  AlertCircle, CheckCircle2, ChevronLeft, ChevronRight, Filter
} from 'lucide-react';
import GeoFilterComponent from '../components/GeoFilterComponent';
import WorkflowBadge, { WorkflowSelect } from '../components/WorkflowBadge';
import MediaUpload from '../components/MediaUpload';
import api from '../api/axios';
import infractionService from '../services/infractionService';
import geoService from '../services/geoService';
import { useAuth } from '../contexts/AuthContext';


const sanitizePayload = (data) => {
  const s = { ...data };
  Object.keys(s).forEach(k => { if (s[k] === '') s[k] = null; });
  return s;
};

const EMPTY_FORM = {
  type_infraction_id: '', service_id: '', annee: new Date().getFullYear(),
  date: new Date().toISOString().split('T')[0], lieu: '', commune_id: '',
  issue: 'Constatée', type_drogue: '', unite: '', quantite: '',
  latitude: '', longitude: '', description: '', workflow_status: 'En cours',
};

function Toast({ toast }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <motion.div
      initial={{ opacity: 0, y: -16 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -16 }}
      className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-lg shadow-lg text-sm font-medium border ${
        isError
          ? 'bg-[#FEF2F2] border-[#FECACA] text-[#DC2626]'
          : 'bg-[#F0FDF4] border-[#BBF7D0] text-[#16A34A]'
      }`}
    >
      {isError ? <AlertCircle className="w-4 h-4 shrink-0" /> : <CheckCircle2 className="w-4 h-4 shrink-0" />}
      {toast.message}
    </motion.div>
  );
}

function FormField({ label, error, required, children }) {
  return (
    <div>
      <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">
        {label}{required && <span className="text-[#DC2626] ml-0.5">*</span>}
      </label>
      {children}
      {error && <p className="text-[#DC2626] text-xs mt-1">{error[0]}</p>}
    </div>
  );
}

const inputCls = "w-full h-9 px-3 text-sm bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all";
const selectCls = inputCls;

const SENEGAL_BOUNDS = { latMin: 12, latMax: 17, lngMin: -18, lngMax: -11 };

const isValidSenegalCoord = (lat, lng) =>
  lat >= SENEGAL_BOUNDS.latMin && lat <= SENEGAL_BOUNDS.latMax &&
  lng >= SENEGAL_BOUNDS.lngMin && lng <= SENEGAL_BOUNDS.lngMax;

export default function Infractions() {
  const { user } = useAuth();
  const [infractions, setInfractions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({ page: 1, per_page: 10 });
  const [meta, setMeta] = useState(null);
  const [selectedInfraction, setSelectedInfraction] = useState(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [formMode, setFormMode] = useState('create');
  const [typesInfractions, setTypesInfractions] = useState([]);
  const [communes, setCommunes] = useState([]);
  const [services, setServices] = useState([]);
  const [formData, setFormData] = useState(EMPTY_FORM);
  const [formErrors, setFormErrors] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [toast, setToast] = useState(null);

  const fetchInfractions = useCallback(async () => {
    setLoading(true);
    try {
      const res = await infractionService.getAll({ ...filters, search: search || undefined });
      setInfractions(res.data.data || []);
      setMeta(res.data.meta || null);
    } catch {
      showToast('Erreur lors de la récupération des infractions', 'error');
    } finally {
      setLoading(false);
    }
  }, [filters, search]);

  useEffect(() => { fetchInfractions(); }, [fetchInfractions]);

  useEffect(() => {
    const fetchAux = async () => {
      try {
        const [resTypes, resCommunes, resServices] = await Promise.all([
          infractionService.getTypes(), geoService.getAllCommunes(), geoService.getAllServices(),
        ]);
        setTypesInfractions(resTypes.data.data || resTypes.data || []);
        setCommunes(resCommunes.data.data || resCommunes.data || []);
        setServices(resServices.data.data || resServices.data || []);
      } catch (e) { console.error(e); }
    };
    fetchAux();
  }, []);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const handlePageChange = (page) => {
    if (page >= 1 && page <= (meta?.last_page || 1)) setFilters(p => ({ ...p, page }));
  };

  const handleOpenCreate = () => {
    setFormMode('create');
    setFormData({ ...EMPTY_FORM, service_id: user?.service_id || '' });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenEdit = (infraction) => {
    const minsElapsed = (new Date() - new Date(infraction.created_at)) / 60000;
    const isAdmin = user?.roles?.some(r => r.name === 'admin' || r.name === 'super_admin');
    if (minsElapsed > 1 && !isAdmin) {
      showToast('Modification impossible : le délai réglementaire de 1 minute est dépassé.', 'error');
      return;
    }
    setFormMode('edit');
    setSelectedInfraction(infraction);
    setFormData({
      type_infraction_id: infraction.type_infraction_id || '',
      service_id: infraction.service_id || '',
      annee: infraction.annee || new Date().getFullYear(),
      date: infraction.date ? infraction.date.split('T')[0] : '',
      lieu: infraction.lieu || '',
      commune_id: infraction.commune_id || '',
      issue: infraction.issue || 'Constatée',
      type_drogue: infraction.type_drogue || '',
      unite: infraction.unite || '',
      quantite: infraction.quantite || '',
      latitude: infraction.latitude || '',
      longitude: infraction.longitude || '',
      description: infraction.description || '',
      workflow_status: infraction.workflow_status || 'En cours',
    });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenDetail = async (infraction) => {
    try {
      const res = await infractionService.getOne(infraction.id);
      setSelectedInfraction(res.data.data || infraction);
      setIsDetailOpen(true);
    } catch { showToast('Erreur lors de la récupération des détails', 'error'); }
  };

  const handleDelete = async (id) => {
    if (!confirm('Voulez-vous vraiment supprimer cette infraction de manière irréversible ?')) return;
    try {
      await infractionService.delete(id);
      showToast('Infraction supprimée avec succès.');
      fetchInfractions();
    } catch (err) {
      showToast(err.response?.data?.message || 'Erreur de suppression.', 'error');
    }
  };

  const isDrugRelated = () => {
    if (!formData.type_infraction_id) return false;
    const t = typesInfractions.find(t => String(t.id) === String(formData.type_infraction_id));
    if (!t) return false;
    const terms = ['drogue', 'stupéfiant', 'narcot', 'cannabis'];
    return terms.some(w =>
      (t.nom || '').toLowerCase().includes(w) ||
      (t.description || '').toLowerCase().includes(w) ||
      (t.categorie_infraction?.nom || '').toLowerCase().includes(w)
    );
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    setActionLoading(true);
    setFormErrors(null);
    const lat = parseFloat(formData.latitude);
    const lng = parseFloat(formData.longitude);
    const validCoords = isValidSenegalCoord(lat, lng)
      ? { latitude: lat, longitude: lng }
      : { latitude: null, longitude: null };
    const isDrug = isDrugRelated();
    const payload = sanitizePayload({
      ...formData,
      type_drogue: isDrug ? formData.type_drogue : null,
      unite: isDrug ? formData.unite : null,
      quantite: isDrug && formData.quantite ? parseFloat(formData.quantite) : null,
      ...validCoords,
    });
    try {
      if (formMode === 'create') { await infractionService.create(payload); showToast('Infraction enregistrée avec succès.'); }
      else { await infractionService.update(selectedInfraction.id, payload); showToast('Infraction mise à jour avec succès.'); }
      setIsFormOpen(false);
      fetchInfractions();
    } catch (err) {
      if (err.response?.status === 422) setFormErrors(err.response.data.errors);
      else showToast(err.response?.data?.message || 'Une erreur est survenue.', 'error');
    } finally {
      setActionLoading(false);
    }
  };

  const handleExportCSV = async () => {
    try {
      const res = await api.get('/export/infractions/csv', { params: filters, responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a');
      a.href = url;
      a.setAttribute('download', `infractions_${Date.now()}.csv`);
      document.body.appendChild(a);
      a.click();
      a.remove();
      showToast('Export CSV réussi.');
    } catch { showToast("Erreur lors de l'exportation.", 'error'); }
  };

  const filteredServices = formData.commune_id
    ? services.filter(s => String(s.commune_id) === String(formData.commune_id))
    : services;
  const displayedServices = filteredServices.length > 0 ? filteredServices : services;

  return (
    <div className="space-y-6 max-w-[1400px]">
      <AnimatePresence>
        {toast && <Toast toast={toast} />}
      </AnimatePresence>

      {/* Page header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white">Gestion des Infractions</h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">Consultez et gérez les infractions constatées sur le territoire</p>
        </div>
        <div className="flex items-center gap-2 w-full sm:w-auto">
          <button
            onClick={handleExportCSV}
            className="flex items-center gap-1.5 h-9 px-4 text-sm font-medium text-[#0F172A] dark:text-white bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors"
          >
            <Download className="w-4 h-4" /> Export CSV
          </button>
          <button
            onClick={handleOpenCreate}
            className="flex items-center gap-1.5 h-9 px-4 text-sm font-medium text-white bg-[#2563EB] rounded-lg hover:bg-[#1D4ED8] transition-colors"
          >
            <Plus className="w-4 h-4" /> Nouvelle Infraction
          </button>
        </div>
      </div>

      {/* Filters bar */}
