          className="w-full max-w-[450px]"
        >
          {/* Carte */}
          <div className="bg-white dark:bg-[#111827] border border-[#E2E8F0] dark:border-white/[0.08] rounded-[20px] p-8 shadow-xl shadow-black/[0.06] dark:shadow-black/40">

            {/* En-tête */}
            <div className="flex flex-col items-center mb-8">
