import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Bell, Send, Search, RefreshCw, CheckCheck, Check,
  X, Globe, User, ChevronLeft, ChevronRight, Archive,
  AlertCircle, CheckCircle, Info,
} from 'lucide-react';
import notificationService from '../services/notificationService';
import api from '../api/axios';
import { useAuth } from '../contexts/AuthContext';

function Toast({ toast }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <motion.div
      initial={{ opacity: 0, y: -16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -16 }}
      className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-lg shadow-lg text-sm font-medium border ${
        isError ? 'bg-[#FEF2F2] border-[#FECACA] text-[#DC2626]' : 'bg-[#F0FDF4] border-[#BBF7D0] text-[#16A34A]'
      }`}
    >
      {isError ? <AlertCircle className="w-4 h-4 shrink-0" /> : <CheckCircle className="w-4 h-4 shrink-0" />}
      {toast.message}
    </motion.div>
  );
}

const inputCls = 'w-full text-sm border border-[#E2E8F0] dark:border-white/10 rounded-lg py-2 px-3 bg-[#F8FAFC] dark:bg-white/5 text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-colors placeholder-[#94A3B8] dark:placeholder-white/30';

export default function Notifications() {
  const { user } = useAuth();
  const isAdmin = user?.role === 'super_admin' || user?.role === 'admin';

  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [meta, setMeta] = useState(null);
  const [search, setSearch] = useState('');
  const [filterRead, setFilterRead] = useState('');
  const [archived, setArchived] = useState([]);
  const [toast, setToast] = useState(null);

  // Send form state
  const [sendOpen, setSendOpen] = useState(false);
  const [sendForm, setSendForm] = useState({ title: '', message: '', type: 'info', user_id: '' });
  const [sendMode, setSendMode] = useState('global'); // 'global' | 'targeted'
  const [users, setUsers] = useState([]);
  const [sending, setSending] = useState(false);
  const [preview, setPreview] = useState(false);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const fetchNotifications = useCallback(async (p = 1) => {
    setLoading(true);
    try {
      const r = await notificationService.getAll({ page: p, per_page: 15 });
      const raw = r.data;
      const items = Array.isArray(raw) ? raw : (Array.isArray(raw?.data) ? raw.data : []);
      setNotifications(items);
      setMeta(raw?.meta || null);
    } catch {
      setNotifications([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchNotifications(page); }, [fetchNotifications, page]);

  useEffect(() => {
    if (isAdmin) {
      api.get('/users', { params: { per_page: 200 } })
        .then(r => {
          const raw = r.data;
          setUsers(Array.isArray(raw) ? raw : (Array.isArray(raw?.data) ? raw.data : []));
        })
        .catch(() => {});
    }
  }, [isAdmin]);

  const handleMarkRead = async (id) => {
    try {
      await notificationService.markAsRead(id);
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n));
    } catch {
      showToast("Erreur lors du marquage.", 'error');
    }
  };

  const handleMarkAll = async () => {
    try {
      await notificationService.markAllAsRead();
      setNotifications(prev => prev.map(n => ({ ...n, read_at: n.read_at || new Date().toISOString() })));
      showToast("Toutes les notifications marquées comme lues.");
    } catch {
      showToast("Erreur lors du marquage.", 'error');
    }
  };

  const handleArchive = (id) => {
    setArchived(prev => prev.includes(id) ? prev.filter(a => a !== id) : [...prev, id]);
  };

  const handleSend = async () => {
    if (!sendForm.title.trim() || !sendForm.message.trim()) {
      showToast("Le titre et le message sont requis.", 'error');
      return;
    }
    setSending(true);
    try {
      const payload = {
        title: sendForm.title,
        message: sendForm.message,
        type: sendForm.type,
        ...(sendMode === 'targeted' && sendForm.user_id ? { user_id: sendForm.user_id } : {}),
      };
      await notificationService.send(payload);
      showToast(sendMode === 'global' ? "Notification globale envoyée avec succès." : "Notification envoyée à l'utilisateur.");
      setSendForm({ title: '', message: '', type: 'info', user_id: '' });
      setSendOpen(false);
      setPreview(false);
      fetchNotifications();
    } catch (e) {
      showToast(e.response?.data?.message || "Erreur lors de l'envoi.", 'error');
    } finally {
      setSending(false);
    }
  };

  const displayed = notifications.filter(n => {
    if (archived.includes(n.id)) return false;
    const titleText = (n.title || n.titre || '').toLowerCase();
    const msgText = (n.message || '').toLowerCase();
    if (search && !titleText.includes(search.toLowerCase()) && !msgText.includes(search.toLowerCase())) return false;
    if (filterRead === 'unread' && n.read_at) return false;
    if (filterRead === 'read' && !n.read_at) return false;
    return true;
  });

  const unreadCount = notifications.filter(n => !n.read_at && !archived.includes(n.id)).length;
  const archivedCount = archived.length;

  const TYPE_ICON = {
    info:    <Info className="w-4 h-4 text-white" />,
    success: <CheckCircle className="w-4 h-4 text-white" />,
    warning: <AlertCircle className="w-4 h-4 text-white" />,
    error:   <AlertCircle className="w-4 h-4 text-white" />,
  };

  const TYPE_BG = {
    info:    'bg-[#2563EB]',
    success: 'bg-[#16A34A]',
    warning: 'bg-[#D97706]',
    error:   'bg-[#DC2626]',
  };

  const TYPE_ACCENT = {
    info:    '#2563EB',
    success: '#16A34A',
    warning: '#D97706',
    error:   '#DC2626',
  };

  return (
    <div className="space-y-6 max-w-[1200px]">
      <AnimatePresence>{toast && <Toast toast={toast} />}</AnimatePresence>

      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white flex items-center gap-2">
            <Bell className="w-6 h-6 text-[#2563EB]" />
            Notifications
          </h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">
            Centre de notifications — {unreadCount} non lue{unreadCount !== 1 ? 's' : ''}
            {archivedCount > 0 && ` · ${archivedCount} archivée${archivedCount !== 1 ? 's' : ''}`}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {unreadCount > 0 && (
            <button
              onClick={handleMarkAll}
              className="inline-flex items-center gap-2 px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 hover:bg-[#F1F5F9] dark:hover:bg-white/10 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-xs font-semibold text-[#475569] dark:text-white/60 transition-colors"
            >
              <CheckCheck className="w-3.5 h-3.5" />
              Tout marquer lu
            </button>
          )}
          <button
            onClick={fetchNotifications}
            className="inline-flex items-center gap-2 px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 hover:bg-[#F1F5F9] dark:hover:bg-white/10 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-xs font-semibold text-[#475569] dark:text-white/60 transition-colors"
          >
            <RefreshCw className="w-3.5 h-3.5" />
            Rafraîchir
          </button>
          {isAdmin && (
            <button
              onClick={() => { setSendOpen(true); setPreview(false); }}
              className="inline-flex items-center gap-2 px-4 py-2 bg-[#2563EB] hover:bg-[#1D4ED8] text-white rounded-lg text-xs font-semibold transition-colors shadow-sm"
            >
              <Send className="w-3.5 h-3.5" />
              Envoyer
            </button>
          )}
        </div>
      </div>

      {/* Send panel (admin only) */}
      <AnimatePresence>
        {sendOpen && isAdmin && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="overflow-hidden"
          >
            <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 space-y-4">
              <div className="flex items-center justify-between">
                <p className="text-sm font-semibold text-[#0F172A] dark:text-white flex items-center gap-2">
                  <Send className="w-4 h-4 text-[#2563EB]" />
                  Envoyer une notification
                </p>
                <button onClick={() => { setSendOpen(false); setPreview(false); }} className="text-[#94A3B8] hover:text-[#475569] dark:hover:text-white/60">
                  <X className="w-4 h-4" />
                </button>
              </div>

              {/* Mode selector */}
              <div className="flex gap-2">
                {[
                  { key: 'global', label: 'Notification globale', icon: <Globe className="w-3.5 h-3.5" /> },
                  { key: 'targeted', label: 'Ciblée', icon: <User className="w-3.5 h-3.5" /> },
                ].map(m => (
                  <button
                    key={m.key}
                    onClick={() => setSendMode(m.key)}
                    className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold border transition-colors ${
                      sendMode === m.key
                        ? 'bg-[#2563EB] text-white border-[#2563EB]'
                        : 'bg-[#F8FAFC] dark:bg-white/5 text-[#475569] dark:text-white/60 border-[#E2E8F0] dark:border-white/10 hover:bg-[#F1F5F9]'
                    }`}
                  >
                    {m.icon}
                    {m.label}
                  </button>
                ))}
              </div>

              {preview ? (
                /* Preview */
                <div className="space-y-4">
                  <div className={`p-4 rounded-xl border ${TYPE_BG[sendForm.type] || TYPE_BG.info} border-[#E2E8F0] dark:border-white/10`}>
                    <div className="flex items-start gap-3">
                      <div className="mt-0.5">{TYPE_ICON[sendForm.type] || TYPE_ICON.info}</div>
                      <div>
                        <p className="font-semibold text-[#0F172A] dark:text-white text-sm">{sendForm.title || '(sans titre)'}</p>
                        <p className="text-xs text-[#64748B] dark:text-white/50 mt-1 whitespace-pre-wrap">{sendForm.message || '(aucun message)'}</p>
                        {sendMode === 'targeted' && sendForm.user_id && (
                          <p className="text-[10px] text-[#94A3B8] dark:text-white/30 mt-1.5">
                            → {users.find(u => String(u.id) === String(sendForm.user_id))?.name || 'Utilisateur sélectionné'}
                          </p>
                        )}
                        {sendMode === 'global' && (
                          <p className="text-[10px] text-[#94A3B8] dark:text-white/30 mt-1.5">→ Tous les utilisateurs</p>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setPreview(false)} className="px-4 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-xs font-semibold text-[#475569] dark:text-white/60 hover:bg-[#F1F5F9] transition-colors">
                      Modifier
                    </button>
                    <button onClick={handleSend} disabled={sending} className="px-4 py-2 bg-[#2563EB] hover:bg-[#1D4ED8] text-white rounded-lg text-xs font-semibold disabled:opacity-50 transition-colors">
                      {sending ? 'Envoi…' : 'Confirmer l\'envoi'}
                    </button>
                  </div>
                </div>
              ) : (
                /* Form */
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-[#64748B] dark:text-white/50">Titre *</label>
                    <input
                      type="text"
                      value={sendForm.title}
                      onChange={e => setSendForm(p => ({ ...p, title: e.target.value }))}
                      placeholder="Titre de la notification"
                      className={inputCls}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-semibold text-[#64748B] dark:text-white/50">Type</label>
                    <select
                      value={sendForm.type}
                      onChange={e => setSendForm(p => ({ ...p, type: e.target.value }))}
                      className={inputCls}
                    >
                      <option value="info">Info</option>
                      <option value="success">Succès</option>
                      <option value="warning">Avertissement</option>
                      <option value="error">Erreur</option>
                    </select>
                  </div>
                  <div className="md:col-span-2 space-y-1.5">
                    <label className="text-xs font-semibold text-[#64748B] dark:text-white/50">Message *</label>
                    <textarea
                      value={sendForm.message}
                      onChange={e => setSendForm(p => ({ ...p, message: e.target.value }))}
                      rows={3}
                      placeholder="Contenu de la notification…"
                      className={`${inputCls} resize-none`}
                    />
                  </div>
                  {sendMode === 'targeted' && (
                    <div className="md:col-span-2 space-y-1.5">
                      <label className="text-xs font-semibold text-[#64748B] dark:text-white/50">Destinataire *</label>
                      <select
                        value={sendForm.user_id}
                        onChange={e => setSendForm(p => ({ ...p, user_id: e.target.value }))}
                        className={inputCls}
                      >
                        <option value="">— Sélectionner un utilisateur —</option>
                        {users.map(u => (
                          <option key={u.id} value={u.id}>{u.name} ({u.email})</option>
                        ))}
                      </select>
                    </div>
                  )}
                  <div className="md:col-span-2 flex gap-2">
                    <button
                      onClick={() => setPreview(true)}
                      disabled={!sendForm.title.trim() || !sendForm.message.trim()}
                      className="px-4 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-xs font-semibold text-[#475569] dark:text-white/60 hover:bg-[#F1F5F9] disabled:opacity-40 transition-colors"
                    >
                      Aperçu
                    </button>
                    <button
                      onClick={handleSend}
                      disabled={sending || !sendForm.title.trim() || !sendForm.message.trim() || (sendMode === 'targeted' && !sendForm.user_id)}
                      className="px-4 py-2 bg-[#2563EB] hover:bg-[#1D4ED8] text-white rounded-lg text-xs font-semibold disabled:opacity-50 transition-colors"
                    >
                      {sending ? 'Envoi…' : 'Envoyer'}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Filter bar */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-4 flex flex-col sm:flex-row gap-3 items-center">
        <div className="relative flex-1 w-full sm:max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
          <input
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Rechercher une notification…"
            className="w-full pl-9 pr-4 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-colors"
          />
        </div>
        <select
          value={filterRead}
          onChange={e => setFilterRead(e.target.value)}
          className="h-9 px-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 transition-colors"
        >
          <option value="">Toutes</option>
          <option value="unread">Non lues</option>
          <option value="read">Lues</option>
        </select>
      </div>

      {/* Notification list */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl overflow-hidden">
        {loading ? (
          <div className="divide-y divide-[#F1F5F9] dark:divide-white/5">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="px-5 py-4 flex gap-3 animate-pulse">
                <div className="w-9 h-9 rounded-lg bg-[#F1F5F9] dark:bg-white/5 shrink-0" />
                <div className="flex-1 space-y-2">
                  <div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-48" />
                  <div className="h-3 bg-[#F1F5F9] dark:bg-white/5 rounded w-72" />
                </div>
              </div>
            ))}
          </div>
        ) : displayed.length === 0 ? (
          <div className="px-5 py-16 text-center text-sm text-[#94A3B8] dark:text-white/30">
            Aucune notification{search ? ` pour « ${search} »` : ''}.
          </div>
        ) : (
          <div className="divide-y divide-[#F1F5F9] dark:divide-white/5">
            {displayed.map(n => {
              const title = n.title || n.titre || 'Notification';
              const message = n.message || '';
              const nType = n.type || 'info';
              const isRead = !!n.read_at;
              return (
                <div
                  key={n.id}
                  className={`px-5 py-4 flex items-start gap-3 transition-colors ${isRead ? '' : 'bg-[#EFF6FF]/30 dark:bg-[#2563EB]/5'}`}
                >
                  <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${TYPE_BG[nType] || TYPE_BG.info}`}>
                    {TYPE_ICON[nType] || TYPE_ICON.info}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-2">
                      <p className={`text-sm font-semibold truncate ${isRead ? 'text-[#475569] dark:text-white/60' : 'text-[#0F172A] dark:text-white'}`}>
                        {title}
                        {!isRead && <span className="ml-2 inline-block w-1.5 h-1.5 rounded-full bg-[#2563EB] align-middle" />}
                      </p>
                      <p className="text-[10px] text-[#94A3B8] dark:text-white/30 shrink-0">
                        {n.created_at ? new Date(n.created_at).toLocaleString('fr-FR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—'}
                      </p>
                    </div>
                    {message && <p className="text-xs text-[#64748B] dark:text-white/40 mt-0.5 line-clamp-2">{message}</p>}
                  </div>
                  <div className="flex items-center gap-1 shrink-0">
                    {!isRead && (
                      <button
                        onClick={() => handleMarkRead(n.id)}
                        title="Marquer comme lu"
                        className="p-1.5 rounded-lg text-[#94A3B8] hover:text-[#2563EB] hover:bg-[#EFF6FF] dark:hover:bg-[#2563EB]/20 transition-colors"
                      >
                        <Check className="w-3.5 h-3.5" />
                      </button>
                    )}
                    <button
                      onClick={() => handleArchive(n.id)}
                      title="Archiver"
                      className="p-1.5 rounded-lg text-[#94A3B8] hover:text-[#D97706] hover:bg-[#FFFBEB] dark:hover:bg-[#D97706]/20 transition-colors"
                    >
                      <Archive className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {meta && meta.last_page > 1 && (
          <div className="px-5 py-3 border-t border-[#E2E8F0] dark:border-white/8 flex items-center justify-between text-xs text-[#64748B] dark:text-white/40">
            <span>{meta.from}–{meta.to} sur {meta.total} entrées</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/10 disabled:opacity-40 hover:bg-[#F8FAFC] dark:hover:bg-white/5 transition-colors">
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="px-3 py-1 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-md font-medium">
                {meta.current_page || page} / {meta.last_page}
              </span>
              <button onClick={() => setPage(p => Math.min(meta.last_page, p + 1))} disabled={page === meta.last_page}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/10 disabled:opacity-40 hover:bg-[#F8FAFC] dark:hover:bg-white/5 transition-colors">
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Search, Plus, Trash2, Edit, Eye, X, AlertCircle, CheckCircle2,
  ChevronLeft, ChevronRight, Users as UsersIcon, Award, Phone, Landmark, Calendar, ShieldAlert
} from 'lucide-react';
import personnelService from '../services/personnelService';
import geoService from '../services/geoService';
import { useAuth } from '../contexts/AuthContext';
import { mockPersonnel } from '../services/mockData';

const inputCls = "w-full h-9 px-3 text-sm bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all";

function Toast({ toast }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <motion.div initial={{ opacity: 0, y: -16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -16 }}
      className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-lg shadow-lg text-sm font-medium border ${
        isError ? 'bg-[#FEF2F2] border-[#FECACA] text-[#DC2626]' : 'bg-[#F0FDF4] border-[#BBF7D0] text-[#16A34A]'
      }`}
    >
      {isError ? <AlertCircle className="w-4 h-4 shrink-0" /> : <CheckCircle2 className="w-4 h-4 shrink-0" />}
      {toast.message}
    </motion.div>
  );
}

function FormField({ label, error, required, children }) {
  return (
    <div>
      <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">
        {label}{required && <span className="text-[#DC2626] ml-0.5">*</span>}
      </label>
      {children}
      {error && <p className="text-[#DC2626] text-xs mt-1">{Array.isArray(error) ? error[0] : error}</p>}
    </div>
  );
}

function SectionHeader({ children }) {
  return <p className="text-[10px] font-semibold text-[#94A3B8] dark:text-white/30 uppercase tracking-widest mb-3">{children}</p>;
}

const STATUT_BADGE = {
  Actif: 'bg-[#F0FDF4] text-[#16A34A] border-[#BBF7D0]',
  Mission: 'bg-[#EFF6FF] text-[#2563EB] border-[#BFDBFE]',
  Inactif: 'bg-[#F1F5F9] text-[#64748B] border-[#E2E8F0]',
};

const EMPTY_FORM = {
  ccap: '', prenom: '', nom: '', grade: '', telephone: '',
  anciennete: '', date_entree_corps: '', sexe: 'M',
  situation_matrimoniale: 'Célibataire', date_naissance: '',
  lieu_naissance: '', service_id: '', statut: 'Actif', sanction: '',
};

export default function Personnel() {
  const { user } = useAuth();
  const [agents, setAgents] = useState([]);
  const [isMockData, setIsMockData] = useState(false);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({ page: 1, per_page: 10, statut: '', grade: '' });
  const [meta, setMeta] = useState(null);
  const [selectedAgent, setSelectedAgent] = useState(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [formMode, setFormMode] = useState('create');
  const [services, setServices] = useState([]);
  const [formData, setFormData] = useState(EMPTY_FORM);
  const [formErrors, setFormErrors] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const fetchAgents = useCallback(async () => {
    setLoading(true);
    try {
      const res = await personnelService.getAll({
        ...filters,
        search: search || undefined,
        statut: filters.statut || undefined,
        grade: filters.grade || undefined,
      });
      const data = res.data.data || [];
      if (data.length > 0) { setAgents(data); setIsMockData(false); }
      else { setAgents(mockPersonnel(12)); setIsMockData(true); }
      setMeta(res.data.meta || null);
    } catch {
      setAgents(mockPersonnel(12)); setIsMockData(true);
    } finally { setLoading(false); }
  }, [filters, search]);

  useEffect(() => { fetchAgents(); }, [fetchAgents]);
  useEffect(() => {
    geoService.getAllServices()
      .then(r => setServices(r.data.data || r.data || []))
      .catch(e => console.error(e));
  }, []);

  const handlePageChange = (p) => {
    if (p >= 1 && p <= (meta?.last_page || 1)) setFilters(prev => ({ ...prev, page: p }));
  };

  const handleOpenCreate = () => {
    setFormMode('create');
    setFormData({ ...EMPTY_FORM, service_id: user?.service_id || '' });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenEdit = (agent) => {
    setFormMode('edit');
    setSelectedAgent(agent);
    setFormData({
      ccap: agent.ccap || '', prenom: agent.prenom || '', nom: agent.nom || '',
      grade: agent.grade || '', telephone: agent.telephone || '',
      anciennete: agent.anciennete ?? '', date_entree_corps: agent.date_entree_corps ? agent.date_entree_corps.split('T')[0] : '',
      sexe: agent.sexe || 'M', situation_matrimoniale: agent.situation_matrimoniale || 'Célibataire',
      date_naissance: agent.date_naissance ? agent.date_naissance.split('T')[0] : '',
      lieu_naissance: agent.lieu_naissance || '', service_id: agent.service_id || '',
      statut: agent.statut || 'Actif', sanction: agent.sanction || '',
    });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenDetail = async (agent) => {
    try {
      const res = await personnelService.getOne(agent.id);
      setSelectedAgent(res.data.data || res.data || agent);
    } catch { setSelectedAgent(agent); }
    setIsDetailOpen(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setActionLoading(true);
    setFormErrors(null);
    const sanitized = {};
    Object.keys(formData).forEach(k => { sanitized[k] = formData[k] === '' ? null : formData[k]; });
    const payload = { ...sanitized, anciennete: sanitized.anciennete !== null ? parseInt(sanitized.anciennete) : null };
    try {
      if (formMode === 'create') { await personnelService.create(payload); showToast('Agent créé avec succès !'); }
      else { await personnelService.update(selectedAgent.id, payload); showToast('Fiche agent mise à jour !'); }
      setIsFormOpen(false);
      fetchAgents();
    } catch (err) {
      if (err.response?.status === 422) { setFormErrors(err.response.data.errors || {}); showToast('Veuillez corriger les erreurs', 'error'); }
      else showToast(err.response?.data?.message || "Erreur lors de l'enregistrement", 'error');
    } finally { setActionLoading(false); }
  };

  const handleDelete = async (id) => {
    if (!confirm("Êtes-vous sûr de vouloir supprimer cet agent ? Cette action est irréversible.")) return;
    try {
      await personnelService.delete(id);
      showToast('Agent supprimé avec succès !');
      fetchAgents();
    } catch (err) { showToast(err.response?.data?.message || 'Erreur lors de la suppression', 'error'); }
  };

  const setField = (key, value) => setFormData(p => ({ ...p, [key]: value }));

  return (
    <div className="space-y-6 max-w-[1400px]">
      <AnimatePresence>{toast && <Toast toast={toast} />}</AnimatePresence>

      {isMockData && (
        <div className="flex items-center gap-2 px-4 py-2.5 bg-[#FFFBEB] border border-[#FDE68A] text-[#92400E] rounded-lg text-xs font-medium">
          <span className="shrink-0">⚠</span>
          Données de démonstration — connexion API indisponible. Les données affichées sont fictives.
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white">Gestion des Effectifs</h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">Registre national DSP : officiers, gradés et agents de terrain</p>
        </div>
        <button onClick={handleOpenCreate} className="flex items-center gap-1.5 h-9 px-4 text-sm font-medium text-white bg-[#2563EB] rounded-lg hover:bg-[#1D4ED8] transition-colors">
          <Plus className="w-4 h-4" /> Ajouter un Agent
        </button>
      </div>

      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-3 flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] dark:text-white/30" />
          <input type="text" value={search} onChange={(e) => { setSearch(e.target.value); setFilters(p => ({ ...p, page: 1 })); }}
            placeholder="Rechercher par nom, CCAP, grade..."
            className="w-full h-9 pl-9 pr-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all" />
        </div>
        <select value={filters.statut} onChange={(e) => setFilters(p => ({ ...p, page: 1, statut: e.target.value }))}
          className="h-9 px-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20">
          <option value="">Tous les statuts</option>
          <option value="Actif">Actif</option>
          <option value="Inactif">Inactif</option>
          <option value="Mission">Mission</option>
        </select>
      </div>

      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[#F1F5F9] dark:border-white/5 bg-[#F8FAFC] dark:bg-white/5">
                {['CCAP', 'Agent', 'Grade', 'Affectation', 'Téléphone', 'Statut', 'Actions'].map((h, i) => (
                  <th key={h} className={`px-4 py-3 text-xs font-semibold text-[#64748B] dark:text-white/50 uppercase tracking-wide ${i === 6 ? 'text-right' : 'text-left'}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-[#F1F5F9] dark:divide-white/5">
              {loading ? (
                [...Array(5)].map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    {[...Array(7)].map((_, j) => <td key={j} className="px-4 py-4"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded" /></td>)}
                  </tr>
                ))
              ) : agents.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-16 text-center">
                    <UsersIcon className="w-8 h-8 text-[#CBD5E1] mx-auto mb-2" />
                    <p className="text-sm text-[#94A3B8] dark:text-white/30">Aucun agent répertorié.</p>
                  </td>
                </tr>
              ) : (
                agents.map(p => {
                  const badgeCls = STATUT_BADGE[p.statut] || STATUT_BADGE.Inactif;
                  return (
                    <tr key={p.id} className="hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors group">
                      <td className="px-4 py-3 font-mono text-xs font-bold text-[#2563EB]">{p.ccap}</td>
                      <td className="px-4 py-3">
                        <p className="font-semibold text-[#0F172A] dark:text-white text-sm">{p.prenom} {p.nom}</p>
                      </td>
                      <td className="px-4 py-3 text-xs text-[#64748B] dark:text-white/50 font-medium">{p.grade || '-'}</td>
                      <td className="px-4 py-3 text-xs text-[#64748B] dark:text-white/50">{p.service?.nom || '-'}</td>
                      <td className="px-4 py-3 font-mono text-xs text-[#64748B] dark:text-white/50">{p.telephone || '-'}</td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border ${badgeCls}`}>
                          {p.statut || 'Inactif'}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button onClick={() => handleOpenDetail(p)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#2563EB] hover:bg-[#EFF6FF] transition-colors"><Eye className="w-4 h-4" /></button>
                          <button onClick={() => handleOpenEdit(p)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#D97706] hover:bg-[#FFFBEB] transition-colors"><Edit className="w-4 h-4" /></button>
                          <button onClick={() => handleDelete(p.id)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#DC2626] hover:bg-[#FEF2F2] transition-colors"><Trash2 className="w-4 h-4" /></button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
        {meta && meta.last_page > 1 && (
          <div className="px-4 py-3 border-t border-[#F1F5F9] dark:border-white/5 flex flex-col sm:flex-row justify-between items-center gap-2 text-xs text-[#64748B] dark:text-white/50">
            <span>{meta.from}–{meta.to} sur {meta.total} agents</span>
            <div className="flex items-center gap-1">
              <button onClick={() => handlePageChange(filters.page - 1)} disabled={filters.page === 1}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/8 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="px-3 py-1 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-md font-medium">{filters.page} / {meta.last_page}</span>
              <button onClick={() => handlePageChange(filters.page + 1)} disabled={filters.page === meta.last_page}
                className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/8 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* MODAL FORM */}
      <AnimatePresence>
        {isFormOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 overflow-y-auto">
            <motion.div initial={{ scale: 0.96, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.96, opacity: 0 }} transition={{ duration: 0.15 }}
              className="bg-white dark:bg-[#1E293B] rounded-xl w-full max-w-3xl flex flex-col shadow-2xl overflow-hidden border border-[#E2E8F0] dark:border-white/8 my-auto">
              <div className="px-6 py-4 border-b border-[#F1F5F9] dark:border-white/5 flex items-center justify-between shrink-0">
                <h3 className="text-base font-semibold text-[#0F172A] dark:text-white">
                  {formMode === 'create' ? 'Ajouter un Agent' : "Modifier la fiche de l'agent"}
                </h3>
                <button onClick={() => setIsFormOpen(false)} className="p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/5 transition-colors"><X className="w-4 h-4" /></button>
              </div>
              <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 space-y-6 max-h-[80vh]">
                {/* Section 1: État Civil */}
                <div>
                  <SectionHeader>État Civil & Identification</SectionHeader>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <FormField label="CCAP" error={formErrors?.ccap} required>
                      <input type="text" value={formData.ccap} onChange={e => setField('ccap', e.target.value)}
                        placeholder="Ex: 504/A" className={`${inputCls} font-mono`} required disabled={formMode === 'edit'} />
                    </FormField>
                    <FormField label="Prénom" error={formErrors?.prenom} required>
                      <input type="text" value={formData.prenom} onChange={e => setField('prenom', e.target.value)}
                        placeholder="Ex: Ousmane" className={inputCls} required />
                    </FormField>
                    <FormField label="Nom" error={formErrors?.nom} required>
                      <input type="text" value={formData.nom} onChange={e => setField('nom', e.target.value)}
                        placeholder="Ex: Diallo" className={inputCls} required />
                    </FormField>
                    <FormField label="Sexe" error={formErrors?.sexe} required>
                      <select value={formData.sexe} onChange={e => setField('sexe', e.target.value)} className={inputCls} required>
                        <option value="M">Masculin</option>
                        <option value="F">Féminin</option>
                      </select>
                    </FormField>
                    <FormField label="Date de naissance" error={formErrors?.date_naissance}>
                      <input type="date" value={formData.date_naissance} onChange={e => setField('date_naissance', e.target.value)} className={inputCls} />
                    </FormField>
                    <FormField label="Lieu de naissance" error={formErrors?.lieu_naissance}>
                      <input type="text" value={formData.lieu_naissance} onChange={e => setField('lieu_naissance', e.target.value)} placeholder="Ex: Dakar" className={inputCls} />
                    </FormField>
                    <FormField label="Situation matrimoniale" error={formErrors?.situation_matrimoniale}>
                      <select value={formData.situation_matrimoniale} onChange={e => setField('situation_matrimoniale', e.target.value)} className={inputCls}>
                        <option value="Célibataire">Célibataire</option>
                        <option value="Marié(e)">Marié(e)</option>
                        <option value="Divorcé(e)">Divorcé(e)</option>
                        <option value="Veuf(ve)">Veuf(ve)</option>
                      </select>
                    </FormField>
                  </div>
                </div>

                {/* Section 2: Données Professionnelles */}
                <div>
                  <SectionHeader>Données Professionnelles</SectionHeader>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <FormField label="Grade" error={formErrors?.grade}>
                      <input type="text" value={formData.grade} onChange={e => setField('grade', e.target.value)}
                        placeholder="Ex: Adjudant, Capitaine..." className={inputCls} />
                    </FormField>
                    <FormField label="Date entrée corps" error={formErrors?.date_entree_corps}>
                      <input type="date" value={formData.date_entree_corps} onChange={e => setField('date_entree_corps', e.target.value)} className={inputCls} />
                    </FormField>
                    <FormField label="Ancienneté (années)" error={formErrors?.anciennete}>
                      <input type="number" min="0" value={formData.anciennete} onChange={e => setField('anciennete', e.target.value)} placeholder="Ex: 5" className={inputCls} />
                    </FormField>
                    <FormField label="Affectation Service" error={formErrors?.service_id} required>
                      <select value={formData.service_id} onChange={e => setField('service_id', e.target.value)} className={inputCls} required>
                        <option value="">Sélectionner...</option>
                        {services.map(s => <option key={s.id} value={s.id}>{s.nom}</option>)}
                      </select>
                    </FormField>
                    <FormField label="Téléphone professionnel" error={formErrors?.telephone}>
                      <input type="text" value={formData.telephone} onChange={e => setField('telephone', e.target.value)}
                        placeholder="Ex: +221 77..." className={`${inputCls} font-mono`} />
                    </FormField>
                    <FormField label="Statut" error={formErrors?.statut} required>
                      <select value={formData.statut} onChange={e => setField('statut', e.target.value)} className={inputCls} required>
                        <option value="Actif">Actif</option>
                        <option value="Inactif">Inactif</option>
                        <option value="Mission">Mission</option>
                      </select>
                    </FormField>
                  </div>
                </div>

                {/* Section 3: Disciplinaire */}
                <div>
                  <SectionHeader>Notes disciplinaires</SectionHeader>
                  <textarea rows={3} value={formData.sanction} onChange={e => setField('sanction', e.target.value)}
                    placeholder="Aucune sanction"
                    className="w-full px-3 py-2 text-sm bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all resize-none" />
                </div>

                <div className="flex justify-end gap-2 pt-4 border-t border-[#F1F5F9] dark:border-white/5">
                  <button type="button" onClick={() => setIsFormOpen(false)} className="h-9 px-4 text-sm font-medium text-[#64748B] dark:text-white/50 bg-[#F1F5F9] dark:bg-white/5 hover:bg-[#E2E8F0] dark:hover:bg-white/5 rounded-lg transition-colors">Annuler</button>
                  <button type="submit" disabled={actionLoading} className="h-9 px-5 text-sm font-medium text-white bg-[#2563EB] hover:bg-[#1D4ED8] rounded-lg transition-colors disabled:opacity-60">
                    {actionLoading ? 'Enregistrement...' : formMode === 'create' ? 'Valider la Fiche' : 'Sauvegarder'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* MODAL DETAIL */}
      <AnimatePresence>
        {isDetailOpen && selectedAgent && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 overflow-y-auto">
            <motion.div initial={{ scale: 0.96, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.96, opacity: 0 }} transition={{ duration: 0.15 }}
              className="bg-white dark:bg-[#1E293B] rounded-xl w-full max-w-2xl flex flex-col shadow-2xl overflow-hidden border border-[#E2E8F0] dark:border-white/8 my-auto">
              <div className="px-6 py-4 border-b border-[#F1F5F9] dark:border-white/5 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-xl bg-[#DBEAFE] flex items-center justify-center shadow-sm">
                    <UsersIcon className="w-5 h-5 text-[#2563EB]" />
                  </div>
                  <div>
                    <h3 className="text-base font-semibold text-[#0F172A] dark:text-white">{selectedAgent.prenom} {selectedAgent.nom}</h3>
                    <p className="text-xs font-mono text-[#64748B] dark:text-white/50">CCAP: {selectedAgent.ccap}</p>
                  </div>
                </div>
                <button onClick={() => setIsDetailOpen(false)} className="p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/5 transition-colors"><X className="w-4 h-4" /></button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-6 max-h-[75vh] text-sm">
                {/* Info générale */}
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  {[
                    { label: 'Sexe', value: selectedAgent.sexe === 'M' ? 'Masculin' : 'Féminin' },
                    { label: 'Situation Matrimoniale', value: selectedAgent.situation_matrimoniale || 'Célibataire' },
                    { label: 'Téléphone', value: selectedAgent.telephone || 'Non renseigné', mono: true },
                  ].map(({ label, value, mono }) => (
                    <div key={label} className="p-3 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg">
                      <p className="text-[10px] text-[#94A3B8] dark:text-white/30 uppercase font-semibold mb-1">{label}</p>
                      <p className={`text-sm font-semibold text-[#0F172A] dark:text-white ${mono ? 'font-mono' : ''}`}>{value}</p>
                    </div>
                  ))}
                </div>

                {selectedAgent.date_naissance && (
                  <div className="p-3 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg">
                    <p className="text-[10px] text-[#94A3B8] dark:text-white/30 uppercase font-semibold mb-1">Date & Lieu de Naissance</p>
                    <p className="text-sm font-semibold text-[#0F172A] dark:text-white">
                      {new Date(selectedAgent.date_naissance).toLocaleDateString('fr-FR')}
                      {selectedAgent.lieu_naissance && ` à ${selectedAgent.lieu_naissance}`}
                    </p>
                  </div>
                )}

                {/* Carrière */}
                <div className="p-4 bg-[#EFF6FF] border border-[#DBEAFE] rounded-lg space-y-3">
                  <p className="text-xs font-semibold text-[#2563EB] uppercase tracking-wide flex items-center gap-1.5">
                    <Award className="w-4 h-4" /> Grade & Affectation
                  </p>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                    <div>
                      <p className="text-[10px] text-[#64748B] uppercase mb-0.5">Grade</p>
                      <p className="font-semibold text-[#0F172A]">{selectedAgent.grade || 'Agent simple'}</p>
                    </div>
                    <div>
                      <p className="text-[10px] text-[#64748B] uppercase mb-0.5">Affectation</p>
                      <p className="font-semibold text-[#0F172A] flex items-center gap-1">
                        <Landmark className="w-3.5 h-3.5 text-[#2563EB]" /> {selectedAgent.service?.nom || '-'}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-[#64748B] uppercase mb-0.5">Ancienneté</p>
                      <p className="font-semibold text-[#0F172A]">{selectedAgent.anciennete ? `${selectedAgent.anciennete} ans` : '-'}</p>
                    </div>
                  </div>
                  {selectedAgent.date_entree_corps && (
                    <div className="pt-2 border-t border-[#BFDBFE] flex items-center gap-2 text-xs text-[#64748B]">
                      <Calendar className="w-4 h-4" />
                      Entrée dans le corps : {new Date(selectedAgent.date_entree_corps).toLocaleDateString('fr-FR')}
                    </div>
                  )}
                </div>

                {/* Statut */}
                <div className="flex items-center gap-2">
                  <p className="text-xs font-medium text-[#94A3B8] dark:text-white/30 uppercase">Statut :</p>
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border ${STATUT_BADGE[selectedAgent.statut] || STATUT_BADGE.Inactif}`}>
                    {selectedAgent.statut || 'Actif'}
                  </span>
                </div>

                {/* Disciplinaire */}
                <div className="p-4 bg-[#FFF7ED] border border-[#FED7AA] rounded-lg">
                  <p className="text-xs font-semibold text-[#9A3412] uppercase tracking-wide flex items-center gap-1.5 mb-2">
                    <ShieldAlert className="w-4 h-4" /> Mesures disciplinaires
                  </p>
                  <p className="text-sm text-[#64748B] whitespace-pre-wrap">
                    {selectedAgent.sanction || 'Aucun dossier disciplinaire ou sanction active.'}
                  </p>
                </div>
              </div>

              <div className="px-6 py-3 border-t border-[#F1F5F9] dark:border-white/5 flex justify-end shrink-0">
                <button onClick={() => setIsDetailOpen(false)} className="h-9 px-4 text-sm font-medium text-[#64748B] dark:text-white/50 bg-[#F1F5F9] dark:bg-white/5 hover:bg-[#E2E8F0] dark:hover:bg-white/5 rounded-lg transition-colors">Fermer</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

