import { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Download, FileText, UploadCloud, RefreshCw, CheckCircle, AlertCircle, X, ShieldAlert, FileJson, Filter, BarChart3, TrendingUp, Users, Globe, CreditCard } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import exportService from '../services/exportService';
import syncService from '../services/syncService';
import GeoFilterComponent from '../components/GeoFilterComponent';
import api from '../api/axios';

function Toast({ toast }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <motion.div
      initial={{ opacity: 0, y: -16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -16 }}
      className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-lg shadow-lg text-sm font-medium border ${
        isError ? 'bg-[#FEF2F2] border-[#FECACA] text-[#DC2626]' : 'bg-[#F0FDF4] border-[#BBF7D0] text-[#16A34A]'
      }`}
    >
      {isError ? <AlertCircle className="w-4 h-4 shrink-0" /> : <CheckCircle className="w-4 h-4 shrink-0" />}
      {toast.message}
    </motion.div>
  );
}

const inputCls = 'w-full text-sm border border-[#E2E8F0] dark:border-white/10 rounded-lg py-2 px-3 bg-[#F8FAFC] dark:bg-white/5 text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-colors font-medium dark:placeholder-white/30';

const ANALYTICS_COLORS = ['#2563EB', '#16A34A', '#D97706', '#DC2626', '#7C3AED', '#0891B2', '#E11D48', '#C2410C'];

function AnalyticsSection() {
  const [data, setData] = useState({ infractions: [], accidents: [], personnels: [], immigrations: [], amendes: [] });
  const [analyticsLoading, setAnalyticsLoading] = useState(true);

  useEffect(() => {
    Promise.allSettled([
      api.get('/infractions', { params: { per_page: 500 } }),
      api.get('/accidents', { params: { per_page: 500 } }),
      api.get('/personnels', { params: { per_page: 500 } }),
      api.get('/immigrations-clandestines', { params: { per_page: 500 } }),
      api.get('/amendes-pieces-saisies', { params: { per_page: 500 } }),
    ]).then(results => {
      const extract = (r) => {
        if (r.status !== 'fulfilled') return [];
        const raw = r.value.data;
        return Array.isArray(raw) ? raw : (Array.isArray(raw?.data) ? raw.data : []);
      };
      setData({
        infractions: extract(results[0]),
        accidents: extract(results[1]),
        personnels: extract(results[2]),
        immigrations: extract(results[3]),
        amendes: extract(results[4]),
      });
      setAnalyticsLoading(false);
    });
  }, []);

  const infractionsParType = useMemo(() => {
    const counts = {};
    data.infractions.forEach(i => {
      const k = i.type_infraction?.nom || 'Autre';
      counts[k] = (counts[k] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value).slice(0, 8);
  }, [data.infractions]);

  const infractionsParRegion = useMemo(() => {
    const counts = {};
    data.infractions.forEach(i => {
      const k = i.commune?.departement?.region?.nom || i.region?.nom || 'Non renseigné';
      counts[k] = (counts[k] || 0) + 1;
    });
    return Object.entries(counts).map(([region, total]) => ({ region, total })).sort((a, b) => b.total - a.total).slice(0, 8);
  }, [data.infractions]);

  const accidentsParGravite = useMemo(() => {
    const counts = {};
    data.accidents.forEach(a => {
      const k = a.type || 'Non précisé';
      counts[k] = (counts[k] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [data.accidents]);

  const personnelParGrade = useMemo(() => {
    const counts = {};
    data.personnels.forEach(p => {
      const k = p.grade || 'Non précisé';
      counts[k] = (counts[k] || 0) + 1;
    });
    return Object.entries(counts).map(([grade, total]) => ({ grade, total })).sort((a, b) => b.total - a.total).slice(0, 8);
  }, [data.personnels]);

  const amendesParRegion = useMemo(() => {
    const counts = {};
    data.amendes.forEach(a => {
      const k = a.region?.nom || 'Non renseigné';
      counts[k] = (counts[k] || 0) + (Number(a.montant) || 0);
    });
    return Object.entries(counts).map(([region, montant]) => ({ region, montant })).sort((a, b) => b.montant - a.montant).slice(0, 8);
  }, [data.amendes]);

  const immigrationDemo = useMemo(() => {
    const counts = { Hommes: 0, Femmes: 0, Mineurs: 0, Sénégalais: 0, Étrangers: 0 };
    data.immigrations.forEach(i => {
      counts.Hommes += Number(i.nombre_hommes || 0);
      counts.Femmes += Number(i.nombre_femmes || 0);
      counts.Mineurs += Number(i.nombre_enfants || 0);
      counts.Sénégalais += Number(i.nombre_senegalais || 0);
      counts.Étrangers += Number(i.nombre_etrangers || 0);
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value })).filter(d => d.value > 0);
  }, [data.immigrations]);

  if (analyticsLoading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {[...Array(6)].map((_, i) => (
          <div key={i} className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 animate-pulse h-56">
            <div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-40 mb-4" />
            <div className="h-36 bg-[#F1F5F9] dark:bg-white/5 rounded" />
          </div>
        ))}
      </div>
    );
  }

  const charts = [
    {
      title: 'Infractions par type',
      icon: <BarChart3 className="w-4 h-4 text-[#D97706]" />,
      show: infractionsParType.length > 0,
      content: (
        <ResponsiveContainer width="100%" height={180}>
          <PieChart>
            <Pie data={infractionsParType} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={70}>
              {infractionsParType.map((_, idx) => <Cell key={idx} fill={ANALYTICS_COLORS[idx % ANALYTICS_COLORS.length]} />)}
            </Pie>
            <Tooltip contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0' }} />
            <Legend iconSize={8} wrapperStyle={{ fontSize: 9 }} />
          </PieChart>
        </ResponsiveContainer>
      ),
    },
    {
      title: 'Infractions par région',
      icon: <TrendingUp className="w-4 h-4 text-[#2563EB]" />,
      show: infractionsParRegion.length > 0,
      content: (
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={infractionsParRegion} layout="vertical" barSize={10} margin={{ left: 48, right: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" horizontal={false} />
            <XAxis type="number" tick={{ fontSize: 9, fill: '#94A3B8' }} axisLine={false} tickLine={false} />
            <YAxis type="category" dataKey="region" tick={{ fontSize: 9, fill: '#64748B' }} axisLine={false} tickLine={false} width={80} />
            <Tooltip contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0' }} formatter={(v) => [v, 'Infractions']} />
            <Bar dataKey="total" fill="#2563EB" radius={[0, 4, 4, 0]} />
          </BarChart>
        </ResponsiveContainer>
      ),
    },
    {
      title: 'Accidents par gravité',
      icon: <AlertCircle className="w-4 h-4 text-[#DC2626]" />,
      show: accidentsParGravite.length > 0,
      content: (
        <ResponsiveContainer width="100%" height={180}>
          <PieChart>
            <Pie data={accidentsParGravite} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={70}>
              {accidentsParGravite.map((_, idx) => <Cell key={idx} fill={ANALYTICS_COLORS[idx % ANALYTICS_COLORS.length]} />)}
            </Pie>
            <Tooltip contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0' }} />
            <Legend iconSize={8} wrapperStyle={{ fontSize: 9 }} />
          </PieChart>
        </ResponsiveContainer>
      ),
    },
    {
      title: 'Personnel par grade',
      icon: <Users className="w-4 h-4 text-[#16A34A]" />,
      show: personnelParGrade.length > 0,
      content: (
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={personnelParGrade} layout="vertical" barSize={10} margin={{ left: 48, right: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" horizontal={false} />
            <XAxis type="number" tick={{ fontSize: 9, fill: '#94A3B8' }} axisLine={false} tickLine={false} />
            <YAxis type="category" dataKey="grade" tick={{ fontSize: 9, fill: '#64748B' }} axisLine={false} tickLine={false} width={80} />
            <Tooltip contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0' }} formatter={(v) => [v, 'Agents']} />
            <Bar dataKey="total" fill="#16A34A" radius={[0, 4, 4, 0]} />
          </BarChart>
        </ResponsiveContainer>
      ),
    },
    {
      title: 'Amendes par région (FCFA)',
      icon: <CreditCard className="w-4 h-4 text-[#7C3AED]" />,
      show: amendesParRegion.length > 0,
      content: (
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={amendesParRegion} layout="vertical" barSize={10} margin={{ left: 48, right: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" horizontal={false} />
            <XAxis type="number" tick={{ fontSize: 9, fill: '#94A3B8' }} axisLine={false} tickLine={false} tickFormatter={v => `${(v/1000).toFixed(0)}k`} />
            <YAxis type="category" dataKey="region" tick={{ fontSize: 9, fill: '#64748B' }} axisLine={false} tickLine={false} width={80} />
            <Tooltip contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0' }} formatter={(v) => [`${Number(v).toLocaleString('fr-FR')} FCFA`, 'Montant']} />
            <Bar dataKey="montant" fill="#7C3AED" radius={[0, 4, 4, 0]} />
          </BarChart>
        </ResponsiveContainer>
      ),
    },
    {
      title: 'Immigration — répartition démographique',
      icon: <Globe className="w-4 h-4 text-[#0891B2]" />,
      show: immigrationDemo.length > 0,
      content: (
        <ResponsiveContainer width="100%" height={180}>
          <PieChart>
            <Pie data={immigrationDemo} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={70}>
              {immigrationDemo.map((_, idx) => <Cell key={idx} fill={ANALYTICS_COLORS[idx % ANALYTICS_COLORS.length]} />)}
            </Pie>
            <Tooltip contentStyle={{ fontSize: 11, borderRadius: 8, border: '1px solid #E2E8F0' }} />
            <Legend iconSize={8} wrapperStyle={{ fontSize: 9 }} />
          </PieChart>
        </ResponsiveContainer>
      ),
    },
  ].filter(c => c.show);

  if (charts.length === 0) return null;

  return (
    <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 space-y-4">
      <div className="flex items-center gap-2 pb-3 border-b border-[#E2E8F0] dark:border-white/8">
        <div className="w-8 h-8 bg-[#DBEAFE] rounded-xl flex items-center justify-center">
          <BarChart3 className="w-4 h-4 text-[#2563EB]" />
        </div>
        <div>
          <p className="text-sm font-semibold text-[#0F172A] dark:text-white">Analyses statistiques</p>
          <p className="text-xs text-[#64748B] dark:text-white/50">Visualisation analytique des données disponibles</p>
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {charts.map(chart => (
          <div key={chart.title} className="border border-[#E2E8F0] dark:border-white/8 rounded-xl p-4">
            <h4 className="text-xs font-semibold text-[#0F172A] dark:text-white mb-3 flex items-center gap-1.5">
              {chart.icon}
              {chart.title}
            </h4>
            {chart.content}
          </div>
        ))}
      </div>
    </div>
  );
}

export default function Rapports() {
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({});
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const [tempFilterType, setTempFilterType] = useState('all');
  const [selectedDay, setSelectedDay] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedHour, setSelectedHour] = useState('');

  const [dragActive, setDragActive] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [uploadSuccess, setUploadSuccess] = useState(null);
  const [uploadError, setUploadError] = useState(null);

  const getCombinedParams = () => {
    const params = { ...filters };
    if (tempFilterType === 'day' && selectedDay) {
      params.date_from = selectedDay; params.date_to = selectedDay;
    } else if (tempFilterType === 'period') {
      if (startDate) params.date_from = startDate;
      if (endDate) params.date_to = endDate;
    }
    if (selectedHour) params.hour = selectedHour;
    return params;
  };

  const handleExport = async (type, format) => {
    setLoading(true);
    try {
      const p = getCombinedParams();
      let response;
      if (type === 'infractions' && format === 'pdf') response = await exportService.infractionsPdf(p);
      if (type === 'infractions' && format === 'csv') response = await exportService.infractionsCsv(p);
      if (type === 'accidents' && format === 'pdf') response = await exportService.accidentsPdf(p);
      if (type === 'accidents' && format === 'csv') response = await exportService.accidentsCsv(p);
      if (response?.data) {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `export_${type}_${format}_${Date.now()}.${format}`);
        document.body.appendChild(link);
        link.click();
        link.parentNode.removeChild(link);
        showToast(`Export ${type} (${format.toUpperCase()}) téléchargé avec succès.`);
      }
    } catch (e) {
      console.error(e);
      showToast("Erreur lors de l'exportation des données.", 'error');
    } finally {
      setLoading(false);
    }
  };

  const [syncStatus, setSyncStatus] = useState(null);
  const [syncCheckedAt, setSyncCheckedAt] = useState(null);
  const [syncHistory, setSyncHistory] = useState([]);

  const checkSyncStatus = async () => {
    try {
      const r = await syncService.status();
      const data = r.data?.data || r.data || {};
      setSyncStatus(data);
      const now = new Date();
      setSyncCheckedAt(now);
      setSyncHistory(prev => [
        {
          date: now.toISOString(),
          infractions_synced: data.synced_infractions || 0,
          accidents_synced: data.synced_accidents || 0,
          pending: (data.pending_infractions || 0) + (data.pending_accidents || 0),
          status: 'success',
        },
        ...prev.slice(0, 9),
      ]);
      showToast('Statut de synchronisation récupéré avec succès.');
    } catch {
      const now = new Date();
      setSyncHistory(prev => [
        { date: now.toISOString(), infractions_synced: 0, accidents_synced: 0, pending: 0, status: 'error' },
        ...prev.slice(0, 9),
      ]);
      showToast('Erreur lors de la récupération du statut de synchronisation.', 'error');
    }
  };

  const handleDrag = (e) => {
    e.preventDefault(); e.stopPropagation();
    setDragActive(e.type === 'dragenter' || e.type === 'dragover');
  };

  const handleDrop = (e) => {
    e.preventDefault(); e.stopPropagation(); setDragActive(false);
    const file = e.dataTransfer.files?.[0];
    if (file && (file.name.endsWith('.json') || file.type === 'application/json')) {
      setSelectedFile(file); setUploadError(null); setUploadSuccess(null);
    } else if (file) {
      setUploadError('Type de fichier invalide. Veuillez déposer uniquement des fichiers JSON.');
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (file && (file.name.endsWith('.json') || file.type === 'application/json')) {
      setSelectedFile(file); setUploadError(null); setUploadSuccess(null);
    } else if (file) {
      setUploadError('Type de fichier invalide. Veuillez sélectionner uniquement des fichiers JSON.');
    }
  };

  const handleUpload = async () => {
    if (!selectedFile) return;
    setUploading(true); setUploadError(null); setUploadSuccess(null);
    try {
      const res = await exportService.importJson(selectedFile);
      setUploadSuccess(res.data?.message || 'Données importées et consolidées avec succès !');
      setSelectedFile(null);
    } catch (err) {
      setUploadError(err.response?.data?.error || err.response?.data?.message || 'Erreur lors de la lecture du fichier JSON.');
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="space-y-6 max-w-[1400px]">
      <AnimatePresence>{toast && <Toast toast={toast} />}</AnimatePresence>
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white">Rapports & Exports</h1>
        <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">Générer des documents PDF/CSV ciblés ou synchroniser les terminaux mobiles</p>
      </div>

      {/* Analytics */}
      <AnalyticsSection />

      {/* Filter panel */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 space-y-4 shadow-[0_2px_6px_rgba(15,23,42,0.04)]">
        <div className="flex items-center gap-2 pb-3 border-b border-[#E2E8F0] dark:border-white/8">
          <div className="w-8 h-8 bg-[#2563EB] rounded-xl flex items-center justify-center shadow-sm">
            <Filter className="w-4 h-4 text-white" />
          </div>
          <div>
            <p className="text-sm font-semibold text-[#0F172A] dark:text-white">Filtrage des exports</p>
            <p className="text-xs text-[#64748B] dark:text-white/50">Affinez par territoire, période et horaire avant téléchargement</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
          <div className="md:col-span-3 flex flex-col gap-1.5">
            <span className="text-xs font-semibold text-[#64748B] dark:text-white/50">1. Territoire</span>
            <GeoFilterComponent onChange={(f) => setFilters(f)} />
          </div>

          <div className="md:col-span-3 flex flex-col gap-1.5">
            <label className="text-xs font-semibold text-[#64748B] dark:text-white/50">2. Filtrage temporel</label>
            <select
              value={tempFilterType}
              onChange={(e) => {
                setTempFilterType(e.target.value);
                if (e.target.value === 'all') { setSelectedDay(''); setStartDate(''); setEndDate(''); }
              }}
              className={inputCls}
            >
              <option value="all">Tous les enregistrements</option>
              <option value="day">Par jour spécifique</option>
              <option value="period">Par période (plage de dates)</option>
            </select>
          </div>

          <div className="md:col-span-4 flex flex-col gap-1.5">
            {tempFilterType === 'day' && (
              <>
                <label className="text-xs font-semibold text-[#64748B] dark:text-white/50">Sélectionner le jour *</label>
                <input type="date" value={selectedDay} onChange={e => setSelectedDay(e.target.value)} className={inputCls} />
              </>
            )}
            {tempFilterType === 'period' && (
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="text-xs font-semibold text-[#64748B] dark:text-white/50 block mb-1.5">Date de début</label>
                  <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className={inputCls} />
                </div>
                <div>
                  <label className="text-xs font-semibold text-[#64748B] dark:text-white/50 block mb-1.5">Date de fin</label>
                  <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className={inputCls} />
                </div>
              </div>
            )}
            {tempFilterType === 'all' && (
              <p className="text-xs text-[#94A3B8] dark:text-white/30 italic pt-6">Pas de restriction de date appliquée.</p>
            )}
          </div>

          <div className="md:col-span-2 flex flex-col gap-1.5">
            <label className="text-xs font-semibold text-[#64748B] dark:text-white/50">3. Heure (optionnel)</label>
            <select value={selectedHour} onChange={e => setSelectedHour(e.target.value)} className={inputCls}>
              <option value="">Toutes les heures</option>
              {Array.from({ length: 24 }).map((_, i) => {
                const h = i.toString().padStart(2, '0');
                return <option key={i} value={h}>{h}h</option>;
              })}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* PDF exports */}
        <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 shadow-[0_2px_6px_rgba(15,23,42,0.04)]">
          <div className="flex items-center gap-3 mb-5">
            <div className="w-10 h-10 bg-[#DC2626] rounded-xl flex items-center justify-center shadow-sm">
              <FileText className="w-5 h-5 text-white" />
            </div>
            <div>
              <p className="font-semibold text-[#0F172A] dark:text-white text-sm">Rapports PDF Officiels</p>
              <p className="text-xs text-[#64748B] dark:text-white/50">Mise en page réglementaire avec en-tête étatique</p>
            </div>
          </div>
          <div className="space-y-2.5">
            {[
              { type: 'infractions', label: 'Registre des Infractions', sub: 'Format PDF • Fiche d\'infraction complète' },
              { type: 'accidents', label: 'Rapport Statistique des Accidents', sub: 'Format PDF • Données et causes présumées' },
            ].map(({ type, label, sub }) => (
              <button
                key={type}
                onClick={() => handleExport(type, 'pdf')}
                disabled={loading}
                className="w-full flex items-center justify-between p-4 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg hover:border-[#FECACA] hover:bg-[#FEF2F2]/30 dark:hover:bg-white/10 transition-all group disabled:opacity-50"
              >
                <div className="text-left">
                  <p className="font-semibold text-[#0F172A] dark:text-white text-sm">{label}</p>
                  <p className="text-xs text-[#94A3B8] dark:text-white/30 mt-0.5">{sub}</p>
                </div>
                <Download className="w-4 h-4 text-[#94A3B8] group-hover:text-[#DC2626] transition-colors shrink-0" />
              </button>
            ))}
          </div>
        </div>

        {/* CSV exports */}
        <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 shadow-[0_2px_6px_rgba(15,23,42,0.04)]">
          <div className="flex items-center gap-3 mb-5">
            <div className="w-10 h-10 bg-[#16A34A] rounded-xl flex items-center justify-center shadow-sm">
              <FileText className="w-5 h-5 text-white" />
            </div>
            <div>
              <p className="font-semibold text-[#0F172A] dark:text-white text-sm">Exports Données CSV</p>
              <p className="text-xs text-[#64748B] dark:text-white/50">Pour intégration dans Excel ou outils d'analyse BI</p>
            </div>
          </div>
          <div className="space-y-2.5">
            {[
              { type: 'infractions', label: 'Données Brutes Infractions', sub: 'Format CSV (UTF-8) • Délimiteur point-virgule' },
              { type: 'accidents', label: 'Données Brutes Accidents', sub: 'Format CSV (UTF-8) • Coordonnées GPS incluses' },
            ].map(({ type, label, sub }) => (
              <button
                key={type}
                onClick={() => handleExport(type, 'csv')}
                disabled={loading}
                className="w-full flex items-center justify-between p-4 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg hover:border-[#BBF7D0] hover:bg-[#F0FDF4]/30 dark:hover:bg-white/10 transition-all group disabled:opacity-50"
              >
                <div className="text-left">
                  <p className="font-semibold text-[#0F172A] dark:text-white text-sm">{label}</p>
                  <p className="text-xs text-[#94A3B8] dark:text-white/30 mt-0.5">{sub}</p>
                </div>
                <Download className="w-4 h-4 text-[#94A3B8] group-hover:text-[#16A34A] transition-colors shrink-0" />
              </button>
            ))}
          </div>
        </div>

        {/* JSON import */}
        <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 md:col-span-2">
          <div className="flex items-center gap-3 mb-5">
            <div className="w-10 h-10 bg-[#2563EB] rounded-xl flex items-center justify-center shadow-sm">
              <UploadCloud className="w-5 h-5 text-white" />
            </div>
            <div>
              <p className="font-semibold text-[#0F172A] dark:text-white text-sm">Restauration & Importation JSON</p>
              <p className="text-xs text-[#64748B] dark:text-white/50">Intégrer des fichiers d'infractions/accidents au format standard GESCRIM</p>
            </div>
          </div>

          <form
            onDragEnter={handleDrag}
            onDragOver={handleDrag}
            onDragLeave={handleDrag}
            onDrop={handleDrop}
            className={`relative border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all ${
              dragActive ? 'border-[#2563EB] bg-[#EFF6FF]/40' : 'border-[#E2E8F0] dark:border-white/10 bg-[#F8FAFC] dark:bg-white/5 hover:bg-[#F1F5F9] dark:hover:bg-white/8'
            }`}
          >
            <input type="file" id="file-json-upload" accept=".json" onChange={handleFileChange} className="hidden" />

            <div className="w-12 h-12 bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-xl flex items-center justify-center text-[#2563EB] mb-3 shadow-sm">
              <FileJson className="w-6 h-6" />
            </div>

            <p className="text-sm font-medium text-[#475569] dark:text-white/60 text-center">
              Faites glisser votre fichier JSON ici, ou{' '}
              <label htmlFor="file-json-upload" className="text-[#2563EB] hover:underline cursor-pointer font-semibold">
                parcourez vos fichiers
              </label>
            </p>
            <p className="text-xs text-[#94A3B8] dark:text-white/30 mt-1">Seuls les fichiers .json structurés sont acceptés</p>

            {selectedFile && (
              <div className="mt-4 p-3 bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg flex items-center justify-between w-full max-w-md shadow-sm">
                <div className="flex items-center gap-2 min-w-0">
                  <FileJson className="w-4 h-4 text-[#2563EB] shrink-0" />
                  <span className="text-xs font-semibold text-[#0F172A] dark:text-white truncate">{selectedFile.name}</span>
                  <span className="text-[10px] text-[#94A3B8] dark:text-white/30 shrink-0">({(selectedFile.size / 1024).toFixed(1)} KB)</span>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    type="button"
                    onClick={handleUpload}
                    disabled={uploading}
                    className="px-3 py-1.5 bg-[#2563EB] hover:bg-[#1D4ED8] text-white rounded-lg text-xs font-semibold disabled:opacity-50 transition-colors"
                  >
                    {uploading ? 'Importation…' : "Confirmer l'import"}
                  </button>
                  <button type="button" onClick={() => setSelectedFile(null)} className="p-1 hover:bg-[#F1F5F9] dark:hover:bg-white/5 rounded-lg text-[#94A3B8] dark:text-white/30 hover:text-[#475569] dark:hover:text-white/60">
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            )}
          </form>

          <AnimatePresence>
            {uploadSuccess && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="mt-3 p-3.5 bg-[#F0FDF4] border border-[#BBF7D0] text-[#16A34A] rounded-lg flex items-start gap-2 text-xs"
              >
                <CheckCircle className="w-4 h-4 shrink-0 mt-0.5" />
                <div><span className="font-bold">Succès :</span> {uploadSuccess}</div>
              </motion.div>
            )}
            {uploadError && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="mt-3 p-3.5 bg-[#FEF2F2] border border-[#FECACA] text-[#DC2626] rounded-lg flex items-start gap-2 text-xs"
              >
                <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                <div><span className="font-bold">Erreur :</span> {uploadError}</div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Sync status + history */}
        <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 md:col-span-2 space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-[#DBEAFE] rounded-xl flex items-center justify-center">
                <RefreshCw className="w-5 h-5 text-[#2563EB]" />
              </div>
              <div>
                <p className="font-semibold text-[#0F172A] dark:text-white text-sm">Synchronisation Flotte Mobile (Flutter)</p>
                <p className="text-xs text-[#64748B] dark:text-white/50">
                  {syncCheckedAt ? `Dernière vérification : ${syncCheckedAt.toLocaleString('fr-FR')}` : 'Statut des bases de données locales embarquées'}
                </p>
              </div>
            </div>
            <button
              onClick={checkSyncStatus}
              className="inline-flex items-center gap-2 px-4 py-2 bg-[#F8FAFC] dark:bg-white/5 hover:bg-[#F1F5F9] dark:hover:bg-white/10 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-xs font-semibold text-[#475569] dark:text-white/60 transition-colors"
            >
              <RefreshCw className="w-3.5 h-3.5" />
              Vérifier
            </button>
          </div>

          {syncStatus ? (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {[
                { label: 'Infractions synchronisées', value: syncStatus.synced_infractions ?? 0, color: 'text-[#16A34A]', bg: 'bg-[#F0FDF4] dark:bg-[#16A34A]/10' },
                { label: 'Accidents synchronisés', value: syncStatus.synced_accidents ?? 0, color: 'text-[#2563EB]', bg: 'bg-[#EFF6FF] dark:bg-[#2563EB]/10' },
                { label: 'Infractions en attente', value: syncStatus.pending_infractions ?? 0, color: 'text-[#D97706]', bg: 'bg-[#FFFBEB] dark:bg-[#D97706]/10' },
                { label: 'Accidents en attente', value: syncStatus.pending_accidents ?? 0, color: 'text-[#DC2626]', bg: 'bg-[#FEF2F2] dark:bg-[#DC2626]/10' },
              ].map(({ label, value, color, bg }) => (
                <div key={label} className={`${bg} rounded-lg p-3`}>
                  <p className="text-[10px] text-[#64748B] dark:text-white/40 mb-1">{label}</p>
                  <p className={`text-xl font-bold ${color}`}>{value}</p>
                </div>
              ))}
            </div>
          ) : (
            <div className="p-4 bg-[#FFFBEB] border border-[#FDE68A] rounded-lg flex items-center gap-2.5 text-xs text-[#92400E] font-medium">
              <ShieldAlert className="w-4 h-4 text-[#D97706] shrink-0" />
              Canal de synchronisation actif. Cliquez sur « Vérifier » pour obtenir le statut des terminaux mobiles.
            </div>
          )}

          {syncHistory.length > 0 && (
            <div>
              <p className="text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wider mb-2">Journal de synchronisation</p>
              <div className="border border-[#E2E8F0] dark:border-white/8 rounded-xl overflow-hidden">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="bg-[#F8FAFC] dark:bg-white/3 border-b border-[#E2E8F0] dark:border-white/8">
                      <th className="px-4 py-2.5 text-left text-[10px] font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Date & Heure</th>
                      <th className="px-4 py-2.5 text-left text-[10px] font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Infractions sync.</th>
                      <th className="px-4 py-2.5 text-left text-[10px] font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Accidents sync.</th>
                      <th className="px-4 py-2.5 text-left text-[10px] font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">En attente</th>
                      <th className="px-4 py-2.5 text-left text-[10px] font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wide">Statut</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#F1F5F9] dark:divide-white/5">
                    {syncHistory.map((entry, idx) => (
                      <tr key={idx} className="hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                        <td className="px-4 py-3 font-mono text-[#475569] dark:text-white/60">
                          {new Date(entry.date).toLocaleString('fr-FR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                        </td>
                        <td className="px-4 py-3 font-semibold text-[#16A34A]">{entry.infractions_synced}</td>
                        <td className="px-4 py-3 font-semibold text-[#2563EB]">{entry.accidents_synced}</td>
                        <td className="px-4 py-3 font-semibold text-[#D97706]">{entry.pending}</td>
                        <td className="px-4 py-3">
                          {entry.status === 'success' ? (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-[#F0FDF4] text-[#16A34A] border border-[#BBF7D0]">
                              <CheckCircle className="w-3 h-3" /> Succès
                            </span>
                          ) : (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-[#FEF2F2] text-[#DC2626] border border-[#FECACA]">
                              <AlertCircle className="w-3 h-3" /> Erreur
                            </span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

