source:
import { useState, useEffect, useCallback } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Search, Plus, Trash2, Edit, Eye, X, AlertCircle, CheckCircle2,
  Shield, MapPin, Phone, Mail, Users, FileText, Activity, ChevronLeft, ChevronRight, Landmark
} from 'lucide-react';
import geoService from '../services/geoService';

const inputCls = "w-full h-9 px-3 text-sm bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all";

const TYPE_BADGE = {
  CC: 'bg-[#EFF6FF] text-[#2563EB] border-[#BFDBFE]',
  CA: 'bg-[#EDE9FE] text-[#7C3AED] border-[#DDD6FE]',
  PP: 'bg-[#F0FDF4] text-[#16A34A] border-[#BBF7D0]',
  CU: 'bg-[#FFF7ED] text-[#C2410C] border-[#FED7AA]',
  CS: 'bg-[#FDF4FF] text-[#9333EA] border-[#F5D0FE]',
};

const typeLabel = (t) => ({
  CC: 'Commissariat Central',
  CA: "Commissariat d'Arrondissement",
  PP: 'Poste de Police',
  CU: 'Commissariat Urbain',
  CS: 'Commissariat Spécial',
}[t] || t);

function Toast({ toast }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <motion.div initial={{ opacity: 0, y: -16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -16 }}
      className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-lg shadow-lg text-sm font-medium border ${
        isError ? 'bg-[#FEF2F2] border-[#FECACA] text-[#DC2626]' : 'bg-[#F0FDF4] border-[#BBF7D0] text-[#16A34A]'
      }`}
    >
      {isError ? <AlertCircle className="w-4 h-4 shrink-0" /> : <CheckCircle2 className="w-4 h-4 shrink-0" />}
      {toast.message}
    </motion.div>
  );
}

export default function Services() {
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({ page: 1, per_page: 9, type: '', commune_id: '' });
  const [meta, setMeta] = useState(null);
  const [selectedService, setSelectedService] = useState(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [formMode, setFormMode] = useState('create');
  const [communes, setCommunes] = useState([]);
  const [formData, setFormData] = useState({ nom: '', type: 'CC', commune_id: '', adresse: '', telephone: '', email: '' });
  const [formErrors, setFormErrors] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const fetchServices = useCallback(async () => {
    setLoading(true);
    try {
      const res = await geoService.getServices({ ...filters, search: search || undefined, type: filters.type || undefined, commune_id: filters.commune_id || undefined });
      setServices(res.data.data || []);
      setMeta(res.data.meta || null);
    } catch { showToast('Erreur lors du chargement des services', 'error'); }
    finally { setLoading(false); }
  }, [filters, search]);

  useEffect(() => { fetchServices(); }, [fetchServices]);
  useEffect(() => {
    geoService.getAllCommunes().then(r => setCommunes(r.data.data || r.data || [])).catch(console.error);
  }, []);

  const handlePageChange = (p) => {
    if (p >= 1 && p <= (meta?.last_page || 1)) setFilters(prev => ({ ...prev, page: p }));
  };

  const handleOpenCreate = () => {
    setFormMode('create');
    setFormData({ nom: '', type: 'CC', commune_id: '', adresse: '', telephone: '', email: '' });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenEdit = (service) => {
    setFormMode('edit');
    setSelectedService(service);
    setFormData({ nom: service.nom || '', type: service.type || 'CC', commune_id: service.commune_id || '', adresse: service.adresse || '', telephone: service.telephone || '', email: service.email || '' });
    setFormErrors(null);
    setIsFormOpen(true);
  };

  const handleOpenDetail = async (service) => {
    try {
      const res = await geoService.getService(service.id);
      setSelectedService(res.data.data || res.data || service);
    } catch { setSelectedService(service); }
    setIsDetailOpen(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setActionLoading(true);
    setFormErrors(null);
    try {
      if (formMode === 'create') { await geoService.createService(formData); showToast('Service créé avec succès !'); }
      else { await geoService.updateService(selectedService.id, formData); showToast('Service mis à jour !'); }
      setIsFormOpen(false);
      fetchServices();
    } catch (err) {
      if (err.response?.status === 422) { setFormErrors(err.response.data.errors || {}); showToast('Veuillez corriger les erreurs', 'error'); }
      else showToast(err.response?.data?.message || 'Une erreur est survenue', 'error');
    } finally { setActionLoading(false); }
  };

  const handleDelete = async (id) => {
    if (!confirm('Êtes-vous sûr de vouloir supprimer ce service ? Cette action supprimera également les liaisons de personnel.')) return;
    try {
      await geoService.deleteService(id);
      showToast('Service supprimé avec succès !');
      fetchServices();
    } catch (err) { showToast(err.response?.data?.message || 'Erreur lors de la suppression', 'error'); }
  };

  const setField = (k, v) => setFormData(p => ({ ...p, [k]: v }));

  return (
    <div className="space-y-6 max-w-[1400px]">
      <AnimatePresence>{toast && <Toast toast={toast} />}</AnimatePresence>

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white">Services & Commissariats</h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">Gestion administrative des unités de police de la Sécurité Publique</p>
        </div>
        <button onClick={handleOpenCreate} className="flex items-center gap-1.5 h-9 px-4 text-sm font-medium text-white bg-[#2563EB] rounded-lg hover:bg-[#1D4ED8] transition-colors">
          <Plus className="w-4 h-4" /> Nouveau Service
        </button>
      </div>

      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-3 flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] dark:text-white/30" />
          <input type="text" value={search} onChange={(e) => { setSearch(e.target.value); setFilters(p => ({ ...p, page: 1 })); }}
            placeholder="Rechercher par nom..."
            className="w-full h-9 pl-9 pr-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all" />
        </div>
        <select value={filters.type} onChange={(e) => setFilters(p => ({ ...p, page: 1, type: e.target.value }))}
          className="h-9 px-3 text-sm bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20">
          <option value="">Tous les types</option>
          <option value="CC">Commissariat Central (CC)</option>
          <option value="CA">Commissariat d'Arrondissement (CA)</option>
          <option value="PP">Poste de Police (PP)</option>
          <option value="CU">Commissariat Urbain (CU)</option>
          <option value="CS">Commissariat Spécial (CS)</option>
        </select>
      </div>

      {/* Grid view */}
      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 animate-pulse space-y-3 h-44">
              <div className="flex justify-between">
                <div className="w-10 h-10 bg-[#F1F5F9] dark:bg-white/5 rounded-lg" />
                <div className="w-12 h-5 bg-[#F1F5F9] dark:bg-white/5 rounded-full" />
              </div>
              <div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-3/4" />
              <div className="h-3 bg-[#F1F5F9] dark:bg-white/5 rounded w-1/2" />
            </div>
          ))}
        </div>
      ) : services.length === 0 ? (
        <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-16 text-center text-[#94A3B8] dark:text-white/30">
          Aucun service ou commissariat répertorié.
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {services.map(s => {
            const badgeCls = TYPE_BADGE[s.type] || 'bg-[#F1F5F9] text-[#64748B] border-[#E2E8F0]';
            return (
              <div key={s.id} className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-5 shadow-[0_2px_6px_rgba(15,23,42,0.04)] hover:shadow-[0_8px_20px_rgba(15,23,42,0.08)] hover:-translate-y-0.5 transition-all duration-200 group">
                <div className="flex items-start justify-between mb-3">
                  <div className="w-9 h-9 rounded-xl bg-[#2563EB] flex items-center justify-center shrink-0 shadow-sm">
                    <Shield className="w-4 h-4 text-white" />
                  </div>
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border ${badgeCls}`}>{s.type}</span>
                </div>
                <h3 className="font-semibold text-[#0F172A] dark:text-white text-sm mb-0.5 leading-snug">{s.nom}</h3>
                <p className="text-xs text-[#64748B] dark:text-white/50 mb-3">{typeLabel(s.type)}</p>
                <div className="space-y-1.5 text-xs text-[#64748B] dark:text-white/50 border-t border-[#F1F5F9] dark:border-white/5 pt-3">
                  <div className="flex items-center gap-1.5">
                    <MapPin className="w-3.5 h-3.5 text-[#94A3B8] dark:text-white/30 shrink-0" />
                    <span>{s.commune?.nom || 'Commune non renseignée'}</span>
                  </div>
                  {s.telephone && (
                    <div className="flex items-center gap-1.5 font-mono">
                      <Phone className="w-3.5 h-3.5 text-[#94A3B8] dark:text-white/30 shrink-0" />
                      <span>{s.telephone}</span>
                    </div>
                  )}
                </div>
                <div className="mt-4 pt-3 border-t border-[#F1F5F9] dark:border-white/5 flex items-center justify-between">
                  <span className="text-xs text-[#64748B] dark:text-white/50 flex items-center gap-1">
                    <Users className="w-3.5 h-3.5" /> {s.personnels_count ?? 0} personnels
                  </span>
                  <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => handleOpenDetail(s)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#2563EB] hover:bg-[#EFF6FF] transition-colors"><Eye className="w-4 h-4" /></button>
                    <button onClick={() => handleOpenEdit(s)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#D97706] hover:bg-[#FFFBEB] transition-colors"><Edit className="w-4 h-4" /></button>
                    <button onClick={() => handleDelete(s.id)} className="p-1.5 rounded-md text-[#94A3B8] hover:text-[#DC2626] hover:bg-[#FEF2F2] transition-colors"><Trash2 className="w-4 h-4" /></button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {meta && meta.last_page > 1 && (
        <div className="flex justify-center items-center gap-2 text-xs">
          <button onClick={() => handlePageChange(filters.page - 1)} disabled={filters.page === 1}
            className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/8 disabled:opacity-40 hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className="px-3 py-1 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-md font-medium text-[#64748B] dark:text-white/50">
            {filters.page} / {meta.last_page}
          </span>
          <button onClick={() => handlePageChange(filters.page + 1)} disabled={filters.page === meta.last_page}
            className="p-1.5 rounded-md border border-[#E2E8F0] dark:border-white/8 disabled:opacity-40 hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* MODAL FORM */}
      <AnimatePresence>
        {isFormOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 overflow-y-auto">
            <motion.div initial={{ scale: 0.96, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.96, opacity: 0 }} transition={{ duration: 0.15 }}
              className="bg-white dark:bg-[#1E293B] rounded-xl w-full max-w-lg flex flex-col shadow-2xl overflow-hidden border border-[#E2E8F0] dark:border-white/8 my-auto">
              <div className="px-6 py-4 border-b border-[#F1F5F9] dark:border-white/5 flex items-center justify-between shrink-0">
                <h3 className="text-base font-semibold text-[#0F172A] dark:text-white">{formMode === 'create' ? 'Nouveau Service' : 'Modifier le Service'}</h3>
                <button onClick={() => setIsFormOpen(false)} className="p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/5 transition-colors"><X className="w-4 h-4" /></button>
              </div>
              <form onSubmit={handleSubmit} className="p-6 space-y-4">
                <div>
                  <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">Nom du service<span className="text-[#DC2626] ml-0.5">*</span></label>
                  <input type="text" required value={formData.nom} onChange={e => setField('nom', e.target.value)}
                    placeholder="Ex: Commissariat Central de Dakar" className={inputCls} />
                  {formErrors?.nom && <p className="text-[#DC2626] text-xs mt-1">{formErrors.nom[0]}</p>}
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">Type d'unité<span className="text-[#DC2626] ml-0.5">*</span></label>
                    <select required value={formData.type} onChange={e => setField('type', e.target.value)} className={inputCls}>
                      <option value="CC">Commissariat Central (CC)</option>
                      <option value="CA">Commissariat d'Arrondissement (CA)</option>
                      <option value="PP">Poste de Police (PP)</option>
                      <option value="CU">Commissariat Urbain (CU)</option>
                      <option value="CS">Commissariat Spécial (CS)</option>
                    </select>
                    {formErrors?.type && <p className="text-[#DC2626] text-xs mt-1">{formErrors.type[0]}</p>}
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">Commune<span className="text-[#DC2626] ml-0.5">*</span></label>
                    <select required value={formData.commune_id} onChange={e => setField('commune_id', e.target.value)} className={inputCls}>
                      <option value="">Sélectionner...</option>
                      {communes.map(c => <option key={c.id} value={c.id}>{c.nom}</option>)}
                    </select>
                    {formErrors?.commune_id && <p className="text-[#DC2626] text-xs mt-1">{formErrors.commune_id[0]}</p>}
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">Téléphone</label>
                    <input type="text" value={formData.telephone} onChange={e => setField('telephone', e.target.value)}
                      placeholder="Ex: 33 800 00 00" className={`${inputCls} font-mono`} />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">Email</label>
                    <input type="email" value={formData.email} onChange={e => setField('email', e.target.value)}
                      placeholder="Ex: central.dakar@policesn.org" className={inputCls} />
                    {formErrors?.email && <p className="text-[#DC2626] text-xs mt-1">{formErrors.email[0]}</p>}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-medium text-[#0F172A] dark:text-white mb-1.5">Adresse Physique</label>
                  <textarea rows={2} value={formData.adresse} onChange={e => setField('adresse', e.target.value)}
                    placeholder="Adresse complète..."
                    className="w-full px-3 py-2 text-sm bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-all resize-none" />
                </div>
                <div className="flex justify-end gap-2 pt-4 border-t border-[#F1F5F9] dark:border-white/5">
                  <button type="button" onClick={() => setIsFormOpen(false)} className="h-9 px-4 text-sm font-medium text-[#64748B] dark:text-white/60 bg-[#F1F5F9] dark:bg-white/5 hover:bg-[#E2E8F0] dark:hover:bg-white/10 rounded-lg transition-colors">Annuler</button>
                  <button type="submit" disabled={actionLoading} className="h-9 px-5 text-sm font-medium text-white bg-[#2563EB] hover:bg-[#1D4ED8] rounded-lg transition-colors disabled:opacity-60">
                    {actionLoading ? 'Enregistrement...' : formMode === 'create' ? 'Créer le Service' : 'Sauvegarder'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* MODAL DETAIL */}
      <AnimatePresence>
        {isDetailOpen && selectedService && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40">
            <motion.div initial={{ scale: 0.96, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.96, opacity: 0 }} transition={{ duration: 0.15 }}
              className="bg-white dark:bg-[#1E293B] rounded-xl w-full max-w-lg flex flex-col shadow-2xl overflow-hidden border border-[#E2E8F0] dark:border-white/8">
              <div className="px-6 py-4 border-b border-[#F1F5F9] dark:border-white/5 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl bg-[#2563EB] flex items-center justify-center shrink-0 shadow-sm">
                    <Shield className="w-4 h-4 text-white" />
                  </div>
                  <div>
                    <h3 className="text-sm font-semibold text-[#0F172A] dark:text-white">{selectedService.nom}</h3>
                    <p className="text-xs text-[#64748B] dark:text-white/50">{typeLabel(selectedService.type)}</p>
                  </div>
                </div>
                <button onClick={() => setIsDetailOpen(false)} className="p-1.5 rounded-md text-[#64748B] dark:text-white/50 hover:text-[#0F172A] dark:hover:text-white hover:bg-[#F1F5F9] dark:hover:bg-white/5 transition-colors"><X className="w-4 h-4" /></button>
              </div>
              <div className="p-6 space-y-5">
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { icon: Users,    value: selectedService.personnels_count ?? 0, label: 'Effectif',   iconBg: 'bg-[#DBEAFE]', iconColor: 'text-[#2563EB]', color: 'text-[#2563EB]' },
                    { icon: FileText, value: selectedService.infractions_count ?? 0, label: 'Infractions', iconBg: 'bg-[#FEF3C7]', iconColor: 'text-[#D97706]', color: 'text-[#D97706]' },
                    { icon: Activity, value: selectedService.accidents_count ?? 0, label: 'Accidents',   iconBg: 'bg-[#FEE2E2]', iconColor: 'text-[#DC2626]', color: 'text-[#DC2626]' },
                  ].map(({ icon: Icon, value, label, iconBg, iconColor, color }) => (
                    <div key={label} className="p-3 bg-white dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-xl text-center shadow-[0_1px_3px_rgba(15,23,42,0.04)]">
                      <div className={`w-8 h-8 ${iconBg} rounded-lg flex items-center justify-center mx-auto mb-1.5`}>
                        <Icon className={`w-4 h-4 ${iconColor}`} />
                      </div>
                      <p className="text-[10px] text-[#94A3B8] uppercase font-semibold mb-0.5">{label}</p>
                      <p className={`text-lg font-bold ${color}`}>{value}</p>
                    </div>
                  ))}
                </div>
                <div className="p-4 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg space-y-3 text-sm">
                  <div className="flex items-start gap-2.5">
                    <MapPin className="w-4 h-4 text-[#94A3B8] dark:text-white/30 shrink-0 mt-0.5" />
                    <div>
                      <p className="text-[10px] text-[#94A3B8] dark:text-white/30 uppercase font-semibold mb-0.5">Périmètre Communal</p>
                      <p className="font-medium text-[#0F172A] dark:text-white">
                        {selectedService.commune?.nom}
                        {selectedService.commune?.departement?.nom && ` — Dept. ${selectedService.commune.departement.nom}`}
                        {selectedService.commune?.departement?.region?.nom && `, Région ${selectedService.commune.departement.region.nom}`}
                      </p>
                    </div>
                  </div>
                  {selectedService.adresse && (
                    <div className="flex items-start gap-2.5 pt-3 border-t border-[#E2E8F0] dark:border-white/8">
                      <Landmark className="w-4 h-4 text-[#94A3B8] dark:text-white/30 shrink-0 mt-0.5" />
                      <div>
                        <p className="text-[10px] text-[#94A3B8] dark:text-white/30 uppercase font-semibold mb-0.5">Adresse Physique</p>
                        <p className="text-[#64748B] dark:text-white/50">{selectedService.adresse}</p>
                      </div>
                    </div>
                  )}
                </div>
                {(selectedService.telephone || selectedService.email) && (
                  <div className="p-4 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg space-y-2 text-xs">
                    <p className="text-[10px] text-[#94A3B8] dark:text-white/30 uppercase font-semibold">Contacts</p>
                    {selectedService.telephone && (
                      <div className="flex items-center gap-2 font-mono text-[#0F172A] dark:text-white">
                        <Phone className="w-4 h-4 text-[#94A3B8] dark:text-white/30" /> {selectedService.telephone}
                      </div>
                    )}
                    {selectedService.email && (
                      <div className="flex items-center gap-2 text-[#0F172A] dark:text-white">
                        <Mail className="w-4 h-4 text-[#94A3B8] dark:text-white/30" /> {selectedService.email}
                      </div>
                    )}
                  </div>
                )}
              </div>
              <div className="px-6 py-3 border-t border-[#F1F5F9] dark:border-white/5 flex justify-end">
                <button onClick={() => setIsDetailOpen(false)} className="h-9 px-4 text-sm font-medium text-[#64748B] dark:text-white/60 bg-[#F1F5F9] dark:bg-white/5 hover:bg-[#E2E8F0] dark:hover:bg-white/10 rounded-lg transition-colors">Fermer</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search, Plus, Trash2, Edit, Eye, X, AlertCircle,
  DollarSign, Calendar, Building2, ChevronLeft, ChevronRight, Briefcase
} from 'lucide-react';
import { serviceRemunereService } from '../services/otherService';
import geoService from '../services/geoService';
import { useAuth } from '../contexts/AuthContext';

const EMPTY_FORM = {
  libelle: '',
  service_id: '',
  date: new Date().toISOString().split('T')[0],
  montant: '',
  description: '',
};

function StatCard({ icon: Icon, label, value, iconBg, iconColor }) {
  return (
    <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-4 flex items-center gap-3 shadow-[0_2px_6px_rgba(15,23,42,0.04)] hover:shadow-[0_8px_20px_rgba(15,23,42,0.08)] hover:-translate-y-0.5 transition-all duration-200">
      <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${iconBg}`}>
        <Icon className={`w-5 h-5 ${iconColor}`} />
      </div>
      <div>
        <p className="text-xs text-[#64748B] dark:text-white/50">{label}</p>
        <p className="text-lg font-bold text-[#0F172A] dark:text-white">{value}</p>
      </div>
    </div>
  );
}

export default function ServicesRemuneres() {
  const { user } = useAuth();
  const isAdmin = user?.roles?.some(r => ['super_admin', 'admin'].includes(r.name));

  const [search, setSearch]         = useState('');
  const [filters, setFilters]       = useState({ page: 1, per_page: 10 });
  const [records, setRecords]       = useState([]);
  const [loading, setLoading]       = useState(true);
  const [meta, setMeta]             = useState(null);
  const [services, setServices]     = useState([]);

  const [selected, setSelected]     = useState(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [formMode, setFormMode]     = useState('create');
  const [formData, setFormData]     = useState(EMPTY_FORM);
  const [formErrors, setFormErrors] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [toast, setToast]           = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const fetchRecords = useCallback(async () => {
    setLoading(true);
    try {
      const res = await serviceRemunereService.getAll({ ...filters, search: search || undefined });
      setRecords(res.data?.data || []);
      setMeta(res.data?.meta || null);
    } catch {
      showToast('Erreur lors du chargement des services rémunérés', 'error');
    } finally {
      setLoading(false);
    }
  }, [filters, search]);

  useEffect(() => { fetchRecords(); }, [fetchRecords]);

  useEffect(() => {
    geoService.getAllServices()
      .then(r => setServices(r.data?.data || r.data || []))
      .catch(() => {});
  }, []);

  const openCreate = () => {
    setFormData(EMPTY_FORM);
    setFormErrors(null);
    setFormMode('create');
    setIsFormOpen(true);
  };

  const openEdit = (rec) => {
    setFormData({
      libelle:    rec.libelle || '',
      service_id: rec.service_id || '',
      date:       rec.date?.split('T')[0] || '',
      montant:    rec.montant || '',
      description: rec.description || '',
    });
    setSelected(rec);
    setFormErrors(null);
    setFormMode('edit');
    setIsFormOpen(true);
  };

  const openDetail = async (rec) => {
    try {
      const res = await serviceRemunereService.getOne(rec.id);
      setSelected(res.data?.data || res.data);
    } catch {
      setSelected(rec);
    }
    setIsDetailOpen(true);
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Confirmer la suppression ?')) return;
    try {
      await serviceRemunereService.delete(id);
      showToast('Service rémunéré supprimé');
      fetchRecords();
    } catch {
      showToast('Erreur lors de la suppression', 'error');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setActionLoading(true);
    setFormErrors(null);
    try {
      const payload = {
        ...formData,
        montant: parseFloat(formData.montant),
        service_id: parseInt(formData.service_id),
      };
      if (formMode === 'create') {
        await serviceRemunereService.create(payload);
        showToast('Service rémunéré créé avec succès');
      } else {
        await serviceRemunereService.update(selected.id, payload);
        showToast('Service rémunéré mis à jour');
      }
      setIsFormOpen(false);
      fetchRecords();
    } catch (err) {
      if (err.response?.status === 422) {
        setFormErrors(err.response.data.errors || err.response.data.message);
      } else {
        showToast('Erreur lors de la sauvegarde', 'error');
      }
    } finally {
      setActionLoading(false);
    }
  };

  const totalMontant = records.reduce((s, r) => s + parseFloat(r.montant || 0), 0);
  const fmt = (v) => new Intl.NumberFormat('fr-SN').format(v) + ' CFA';

  return (
    <div className="space-y-6">
      {/* Toast */}
      <AnimatePresence>
        {toast && (
          <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }}
            className={`fixed top-4 right-4 z-[9999] flex items-center gap-2 px-4 py-3 rounded-xl shadow-lg text-sm font-medium text-white ${toast.type === 'error' ? 'bg-[#DC2626]' : 'bg-[#16A34A]'}`}>
            <AlertCircle className="w-4 h-4" />
            {toast.message}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white flex items-center gap-2">
            <DollarSign className="w-5 h-5 text-[#2563EB]" />
            Services Rémunérés
          </h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-0.5">Gestion des prestations rémunérées de la DSP</p>
        </div>
        {isAdmin && (
          <button onClick={openCreate}
            className="flex items-center gap-2 px-4 py-2 bg-[#2563EB] hover:bg-[#1D4ED8] text-white rounded-xl text-sm font-medium transition-colors shadow-sm">
            <Plus className="w-4 h-4" /> Nouveau service
          </button>
        )}
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard icon={Briefcase} label="Total enregistrements" value={meta?.total ?? records.length} iconBg="bg-[#DBEAFE]" iconColor="text-[#2563EB]" />
        <StatCard icon={DollarSign} label="Montant total (page)" value={fmt(totalMontant)} iconBg="bg-[#DCFCE7]" iconColor="text-[#16A34A]" />
        <StatCard icon={Building2} label="Services concernés" value={new Set(records.map(r => r.service_id)).size} iconBg="bg-[#FEF3C7]" iconColor="text-[#D97706]" />
      </div>

      {/* Recherche */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-4 flex gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
          <input type="text" value={search} onChange={e => { setSearch(e.target.value); setFilters(f => ({ ...f, page: 1 })); }}
            placeholder="Rechercher par libellé, service…"
            className="w-full pl-9 pr-4 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white placeholder-[#94A3B8] focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB]" />
        </div>
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-[#F8FAFC] dark:bg-white/3 border-b border-[#E2E8F0] dark:border-white/8">
              <tr>
                {['Libellé', 'Service', 'Date', 'Montant', 'Description', 'Actions'].map(h => (
                  <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-[#64748B] dark:text-white/40 uppercase tracking-wider">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-[#F1F5F9] dark:divide-white/5">
              {loading ? (
                [...Array(5)].map((_, i) => (
                  <tr key={i}>
                    {[...Array(6)].map((_, j) => (
                      <td key={j} className="px-4 py-3"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded animate-pulse" /></td>
                    ))}
                  </tr>
                ))
              ) : records.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center text-[#94A3B8] dark:text-white/30 text-sm">
                    Aucun service rémunéré trouvé.
                  </td>
                </tr>
              ) : records.map(rec => (
                <tr key={rec.id} className="hover:bg-[#F8FAFC] dark:hover:bg-white/2 transition-colors">
                  <td className="px-4 py-3 font-medium text-[#0F172A] dark:text-white max-w-[180px] truncate">{rec.libelle || '—'}</td>
                  <td className="px-4 py-3 text-[#475569] dark:text-white/60 max-w-[160px] truncate">{rec.service?.nom || '—'}</td>
                  <td className="px-4 py-3 text-[#475569] dark:text-white/60 whitespace-nowrap">
                    {rec.date ? new Date(rec.date).toLocaleDateString('fr-FR') : '—'}
                  </td>
                  <td className="px-4 py-3">
                    <span className="font-semibold text-[#16A34A]">{fmt(rec.montant || 0)}</span>
                  </td>
                  <td className="px-4 py-3 text-[#64748B] dark:text-white/50 max-w-[200px] truncate">{rec.description || '—'}</td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-1.5">
                      <button onClick={() => openDetail(rec)}
                        className="p-1.5 rounded-lg hover:bg-[#EFF6FF] dark:hover:bg-[#2563EB]/10 text-[#2563EB] transition-colors" title="Voir">
                        <Eye className="w-3.5 h-3.5" />
                      </button>
                      {isAdmin && (
                        <>
                          <button onClick={() => openEdit(rec)}
                            className="p-1.5 rounded-lg hover:bg-[#FFF7ED] dark:hover:bg-[#D97706]/10 text-[#D97706] transition-colors" title="Modifier">
                            <Edit className="w-3.5 h-3.5" />
                          </button>
                          <button onClick={() => handleDelete(rec.id)}
                            className="p-1.5 rounded-lg hover:bg-[#FEF2F2] dark:hover:bg-[#DC2626]/10 text-[#DC2626] transition-colors" title="Supprimer">
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {meta && meta.last_page > 1 && (
          <div className="px-4 py-3 border-t border-[#E2E8F0] dark:border-white/8 flex items-center justify-between text-xs text-[#64748B] dark:text-white/40">
            <span>{meta.from}–{meta.to} sur {meta.total}</span>
            <div className="flex items-center gap-1">
              <button disabled={meta.current_page === 1}
                onClick={() => setFilters(f => ({ ...f, page: f.page - 1 }))}
                className="p-1.5 rounded-lg hover:bg-[#F1F5F9] dark:hover:bg-white/5 disabled:opacity-40">
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="px-2">Page {meta.current_page} / {meta.last_page}</span>
              <button disabled={meta.current_page === meta.last_page}
                onClick={() => setFilters(f => ({ ...f, page: f.page + 1 }))}
                className="p-1.5 rounded-lg hover:bg-[#F1F5F9] dark:hover:bg-white/5 disabled:opacity-40">
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Modal Détail */}
      <AnimatePresence>
        {isDetailOpen && selected && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4"
            onClick={() => setIsDetailOpen(false)}>
            <motion.div initial={{ scale: 0.95 }} animate={{ scale: 1 }} exit={{ scale: 0.95 }}
              onClick={e => e.stopPropagation()}
              className="bg-white dark:bg-[#1E293B] rounded-2xl shadow-xl w-full max-w-md p-6 space-y-4">
              <div className="flex items-center justify-between">
                <h2 className="text-lg font-bold text-[#0F172A] dark:text-white flex items-center gap-2">
                  <DollarSign className="w-5 h-5 text-[#2563EB]" /> Détail #{selected.id}
                </h2>
                <button onClick={() => setIsDetailOpen(false)} className="p-1.5 rounded-lg hover:bg-[#F1F5F9] dark:hover:bg-white/5 text-[#64748B]">
                  <X className="w-4 h-4" />
                </button>
              </div>
              <div className="space-y-3 text-sm">
                {[
                  { label: 'Libellé', val: selected.libelle },
                  { label: 'Service', val: selected.service?.nom },
                  { label: 'Date', val: selected.date ? new Date(selected.date).toLocaleDateString('fr-FR') : '—' },
                  { label: 'Montant', val: fmt(selected.montant || 0) },
                  { label: 'Description', val: selected.description },
                  { label: 'Saisi par', val: selected.user?.name },
                ].map(({ label, val }) => (
                  <div key={label} className="flex justify-between gap-4 py-2 border-b border-[#F1F5F9] dark:border-white/5 last:border-0">
                    <span className="text-[#64748B] dark:text-white/50 font-medium">{label}</span>
                    <span className="text-[#0F172A] dark:text-white text-right">{val || '—'}</span>
                  </div>
                ))}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Modal Formulaire */}
      <AnimatePresence>
        {isFormOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4"
            onClick={() => setIsFormOpen(false)}>
            <motion.div initial={{ scale: 0.95 }} animate={{ scale: 1 }} exit={{ scale: 0.95 }}
              onClick={e => e.stopPropagation()}
              className="bg-white dark:bg-[#1E293B] rounded-2xl shadow-xl w-full max-w-lg p-6">
              <div className="flex items-center justify-between mb-5">
                <h2 className="text-lg font-bold text-[#0F172A] dark:text-white">
                  {formMode === 'create' ? 'Nouveau service rémunéré' : 'Modifier le service'}
                </h2>
                <button onClick={() => setIsFormOpen(false)} className="p-1.5 rounded-lg hover:bg-[#F1F5F9] dark:hover:bg-white/5 text-[#64748B]">
                  <X className="w-4 h-4" />
                </button>
              </div>

              {formErrors && (
                <div className="mb-4 p-3 bg-[#FEF2F2] border border-[#FECACA] rounded-lg text-xs text-[#DC2626]">
                  {typeof formErrors === 'string' ? formErrors : Object.values(formErrors).flat().join(' · ')}
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="block text-xs font-medium text-[#374151] dark:text-white/70 mb-1">Libellé *</label>
                  <input type="text" required value={formData.libelle}
                    onChange={e => setFormData(f => ({ ...f, libelle: e.target.value }))}
                    className="w-full px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB]"
                    placeholder="Ex: Garde de nuit, Escorte VIP…" />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-[#374151] dark:text-white/70 mb-1">Service *</label>
                    <select required value={formData.service_id}
                      onChange={e => setFormData(f => ({ ...f, service_id: e.target.value }))}
                      className="w-full px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB]">
                      <option value="">— Sélectionner —</option>
                      {services.map(s => <option key={s.id} value={s.id}>{s.nom}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-[#374151] dark:text-white/70 mb-1">Date *</label>
                    <input type="date" required value={formData.date}
                      onChange={e => setFormData(f => ({ ...f, date: e.target.value }))}
                      className="w-full px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB]" />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-medium text-[#374151] dark:text-white/70 mb-1">Montant (CFA) *</label>
                  <input type="number" required min="0" step="100" value={formData.montant}
                    onChange={e => setFormData(f => ({ ...f, montant: e.target.value }))}
                    className="w-full px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB]"
                    placeholder="Ex: 50000" />
                </div>

                <div>
                  <label className="block text-xs font-medium text-[#374151] dark:text-white/70 mb-1">Description</label>
                  <textarea rows={3} value={formData.description}
                    onChange={e => setFormData(f => ({ ...f, description: e.target.value }))}
                    className="w-full px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] resize-none"
                    placeholder="Observations…" />
                </div>

                <div className="flex justify-end gap-3 pt-2">
                  <button type="button" onClick={() => setIsFormOpen(false)}
                    className="px-4 py-2 rounded-xl border border-[#E2E8F0] dark:border-white/10 text-sm font-medium text-[#64748B] dark:text-white/60 hover:bg-[#F8FAFC] dark:hover:bg-white/5 transition-colors">
                    Annuler
                  </button>
                  <button type="submit" disabled={actionLoading}
                    className="px-4 py-2 rounded-xl bg-[#2563EB] hover:bg-[#1D4ED8] text-white text-sm font-medium transition-colors flex items-center gap-2 disabled:opacity-60">
                    {actionLoading && <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
                    {formMode === 'create' ? 'Créer' : 'Enregistrer'}
                  </button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

