import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Plus, Trash2, Edit, Eye, X, AlertCircle, CheckCircle, ShieldCheck, Mail, Phone, EyeOff, ChevronLeft, ChevronRight } from 'lucide-react';
import userService from '../services/userService';
import geoService from '../services/geoService';
import { useAuth } from '../contexts/AuthContext';

const ROLE_BADGE = {
  super_admin: 'bg-[#FEF2F2] text-[#DC2626] border-[#FECACA]',
  admin:       'bg-[#FFF7ED] text-[#C2410C] border-[#FED7AA]',
  superviseur: 'bg-[#EFF6FF] text-[#2563EB] border-[#BFDBFE]',
  agent:       'bg-[#F0FDF4] text-[#16A34A] border-[#BBF7D0]',
};
const roleBadgeCls = (rolesArr) =>
  ROLE_BADGE[rolesArr?.[0]?.name] || 'bg-[#F8FAFC] text-[#475569] border-[#E2E8F0]';

const inputCls = 'w-full px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white placeholder-[#94A3B8] dark:placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-colors';
const selectCls = 'w-full px-3 py-2 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/10 rounded-lg text-sm text-[#0F172A] dark:text-white focus:outline-none focus:ring-2 focus:ring-[#2563EB]/20 focus:border-[#2563EB] transition-colors';

function Toast({ toast }) {
  return (
    <AnimatePresence>
      {toast && (
        <motion.div
          initial={{ opacity: 0, y: -12 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -12 }}
          transition={{ duration: 0.18 }}
          className={`fixed top-4 right-4 z-[60] flex items-center gap-2.5 px-4 py-3 rounded-xl border shadow-lg text-sm font-medium ${
            toast.type === 'error'
              ? 'bg-[#FEF2F2] border-[#FECACA] text-[#DC2626]'
              : 'bg-[#F0FDF4] border-[#BBF7D0] text-[#16A34A]'
          }`}
        >
          {toast.type === 'error'
            ? <AlertCircle className="w-4 h-4 shrink-0" />
            : <CheckCircle className="w-4 h-4 shrink-0" />}
          {toast.message}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

function FormField({ label, error, children }) {
  return (
    <div>
      <label className="block text-xs font-semibold text-[#64748B] dark:text-white/50 mb-1.5 uppercase tracking-wide">{label}</label>
      {children}
      {error && <p className="text-[#DC2626] text-xs mt-1">{error[0]}</p>}
    </div>
  );
}

export default function Users() {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({ page: 1, per_page: 10 });
  const [meta, setMeta] = useState(null);

  const [selectedUser, setSelectedUser] = useState(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [formMode, setFormMode] = useState('create');

  const [roles, setRoles] = useState([]);
  const [services, setServices] = useState([]);
  const [showPassword, setShowPassword] = useState(false);
  const [formData, setFormData] = useState({
    name: '', email: '', password: '', telephone: '', service_id: '',
    role: '', is_active: true,
    read_scope_type: 'service', read_scope_id: '',
    write_scope_type: 'service', write_scope_id: '',
  });
  const setField = (k, v) => setFormData(p => ({ ...p, [k]: v }));

  const [formErrors, setFormErrors] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [toast, setToast] = useState(null);
  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const fetchUsers = useCallback(async () => {
    setLoading(true);
    try {
      const r = await userService.getAll({ ...filters, search: search || undefined });
      setUsers(r.data.data || []);
      setMeta(r.data.meta || null);
    } catch {
      showToast('Erreur lors de la récupération des utilisateurs', 'error');
    } finally {
      setLoading(false);
    }
  }, [filters, search]);

  useEffect(() => { fetchUsers(); }, [fetchUsers]);

  useEffect(() => {
    const fetchAux = async () => {
      try {
        const [resRoles, resServices] = await Promise.all([
          userService.getRoles(),
          geoService.getAllServices(),
        ]);
        setRoles(resRoles.data.data || resRoles.data || []);
        setServices(resServices.data.data || resServices.data || []);
      } catch (e) { console.error(e); }
    };
    fetchAux();
  }, []);

  const handlePageChange = (p) => {
    if (p >= 1 && p <= (meta?.last_page || 1)) setFilters(prev => ({ ...prev, page: p }));
  };

  const openCreate = () => {
    setFormMode('create');
    setFormData({
      name: '', email: '', password: '', telephone: '', service_id: '',
      role: roles[0]?.name || 'agent', is_active: true,
      read_scope_type: 'service', read_scope_id: '',
      write_scope_type: 'service', write_scope_id: '',
    });
    setFormErrors(null); setShowPassword(false); setIsFormOpen(true);
  };

  const openEdit = (u) => {
    setFormMode('edit'); setSelectedUser(u);
    setFormData({
      name: u.name || '', email: u.email || '', password: '',
      telephone: u.telephone || '', service_id: u.service_id || '',
      role: u.roles?.[0]?.name || 'agent', is_active: u.is_active ?? true,
      read_scope_type: u.read_scope_type || 'service', read_scope_id: u.read_scope_id || '',
      write_scope_type: u.write_scope_type || 'service', write_scope_id: u.write_scope_id || '',
    });
    setFormErrors(null); setShowPassword(false); setIsFormOpen(true);
  };

  const openDetail = async (u) => {
    try {
      const r = await userService.getOne(u.id);
      setSelectedUser(r.data.data || r.data || u);
    } catch { setSelectedUser(u); }
    setIsDetailOpen(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); setActionLoading(true); setFormErrors(null);
    const payload = {
      ...formData,
      is_active: formData.is_active ? 1 : 0,
      read_scope_id: formData.read_scope_id ? parseInt(formData.read_scope_id) : null,
      write_scope_id: formData.write_scope_id ? parseInt(formData.write_scope_id) : null,
    };
    if (formMode === 'edit' && !payload.password) delete payload.password;
    try {
      if (formMode === 'create') {
        const r = await userService.create(payload);
        const newId = r.data.data?.id || r.data?.id;
        if (newId && (payload.read_scope_id || payload.write_scope_id)) {
          await userService.update(newId, {
            read_scope_type: payload.read_scope_type, read_scope_id: payload.read_scope_id,
            write_scope_type: payload.write_scope_type, write_scope_id: payload.write_scope_id,
          });
        }
        showToast('Utilisateur créé avec succès !');
      } else {
        await userService.update(selectedUser.id, payload);
        showToast('Utilisateur mis à jour avec succès !');
      }
      setIsFormOpen(false); fetchUsers();
    } catch (err) {
      if (err.response?.status === 422) {
        setFormErrors(err.response.data.errors || err.response.data.message);
        showToast('Veuillez corriger les erreurs', 'error');
      } else {
        showToast(err.response?.data?.message || "Erreur d'enregistrement", 'error');
      }
    } finally { setActionLoading(false); }
  };

  const handleDelete = async (id) => {
    if (id === currentUser?.id) {
      showToast('Vous ne pouvez pas supprimer votre propre compte !', 'error'); return;
    }
    if (!window.confirm('Êtes-vous sûr de vouloir supprimer cet utilisateur ?')) return;
    try {
      await userService.delete(id);
      showToast('Utilisateur supprimé avec succès !'); fetchUsers();
    } catch (err) {
      showToast(err.response?.data?.message || 'Erreur de suppression', 'error');
    }
  };

  const SCOPE_TYPES = ['service', 'commune', 'departement', 'region', 'national'];

  return (
    <div className="space-y-6 max-w-[1400px]">
      <Toast toast={toast} />

      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#0F172A] dark:text-white">Utilisateurs & Habilitations</h1>
          <p className="text-sm text-[#64748B] dark:text-white/50 mt-1">Gestion des comptes, rôles et portées territoriales</p>
        </div>
        <button
          onClick={openCreate}
          className="inline-flex items-center gap-2 px-4 py-2.5 bg-[#2563EB] hover:bg-[#1D4ED8] text-white rounded-lg text-sm font-semibold transition-colors shrink-0"
        >
          <Plus className="w-4 h-4" />
          Ajouter un utilisateur
        </button>
      </div>

      {/* Toolbar */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl p-4">
        <div className="relative w-full sm:max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] dark:text-white/30" />
          <input
            type="text"
            placeholder="Rechercher par nom ou email…"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setFilters(p => ({ ...p, page: 1 })); }}
            className={`${inputCls} pl-9`}
          />
        </div>
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead>
              <tr className="border-b border-[#E2E8F0] dark:border-white/8 bg-[#F8FAFC] dark:bg-white/5">
                {['Identité', 'Email', 'Rôle', 'Scope lecture', 'État', 'Actions'].map((h, i) => (
                  <th key={h} className={`px-5 py-3 text-xs font-semibold text-[#64748B] dark:text-white/50 uppercase tracking-wide ${i === 5 ? 'text-right' : ''}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-[#F1F5F9] dark:divide-white/5">
              {loading ? (
                [...Array(5)].map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td className="px-5 py-4"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-28" /></td>
                    <td className="px-5 py-4"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-40" /></td>
                    <td className="px-5 py-4"><div className="h-5 bg-[#F1F5F9] dark:bg-white/5 rounded-full w-16" /></td>
                    <td className="px-5 py-4"><div className="h-5 bg-[#F1F5F9] dark:bg-white/5 rounded w-24" /></td>
                    <td className="px-5 py-4"><div className="h-4 bg-[#F1F5F9] dark:bg-white/5 rounded w-12" /></td>
                    <td className="px-5 py-4 text-right"><div className="h-7 bg-[#F1F5F9] dark:bg-white/5 rounded w-20 ml-auto" /></td>
                  </tr>
                ))
              ) : users.length === 0 ? (
                <tr>
                  <td colSpan="6" className="px-5 py-16 text-center text-sm text-[#94A3B8] dark:text-white/30">Aucun utilisateur trouvé.</td>
                </tr>
              ) : users.map(u => (
                <tr key={u.id} className="hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                  <td className="px-5 py-3.5 font-semibold text-[#0F172A] dark:text-white text-sm">{u.name}</td>
                  <td className="px-5 py-3.5 text-[#475569] dark:text-white/60 text-sm">{u.email}</td>
                  <td className="px-5 py-3.5">
                    <span className={`inline-flex px-2 py-0.5 rounded-full text-[10px] font-bold uppercase border ${roleBadgeCls(u.roles)}`}>
                      {u.roles?.[0]?.name || 'agent'}
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    <span className="font-mono text-xs bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 px-2 py-1 rounded-lg text-[#475569] dark:text-white/60 uppercase">
                      {u.read_scope_type || 'service'} ({u.read_scope_id || '—'})
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    <span className={`inline-flex items-center gap-1.5 text-xs font-semibold ${u.is_active ? 'text-[#16A34A]' : 'text-[#94A3B8] dark:text-white/30'}`}>
                      <span className={`w-1.5 h-1.5 rounded-full ${u.is_active ? 'bg-[#16A34A]' : 'bg-[#94A3B8]'}`} />
                      {u.is_active ? 'Actif' : 'Bloqué'}
                    </span>
                  </td>
                  <td className="px-5 py-3.5 text-right space-x-1">
                    <button onClick={() => openDetail(u)} className="p-1.5 text-[#94A3B8] hover:text-[#2563EB] hover:bg-[#EFF6FF] rounded-lg transition-colors" title="Détails">
                      <Eye className="w-4 h-4" />
                    </button>
                    <button onClick={() => openEdit(u)} className="p-1.5 text-[#94A3B8] hover:text-[#D97706] hover:bg-[#FFF7ED] rounded-lg transition-colors" title="Modifier">
                      <Edit className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(u.id)}
                      disabled={u.id === currentUser?.id}
                      className="p-1.5 text-[#94A3B8] hover:text-[#DC2626] hover:bg-[#FEF2F2] rounded-lg transition-colors disabled:opacity-30"
                      title="Supprimer"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {meta && meta.last_page > 1 && (
          <div className="px-5 py-3.5 border-t border-[#E2E8F0] dark:border-white/8 bg-[#F8FAFC] dark:bg-white/5 flex items-center justify-between">
            <span className="text-xs text-[#64748B] dark:text-white/50">
              {meta.from}–{meta.to} sur {meta.total} utilisateurs
            </span>
            <div className="flex items-center gap-2">
              <button
                onClick={() => handlePageChange(filters.page - 1)}
                disabled={filters.page === 1}
                className="p-1.5 rounded-lg border border-[#E2E8F0] dark:border-white/8 bg-white dark:bg-white/5 text-[#475569] dark:text-white/60 hover:bg-[#F1F5F9] dark:hover:bg-white/10 disabled:opacity-40 transition-colors"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="text-xs font-semibold text-[#0F172A] dark:text-white tabular-nums">
                {filters.page} / {meta.last_page}
              </span>
              <button
                onClick={() => handlePageChange(filters.page + 1)}
                disabled={filters.page === meta.last_page}
                className="p-1.5 rounded-lg border border-[#E2E8F0] dark:border-white/8 bg-white dark:bg-white/5 text-[#475569] dark:text-white/60 hover:bg-[#F1F5F9] dark:hover:bg-white/10 disabled:opacity-40 transition-colors"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Form modal */}
      <AnimatePresence>
        {isFormOpen && (
          <div className="fixed inset-0 z-50 bg-black/40 overflow-y-auto flex items-start justify-center p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.96, y: 12 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.96, y: 12 }}
              transition={{ duration: 0.18 }}
              className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl w-full max-w-3xl shadow-lg my-auto"
            >
              {/* Header */}
              <div className="px-6 py-4 border-b border-[#E2E8F0] dark:border-white/8 flex items-center justify-between bg-[#F8FAFC] dark:bg-white/5">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 bg-[#DBEAFE] rounded-xl flex items-center justify-center shadow-sm">
                    <ShieldCheck className="w-4 h-4 text-[#2563EB]" />
                  </div>
                  <p className="font-semibold text-[#0F172A] dark:text-white text-sm">
                    {formMode === 'create' ? 'Nouvel utilisateur' : 'Modifier le compte'}
                  </p>
                </div>
                <button onClick={() => setIsFormOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-lg text-[#64748B] dark:text-white/50 hover:bg-[#E2E8F0] dark:hover:bg-white/10 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="p-6 space-y-6">
                {/* Section 1: Identité */}
                <div className="space-y-4">
                  <p className="text-xs font-semibold text-[#94A3B8] dark:text-white/30 uppercase tracking-wider">Informations d'identité</p>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <FormField label="Nom complet *" error={formErrors?.name}>
                      <input type="text" required placeholder="Ex: Babacar Seck" value={formData.name} onChange={e => setField('name', e.target.value)} className={inputCls} />
                    </FormField>
                    <FormField label="Email unique *" error={formErrors?.email}>
                      <input type="email" required placeholder="b.seck@policesn.org" value={formData.email} onChange={e => setField('email', e.target.value)} className={inputCls} disabled={formMode === 'edit'} />
                    </FormField>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <FormField label={formMode === 'create' ? 'Mot de passe *' : 'Nouveau mot de passe'} error={formErrors?.password}>
                      <div className="relative">
                        <input
                          type={showPassword ? 'text' : 'password'}
                          placeholder={formMode === 'create' ? 'Min. 8 caractères' : 'Laisser vide si inchangé'}
                          required={formMode === 'create'}
                          value={formData.password}
                          onChange={e => setField('password', e.target.value)}
                          className={`${inputCls} pr-10 font-mono`}
                        />
                        <button type="button" onClick={() => setShowPassword(p => !p)} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#94A3B8] dark:text-white/30 hover:text-[#475569] dark:hover:text-white/60">
                          {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                        </button>
                      </div>
                    </FormField>
                    <FormField label="Téléphone">
                      <input type="text" placeholder="+221 77 000 00 00" value={formData.telephone} onChange={e => setField('telephone', e.target.value)} className={`${inputCls} font-mono`} />
                    </FormField>
                    <FormField label="Unité d'affectation">
                      <select value={formData.service_id} onChange={e => setField('service_id', e.target.value)} className={selectCls}>
                        <option value="">Aucune affectation</option>
                        {services.map(s => <option key={s.id} value={s.id}>{s.nom}</option>)}
                      </select>
                    </FormField>
                  </div>
                </div>

                <div className="border-t border-[#E2E8F0] dark:border-white/8" />

                {/* Section 2: Rôles & Scopes */}
                <div className="space-y-4">
                  <p className="text-xs font-semibold text-[#94A3B8] dark:text-white/30 uppercase tracking-wider">Rôles & Permissions territoriales</p>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <FormField label="Rôle système *" error={formErrors?.role}>
                      <select required value={formData.role} onChange={e => setField('role', e.target.value)} className={selectCls}>
                        <option value="">Sélectionner un rôle…</option>
                        {roles.map(r => <option key={r.id} value={r.name}>{r.name}</option>)}
                      </select>
                    </FormField>
                    <div className="flex items-end pb-1">
                      <label className="flex items-center gap-2.5 text-sm text-[#475569] dark:text-white/60 cursor-pointer">
                        <input
                          type="checkbox"
                          checked={formData.is_active}
                          onChange={e => setField('is_active', e.target.checked)}
                          className="w-4 h-4 rounded border-[#E2E8F0] text-[#2563EB] focus:ring-[#2563EB]/20"
                        />
                        <span className="font-medium">Compte actif</span>
                      </label>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2">
                    {[
                      { label: 'Habilitation de LECTURE', scopeType: 'read_scope_type', scopeId: 'read_scope_id' },
                      { label: "Habilitation d'ÉCRITURE", scopeType: 'write_scope_type', scopeId: 'write_scope_id' },
                    ].map(({ label, scopeType, scopeId }) => (
                      <div key={label} className="space-y-2">
                        <p className="text-xs font-semibold text-[#64748B] dark:text-white/50 uppercase tracking-wide">{label}</p>
                        <div className="grid grid-cols-2 gap-2">
                          <div>
                            <label className="block text-[10px] text-[#94A3B8] dark:text-white/30 font-semibold mb-1 uppercase">Type</label>
                            <select value={formData[scopeType]} onChange={e => setField(scopeType, e.target.value)} className={selectCls}>
                              {SCOPE_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                            </select>
                          </div>
                          <div>
                            <label className="block text-[10px] text-[#94A3B8] dark:text-white/30 font-semibold mb-1 uppercase">ID ciblé</label>
                            <input type="number" placeholder="Ex: 5" value={formData[scopeId]} onChange={e => setField(scopeId, e.target.value)} className={`${inputCls} font-mono`} />
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="flex justify-end gap-3 pt-2 border-t border-[#E2E8F0] dark:border-white/8">
                  <button type="button" onClick={() => setIsFormOpen(false)} className="px-4 py-2 border border-[#E2E8F0] dark:border-white/8 rounded-lg text-sm font-medium text-[#475569] dark:text-white/60 hover:bg-[#F8FAFC] dark:hover:bg-white/3 transition-colors">
                    Annuler
                  </button>
                  <button type="submit" disabled={actionLoading} className="px-5 py-2 bg-[#2563EB] hover:bg-[#1D4ED8] text-white rounded-lg text-sm font-semibold disabled:opacity-50 transition-colors">
                    {actionLoading ? 'Enregistrement…' : formMode === 'create' ? 'Créer le compte' : 'Enregistrer'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Detail modal */}
      <AnimatePresence>
        {isDetailOpen && selectedUser && (
          <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.96 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.96 }}
              transition={{ duration: 0.18 }}
              className="bg-white dark:bg-[#1E293B] border border-[#E2E8F0] dark:border-white/8 rounded-xl w-full max-w-md shadow-lg"
            >
              <div className="px-6 py-4 border-b border-[#E2E8F0] dark:border-white/8 flex items-center justify-between bg-[#F8FAFC] dark:bg-white/5">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 bg-[#DBEAFE] rounded-xl flex items-center justify-center shadow-sm">
                    <ShieldCheck className="w-4 h-4 text-[#2563EB]" />
                  </div>
                  <div>
                    <p className="font-semibold text-[#0F172A] dark:text-white text-sm">{selectedUser.name}</p>
                    <span className={`inline-flex px-2 py-0.5 rounded-full text-[10px] font-bold uppercase border ${roleBadgeCls(selectedUser.roles)}`}>
                      {selectedUser.roles?.[0]?.name || 'agent'}
                    </span>
                  </div>
                </div>
                <button onClick={() => setIsDetailOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-lg text-[#64748B] dark:text-white/50 hover:bg-[#E2E8F0] dark:hover:bg-white/10 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="p-6 space-y-4">
                <div className="p-4 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg space-y-2.5 text-sm">
                  <div className="flex items-center gap-2 text-[#475569] dark:text-white/60">
                    <Mail className="w-4 h-4 text-[#94A3B8] dark:text-white/30" />
                    <span className="font-medium">{selectedUser.email}</span>
                  </div>
                  {selectedUser.telephone && (
                    <div className="flex items-center gap-2 text-[#475569] dark:text-white/60 font-mono">
                      <Phone className="w-4 h-4 text-[#94A3B8] dark:text-white/30" />
                      <span>{selectedUser.telephone}</span>
                    </div>
                  )}
                </div>

                <div className="p-4 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg space-y-3">
                  <p className="text-[10px] text-[#94A3B8] dark:text-white/30 font-semibold uppercase tracking-wider">Scope territorial</p>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <p className="text-[10px] text-[#94A3B8] dark:text-white/30 uppercase font-semibold mb-1">Lecture</p>
                      <span className="px-2 py-1 bg-[#EFF6FF] text-[#2563EB] border border-[#BFDBFE] rounded-lg text-xs font-bold block text-center uppercase">
                        {selectedUser.read_scope_type || 'service'} ({selectedUser.read_scope_id || '—'})
                      </span>
                    </div>
                    <div>
                      <p className="text-[10px] text-[#94A3B8] dark:text-white/30 uppercase font-semibold mb-1">Écriture</p>
                      <span className="px-2 py-1 bg-[#FFF7ED] text-[#C2410C] border border-[#FED7AA] rounded-lg text-xs font-bold block text-center uppercase">
                        {selectedUser.write_scope_type || 'service'} ({selectedUser.write_scope_id || '—'})
                      </span>
                    </div>
                  </div>
                </div>

                {selectedUser.service && (
                  <div className="p-4 bg-[#F8FAFC] dark:bg-white/5 border border-[#E2E8F0] dark:border-white/8 rounded-lg">
                    <p className="text-[10px] text-[#94A3B8] dark:text-white/30 font-semibold uppercase tracking-wider mb-1">Unité d'affectation</p>
                    <p className="font-semibold text-[#0F172A] dark:text-white">{selectedUser.service.nom}</p>
                  </div>
                )}
              </div>

              <div className="px-6 py-4 border-t border-[#E2E8F0] dark:border-white/8 bg-[#F8FAFC] dark:bg-white/5 flex justify-end">
                <button onClick={() => setIsDetailOpen(false)} className="px-5 py-2 bg-[#0F172A] dark:bg-white/10 hover:bg-[#1E293B] dark:hover:bg-white/20 text-white rounded-lg text-xs font-semibold transition-colors">
                  Fermer
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

