                          Lieu: {selectedVictime.accident.lieu}
                        </p>
                      </div>
                    ) : (
                      <span className="text-xs text-[#94A3B8] dark:text-white/30 italic">Aucune information détaillée de dossier chargée.</span>
                    )}
                  </div>
                </div>
              </motion.div>
            </div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

