const PRENOMS = ['Mamadou','Ibrahima','Cheikh','Ousmane','Abdoulaye','Fatou','Aminata','Mariama','Aïssatou','Ndeye'];
const NOMS    = ['Diallo','Ndiaye','Fall','Sow','Ba','Diop','Sarr','Gueye','Mbaye','Ndour'];
const GRADES  = ['Commissaire','Commandant','Lieutenant','Sergent-chef','Brigadier-chef','Gardien de la paix'];
const STATUTS = ['Actif','Actif','Actif','Mission','Inactif'];
const SERVICES_NOM = ['Commissariat Central de Dakar','Brigade de Thiès','Post de Saint-Louis','Commissariat de Ziguinchor','Brigade de Kaolack'];
const ZONES   = ['Dakar','Thiès','Rufisque','Pikine','Kaolack','Saint-Louis','Ziguinchor','Tambacounda'];
const NOTIF_MSGS = [
  'Nouvelle infraction enregistrée – Commissariat de Dakar',
  'Rapport hebdomadaire disponible',
  'Mise à jour du système effectuée',
  'Nouvel accident corporel signalé – Zone Thiès',
  'Synchronisation des données terminée',
  'Alerte : augmentation des infractions cette semaine',
];

function rnd(arr)  { return arr[Math.floor(Math.random() * arr.length)]; }
function rndInt(a, b) { return Math.floor(Math.random() * (b - a + 1)) + a; }
function dateStr(yearsAgo = 0, daysOffset = 0) {
  const d = new Date();
  d.setFullYear(d.getFullYear() - yearsAgo);
  d.setDate(d.getDate() - daysOffset);
  return d.toISOString().split('T')[0];
}

export function mockPersonnel(n = 12) {
  return Array.from({ length: n }, (_, i) => ({
    id: 1000 + i,
    ccap: `SN${String(2000 + i).padStart(6,'0')}`,
    prenom: rnd(PRENOMS),
    nom: rnd(NOMS),
    grade: rnd(GRADES),
    sexe: i % 5 === 0 ? 'F' : 'M',
    telephone: `+221 7${rndInt(7,8)} ${rndInt(100,999)} ${rndInt(10,99)} ${rndInt(10,99)}`,
    statut: STATUTS[i % STATUTS.length],
    service: { id: (i % 5) + 1, nom: SERVICES_NOM[i % SERVICES_NOM.length] },
    service_id: (i % 5) + 1,
    anciennete: rndInt(1, 25),
    date_entree_corps: dateStr(rndInt(1, 25)),
    date_naissance: dateStr(rndInt(28, 50)),
    lieu_naissance: rnd(ZONES),
    situation_matrimoniale: i % 3 === 0 ? 'Célibataire' : 'Marié(e)',
    sanction: '',
    _isMock: true,
  }));
}

export function mockImmigration(n = 10) {
  const types = ['Reconduite à la frontière','Mise en demeure','Arrestation','Reconduction'];
  return Array.from({ length: n }, (_, i) => {
    const h = rndInt(3, 40), f = rndInt(1, 15), e = rndInt(0, 10);
    const sn = rndInt(1, h + f + e), et = (h + f + e) - sn;
    return {
      id: 2000 + i,
      date: dateStr(0, rndInt(0, 365)),
      nombre_interpellation: h + f + e,
      nombre_hommes: h,
      nombre_femmes: f,
      nombre_enfants: e,
      nombre_maries: rndInt(0, Math.floor((h + f) / 2)),
      nombre_celibataires: rndInt(1, h + f),
      nombre_senegalais: sn,
      nombre_etrangers: et,
      zone_depart: rnd(['Gambie','Mali','Guinée','Mauritanie','Sénégal']),
      zone_arrivee_prevue: rnd(['Espagne','France','Italie','Maroc']),
      service: { id: (i % 5) + 1, nom: SERVICES_NOM[i % SERVICES_NOM.length] },
      service_id: (i % 5) + 1,
      type: rnd(types),
      commune: { nom: rnd(ZONES), departement: { region_id: (i % 14) + 1 } },
      _isMock: true,
    };
  });
}

